BOOK.add({
  subject: "gs",
  id: "gs-23",
  title: "खेल एवं पुरस्कार — खेल जगत, ट्रॉफियाँ, ओलंपिक, राष्ट्रीय व अंतरराष्ट्रीय पुरस्कार (विस्तृत अभ्यास)",
  notes: "\n    <div class=\"tip\">यह अध्याय \"समसामयिक घटनाएँ एवं खेल\" का स्थैतिक (स्थायी) भाग है। इसमें केवल 2025 तक के निश्चित परिणाम हैं। 2026 के परिणामों के लिए करेंट अफेयर्स पुस्तक देखें।</div>\n\n    <h3>1. ग्रीष्मकालीन ओलंपिक — आयोजन स्थल</h3>\n    <table>\n      <tr><th>वर्ष</th><th>शहर</th><th>वर्ष</th><th>शहर</th></tr>\n      <tr><td>1896</td><td>एथेंस (प्रथम आधुनिक)</td><td>1960</td><td>रोम</td></tr>\n      <tr><td>1900</td><td>पेरिस (महिलाओं की पहली भागीदारी)</td><td>1964</td><td>टोक्यो (एशिया में प्रथम)</td></tr>\n      <tr><td>1904</td><td>सेंट लुइस (USA)</td><td>1968</td><td>मेक्सिको सिटी</td></tr>\n      <tr><td>1908</td><td>लंदन</td><td>1972</td><td>म्यूनिख</td></tr>\n      <tr><td>1912</td><td>स्टॉकहोम</td><td>1976</td><td>मॉन्ट्रियल</td></tr>\n      <tr><td>1920</td><td>एंटवर्प (ओलंपिक ध्वज पहली बार)</td><td>1980</td><td>मॉस्को</td></tr>\n      <tr><td>1924</td><td>पेरिस</td><td>1984</td><td>लॉस एंजिलिस</td></tr>\n      <tr><td>1928</td><td>एम्सटर्डम (ओलंपिक ज्योति)</td><td>1988</td><td>सियोल</td></tr>\n      <tr><td>1932</td><td>लॉस एंजिलिस</td><td>1992</td><td>बार्सिलोना</td></tr>\n      <tr><td>1936</td><td>बर्लिन (मशाल रिले आरंभ)</td><td>1996</td><td>अटलांटा</td></tr>\n      <tr><td>1948</td><td>लंदन</td><td>2000</td><td>सिडनी</td></tr>\n      <tr><td>1952</td><td>हेलसिंकी</td><td>2004</td><td>एथेंस</td></tr>\n      <tr><td>1956</td><td>मेलबर्न (घुड़सवारी स्टॉकहोम में)</td><td>2008</td><td>बीजिंग</td></tr>\n      <tr><td colspan=\"2\">1916, 1940, 1944 — विश्व युद्धों के कारण रद्द</td><td>2012 / 2016</td><td>लंदन / रियो डी जनेरियो</td></tr>\n      <tr><td colspan=\"2\">2020 (आयोजन 2021) — टोक्यो; 2024 — पेरिस</td><td>2028 / 2032</td><td>लॉस एंजिलिस / ब्रिस्बेन</td></tr>\n    </table>\n    <p>लंदन ने तीन बार (1908, 1948, 2012) और पेरिस ने तीन बार (1900, 1924, 2024) मेज़बानी की। बीजिंग ग्रीष्म (2008) और शीत (2022) दोनों ओलंपिक कराने वाला पहला शहर है।</p>\n\n    <h3>2. भारत के ओलंपिक पदक (1900–2024) — कुल 41</h3>\n    <table>\n      <tr><th>ओलंपिक</th><th>पदक विजेता (स्पर्धा)</th></tr>\n      <tr><td>1900 पेरिस</td><td>नॉर्मन प्रिचर्ड — 2 रजत (200 मी दौड़, 200 मी बाधा दौड़)</td></tr>\n      <tr><td>1928–1936</td><td>हॉकी स्वर्ण (एम्सटर्डम, लॉस एंजिलिस, बर्लिन)</td></tr>\n      <tr><td>1948 लंदन</td><td>हॉकी स्वर्ण (फ़ाइनल में ग्रेट ब्रिटेन को 4-0) — स्वतंत्र भारत का पहला स्वर्ण</td></tr>\n      <tr><td>1952 हेलसिंकी</td><td>हॉकी स्वर्ण; के. डी. जाधव — कुश्ती (बैंटमवेट) कांस्य</td></tr>\n      <tr><td>1956 मेलबर्न</td><td>हॉकी स्वर्ण (फ़ाइनल में पाकिस्तान को 1-0)</td></tr>\n      <tr><td>1960 रोम</td><td>हॉकी रजत</td></tr>\n      <tr><td>1964 टोक्यो</td><td>हॉकी स्वर्ण (फ़ाइनल में पाकिस्तान को 1-0)</td></tr>\n      <tr><td>1968, 1972</td><td>हॉकी कांस्य (मेक्सिको सिटी, म्यूनिख)</td></tr>\n      <tr><td>1980 मॉस्को</td><td>हॉकी स्वर्ण (फ़ाइनल में स्पेन को 4-3) — 8वाँ व अंतिम हॉकी स्वर्ण</td></tr>\n      <tr><td>1996 अटलांटा</td><td>लिएंडर पेस — टेनिस एकल कांस्य</td></tr>\n      <tr><td>2000 सिडनी</td><td>कर्णम मल्लेश्वरी — भारोत्तोलन (69 किग्रा) कांस्य</td></tr>\n      <tr><td>2004 एथेंस</td><td>राज्यवर्धन सिंह राठौड़ — डबल ट्रैप रजत</td></tr>\n      <tr><td>2008 बीजिंग</td><td>अभिनव बिंद्रा — 10 मी एयर राइफ़ल स्वर्ण; सुशील कुमार — कुश्ती 66 किग्रा कांस्य; विजेंदर सिंह — मुक्केबाज़ी 75 किग्रा कांस्य</td></tr>\n      <tr><td>2012 लंदन (6)</td><td>विजय कुमार — 25 मी रैपिड फ़ायर पिस्टल रजत; सुशील कुमार — 66 किग्रा रजत; गगन नारंग — 10 मी एयर राइफ़ल कांस्य; साइना नेहवाल — बैडमिंटन कांस्य; मैरी कॉम — 51 किग्रा कांस्य; योगेश्वर दत्त — 60 किग्रा कांस्य</td></tr>\n      <tr><td>2016 रियो (2)</td><td>पी. वी. सिंधु — बैडमिंटन रजत; साक्षी मलिक — कुश्ती 58 किग्रा कांस्य</td></tr>\n      <tr><td>2020 टोक्यो (7)</td><td>नीरज चोपड़ा — भाला स्वर्ण (87.58 मी); मीराबाई चानू — 49 किग्रा रजत; रवि दहिया — 57 किग्रा रजत; लवलीना बोरगोहेन — मुक्केबाज़ी कांस्य; पी. वी. सिंधु — कांस्य; बजरंग पूनिया — 65 किग्रा कांस्य; पुरुष हॉकी — कांस्य (जर्मनी को 5-4)</td></tr>\n      <tr><td>2024 पेरिस (6)</td><td>नीरज चोपड़ा — रजत (89.45 मी); मनु भाकर — 10 मी एयर पिस्टल कांस्य; मनु भाकर–सरबजोत सिंह — मिश्रित टीम कांस्य; स्वप्निल कुसाले — 50 मी राइफ़ल थ्री पोज़ीशन कांस्य; पुरुष हॉकी — कांस्य (स्पेन को 2-1); अमन सहरावत — 57 किग्रा कांस्य</td></tr>\n    </table>\n    <p>भारत के 10 ओलंपिक स्वर्ण = 8 हॉकी + अभिनव बिंद्रा (2008) + नीरज चोपड़ा (2020)। हॉकी में कुल 13 पदक (8 स्वर्ण, 1 रजत, 4 कांस्य)। 1976, 1984, 1988, 1992 में भारत को कोई पदक नहीं मिला।</p>\n\n    <h3>3. एशियाई खेल एवं राष्ट्रमंडल खेल — मेज़बान</h3>\n    <table>\n      <tr><th>एशियाई खेल</th><th>मेज़बान</th><th>राष्ट्रमंडल खेल</th><th>मेज़बान</th></tr>\n      <tr><td>1951</td><td>नई दिल्ली</td><td>1930</td><td>हैमिल्टन (कनाडा)</td></tr>\n      <tr><td>1954</td><td>मनीला</td><td>1934</td><td>लंदन (भारत की पहली भागीदारी)</td></tr>\n      <tr><td>1958</td><td>टोक्यो</td><td>1958</td><td>कार्डिफ़ (मिल्खा सिंह का स्वर्ण)</td></tr>\n      <tr><td>1962</td><td>जकार्ता</td><td>1966</td><td>किंग्स्टन (जमैका)</td></tr>\n      <tr><td>1966, 1970, 1978, 1998</td><td>बैंकॉक (सर्वाधिक 4 बार)</td><td>1970, 1986</td><td>एडिनबर्ग</td></tr>\n      <tr><td>1974</td><td>तेहरान</td><td>1982</td><td>ब्रिस्बेन</td></tr>\n      <tr><td>1982</td><td>नई दिल्ली (शुभंकर \"अप्पू\")</td><td>1998</td><td>कुआलालंपुर (एशिया में प्रथम; क्रिकेट शामिल)</td></tr>\n      <tr><td>1986 / 1990</td><td>सियोल / बीजिंग (कबड्डी शामिल)</td><td>2002</td><td>मैनचेस्टर</td></tr>\n      <tr><td>1994 / 2002</td><td>हिरोशिमा / बुसान</td><td>2006</td><td>मेलबर्न</td></tr>\n      <tr><td>2006 / 2010</td><td>दोहा / ग्वांगझू (क्रिकेट शामिल)</td><td>2010</td><td>नई दिल्ली (भारत 101 पदक, दूसरा स्थान)</td></tr>\n      <tr><td>2014 / 2018</td><td>इंचियोन / जकार्ता–पालेमबांग</td><td>2014 / 2018</td><td>ग्लासगो / गोल्ड कोस्ट</td></tr>\n      <tr><td>2022 (आयोजन 2023)</td><td>हांगझोउ (भारत 107 पदक)</td><td>2022</td><td>बर्मिंघम (महिला T20 क्रिकेट)</td></tr>\n    </table>\n\n    <h3>4. क्रिकेट — ICC प्रतियोगिताओं के विजेता</h3>\n    <table>\n      <tr><th>पुरुष एकदिवसीय विश्व कप</th><th>विजेता (फ़ाइनल स्थल)</th></tr>\n      <tr><td>1975, 1979</td><td>वेस्ट इंडीज़ (दोनों लॉर्ड्स)</td></tr>\n      <tr><td>1983</td><td>भारत — कप्तान कपिल देव (लॉर्ड्स)</td></tr>\n      <tr><td>1987</td><td>ऑस्ट्रेलिया — एलन बॉर्डर (ईडन गार्डन्स, कोलकाता)</td></tr>\n      <tr><td>1992</td><td>पाकिस्तान — इमरान ख़ान (MCG, मेलबर्न)</td></tr>\n      <tr><td>1996</td><td>श्रीलंका — अर्जुन रणतुंगा (लाहौर)</td></tr>\n      <tr><td>1999, 2003, 2007</td><td>ऑस्ट्रेलिया — स्टीव वॉ (लॉर्ड्स); रिकी पोंटिंग (जोहान्सबर्ग में भारत को हराया); पोंटिंग (ब्रिजटाउन)</td></tr>\n      <tr><td>2011</td><td>भारत — एम. एस. धोनी (वानखेड़े, मुंबई; श्रीलंका को हराया)</td></tr>\n      <tr><td>2015</td><td>ऑस्ट्रेलिया — माइकल क्लार्क (MCG; न्यूज़ीलैंड को हराया)</td></tr>\n      <tr><td>2019</td><td>इंग्लैंड — इयोन मॉर्गन (लॉर्ड्स; सुपर ओवर टाई के बाद बाउंड्री गणना से)</td></tr>\n      <tr><td>2023</td><td>ऑस्ट्रेलिया — पैट कमिंस (अहमदाबाद; भारत को हराया) — छठा ख़िताब</td></tr>\n    </table>\n    <table>\n      <tr><th>पुरुष T20 विश्व कप</th><th>विजेता</th><th>चैंपियंस ट्रॉफी</th><th>विजेता</th></tr>\n      <tr><td>2007</td><td>भारत (जोहान्सबर्ग; पाकिस्तान को हराया)</td><td>1998</td><td>दक्षिण अफ़्रीका (ढाका; \"ICC नॉकआउट\")</td></tr>\n      <tr><td>2009</td><td>पाकिस्तान (लॉर्ड्स)</td><td>2000</td><td>न्यूज़ीलैंड (नैरोबी; भारत को हराया)</td></tr>\n      <tr><td>2010</td><td>इंग्लैंड (ब्रिजटाउन) — पहला ICC ख़िताब</td><td>2002</td><td>भारत–श्रीलंका संयुक्त (कोलंबो, वर्षा)</td></tr>\n      <tr><td>2012</td><td>वेस्ट इंडीज़ (कोलंबो)</td><td>2004</td><td>वेस्ट इंडीज़</td></tr>\n      <tr><td>2014</td><td>श्रीलंका (ढाका; भारत को हराया)</td><td>2006, 2009</td><td>ऑस्ट्रेलिया</td></tr>\n      <tr><td>2016</td><td>वेस्ट इंडीज़ (कोलकाता) — दूसरी बार</td><td>2013</td><td>भारत (एजबेस्टन; इंग्लैंड को हराया)</td></tr>\n      <tr><td>2021</td><td>ऑस्ट्रेलिया (दुबई)</td><td>2017</td><td>पाकिस्तान (द ओवल; भारत को हराया)</td></tr>\n      <tr><td>2022</td><td>इंग्लैंड (MCG; पाकिस्तान को हराया)</td><td>2025</td><td>भारत (दुबई; न्यूज़ीलैंड को हराया)</td></tr>\n      <tr><td>2024</td><td>भारत (ब्रिजटाउन; दक्षिण अफ़्रीका को हराया)</td><td colspan=\"2\">विश्व टेस्ट चैंपियनशिप: 2021 न्यूज़ीलैंड (साउथैम्प्टन), 2023 ऑस्ट्रेलिया (द ओवल), 2025 दक्षिण अफ़्रीका (लॉर्ड्स)</td></tr>\n    </table>\n    <p>महिला एकदिवसीय विश्व कप: ऑस्ट्रेलिया 7 बार, इंग्लैंड 4 बार (1973, 1993, 2009, 2017), न्यूज़ीलैंड 2000, भारत 2025। भारत 2005 व 2017 में उपविजेता रहा। महिला T20 विश्व कप: ऑस्ट्रेलिया 6 बार; 2009 इंग्लैंड, 2016 वेस्ट इंडीज़, 2024 न्यूज़ीलैंड; भारत 2020 में उपविजेता (MCG)।</p>\n\n    <h3>5. फ़ुटबॉल एवं हॉकी विश्व कप</h3>\n    <table>\n      <tr><th>फ़ीफ़ा विश्व कप</th><th>विजेता (मेज़बान)</th><th>पुरुष हॉकी विश्व कप</th><th>विजेता (मेज़बान)</th></tr>\n      <tr><td>1930 / 1950</td><td>उरुग्वे (उरुग्वे / ब्राज़ील)</td><td>1971</td><td>पाकिस्तान (बार्सिलोना)</td></tr>\n      <tr><td>1934, 1938</td><td>इटली</td><td>1973</td><td>नीदरलैंड्स (भारत उपविजेता)</td></tr>\n      <tr><td>1954, 1974, 1990</td><td>पश्चिम जर्मनी</td><td>1975</td><td>भारत (कुआलालंपुर; पाकिस्तान को 2-1)</td></tr>\n      <tr><td>1958, 1962, 1970, 1994, 2002</td><td>ब्राज़ील (सर्वाधिक 5)</td><td>1978, 1982, 1994</td><td>पाकिस्तान (सर्वाधिक 4; 1982 मेज़बान बॉम्बे)</td></tr>\n      <tr><td>1966</td><td>इंग्लैंड (मेज़बान)</td><td>1986</td><td>ऑस्ट्रेलिया (लंदन)</td></tr>\n      <tr><td>1978, 1986, 2022</td><td>अर्जेंटीना</td><td>1990, 1998</td><td>नीदरलैंड्स (लाहौर, यूट्रेक्ट)</td></tr>\n      <tr><td>1982, 2006</td><td>इटली (कुल 4)</td><td>2002, 2006</td><td>जर्मनी</td></tr>\n      <tr><td>1998, 2018</td><td>फ़्रांस</td><td>2010, 2014</td><td>ऑस्ट्रेलिया (नई दिल्ली, द हेग)</td></tr>\n      <tr><td>2010</td><td>स्पेन (दक्षिण अफ़्रीका — अफ़्रीका में प्रथम)</td><td>2018</td><td>बेल्जियम (भुवनेश्वर)</td></tr>\n      <tr><td>2014</td><td>जर्मनी (ब्राज़ील; कुल 4)</td><td>2023</td><td>जर्मनी (भुवनेश्वर–राउरकेला)</td></tr>\n    </table>\n    <p>भारत ने पुरुष हॉकी विश्व कप की मेज़बानी 1982 (बॉम्बे), 2010 (नई दिल्ली), 2018 (भुवनेश्वर) व 2023 (भुवनेश्वर–राउरकेला) में की। भारत के हॉकी विश्व कप पदक: 1971 कांस्य, 1973 रजत, 1975 स्वर्ण।</p>\n\n    <h3>6. टेनिस ग्रैंड स्लैम</h3>\n    <table>\n      <tr><th>टूर्नामेंट</th><th>स्थल / सतह</th><th>महीना</th><th>पुरुष / महिला एकल ट्रॉफी</th></tr>\n      <tr><td>ऑस्ट्रेलियन ओपन (1905)</td><td>मेलबर्न पार्क / हार्ड</td><td>जनवरी</td><td>नॉर्मन ब्रूक्स चैलेंज कप / डैफ़्ने अखर्स्ट मेमोरियल कप</td></tr>\n      <tr><td>फ़्रेंच ओपन (1891)</td><td>रोलां गैरो, पेरिस / क्ले</td><td>मई–जून</td><td>कूप दे मूसक्वेतेयर / कूप सुज़ान लेंगलेन</td></tr>\n      <tr><td>विंबलडन (1877)</td><td>ऑल इंग्लैंड क्लब, लंदन / घास</td><td>जून–जुलाई</td><td>सिल्वर-गिल्ट कप / वीनस रोज़वाटर डिश</td></tr>\n      <tr><td>यूएस ओपन (1881)</td><td>फ़्लशिंग मेडोज़, न्यूयॉर्क / हार्ड</td><td>अगस्त–सितंबर</td><td>—</td></tr>\n    </table>\n    <p>भारतीय: महेश भूपति — पहला ग्रैंड स्लैम (1997 फ़्रेंच ओपन मिश्रित युगल)। सानिया मिर्ज़ा — ग्रैंड स्लैम जीतने वाली पहली भारतीय महिला (2009 ऑस्ट्रेलियन ओपन मिश्रित, भूपति के साथ); कुल 6 ग्रैंड स्लैम (3 महिला युगल + 3 मिश्रित)। लिएंडर पेस — 18 ग्रैंड स्लैम (8 पुरुष युगल + 10 मिश्रित)। रोहन बोपन्ना — पहला ग्रैंड स्लैम 2017 फ़्रेंच ओपन मिश्रित (गैब्रिएला डाब्रोव्स्की के साथ)। डेविस कप में भारत तीन बार फ़ाइनल में (1966, 1974, 1987) — कभी नहीं जीता; 1974 में रंगभेद के विरोध में दक्षिण अफ़्रीका से फ़ाइनल खेलने से इनकार।</p>\n\n    <h3>7. शतरंज</h3>\n    <table>\n      <tr><th>तथ्य</th><th>विवरण</th></tr>\n      <tr><td>भारत के ग्रैंडमास्टर (क्रम)</td><td>1. विश्वनाथन आनंद (1988) 2. दिव्येंदु बरुआ (1991) 3. प्रवीण थिप्से (1997)</td></tr>\n      <tr><td>महिला GM</td><td>1. कोनेरू हम्पी (2002) 2. द्रोणावल्ली हरिका 3. आर. वैशाली (2023) 4. दिव्या देशमुख (2025, महिला विश्व कप जीतकर)</td></tr>\n      <tr><td>आनंद के विश्व ख़िताब</td><td>2000 (FIDE नॉकआउट, फ़ाइनल तेहरान), 2007 (मेक्सिको सिटी टूर्नामेंट), 2008 (बॉन — क्रैमनिक), 2010 (सोफ़िया — टोपालोव), 2012 (मॉस्को — गेलफ़ंड)</td></tr>\n      <tr><td>आनंद की हार</td><td>2013 चेन्नई व 2014 सोची — मैग्नस कार्लसन से</td></tr>\n      <tr><td>डी. गुकेश</td><td>2024 सिंगापुर में डिंग लिरेन को हराकर 18वें विश्व चैंपियन, 18 वर्ष की आयु में — सबसे युवा</td></tr>\n      <tr><td>आनंद के उपनाम</td><td>\"लाइटनिंग किड\", \"टाइगर ऑफ़ मद्रास\"; 1987 में विश्व जूनियर चैंपियन बनने वाले पहले एशियाई</td></tr>\n    </table>\n\n    <h3>8. अन्य खेलों के भारतीय सितारे</h3>\n    <table>\n      <tr><th>खेल</th><th>उपलब्धियाँ</th></tr>\n      <tr><td>बैडमिंटन</td><td>प्रकाश पादुकोण — 1980 ऑल इंग्लैंड, 1983 विश्व चैंपियनशिप कांस्य (भारत का पहला विश्व पदक); पी. वी. सिंधु — विश्व चैंपियनशिप में 5 पदक, 2019 बासेल स्वर्ण; किदांबी श्रीकांत — अप्रैल 2018 में पुरुष विश्व नंबर 1, 2021 विश्व चैंपियनशिप रजत; सात्विकसाईराज–चिराग — 2023 एशियाई खेलों में भारत का पहला बैडमिंटन स्वर्ण</td></tr>\n      <tr><td>कुश्ती</td><td>सुशील कुमार — 2010 मॉस्को में भारत के पहले विश्व चैंपियन; गीता फोगाट — 2010 राष्ट्रमंडल खेल में स्वर्ण जीतने वाली पहली भारतीय महिला पहलवान; विनेश फोगाट — 2018 एशियाई खेलों में स्वर्ण जीतने वाली पहली भारतीय महिला पहलवान; दारा सिंह — \"रुस्तम-ए-हिंद\", राज्यसभा में मनोनीत पहले खिलाड़ी</td></tr>\n      <tr><td>निशानेबाज़ी</td><td>जसपाल राणा — 1994 हिरोशिमा एशियाई खेल स्वर्ण; तेजस्विनी सावंत — 2010 में विश्व चैंपियन बनने वाली पहली भारतीय महिला (50 मी राइफ़ल प्रोन); हिना सिद्धू — विश्व नंबर 1 बनने वाली पहली भारतीय पिस्टल निशानेबाज़; रुद्रांक्ष पाटिल — 2022 विश्व चैंपियन (10 मी एयर राइफ़ल)</td></tr>\n      <tr><td>एथलेटिक्स</td><td>कमलजीत संधू — 1970 बैंकॉक एशियाई खेलों में 400 मी स्वर्ण (एशियाई खेलों में व्यक्तिगत स्वर्ण जीतने वाली पहली भारतीय महिला); पी. टी. उषा — 1986 सियोल एशियाई खेलों में 4 स्वर्ण; नीरज चोपड़ा — 2016 U-20 विश्व रिकॉर्ड (86.48 मी), 2018 एशियाई व राष्ट्रमंडल स्वर्ण, 2022 डायमंड लीग ख़िताब (ज़्यूरिख) जीतने वाले पहले भारतीय; गुरबचन सिंह रंधावा — 1964 टोक्यो 110 मी बाधा दौड़ में 5वें</td></tr>\n      <tr><td>मुक्केबाज़ी</td><td>हवा सिंह — 1966 व 1970 एशियाई खेल हैवीवेट स्वर्ण; डिंको सिंह — 1998 बैंकॉक एशियाई खेल स्वर्ण; अमित पंघाल — 2019 विश्व चैंपियनशिप रजत (पहला भारतीय पुरुष)</td></tr>\n      <tr><td>पैरा खेल</td><td>मुरलीकांत पेटकर — भारत का पहला पैरालंपिक स्वर्ण (1972 हाइडेलबर्ग, तैराकी); दीपा मलिक — पैरालंपिक पदक जीतने वाली पहली भारतीय महिला (2016 रजत, गोला फेंक); भाविना पटेल — टोक्यो 2020 टेबल टेनिस रजत; प्रमोद भगत — टोक्यो 2020 बैडमिंटन SL3 स्वर्ण</td></tr>\n    </table>\n\n    <h3>9. खेल संस्थाएँ — मुख्यालय</h3>\n    <table>\n      <tr><th>संस्था</th><th>मुख्यालय</th><th>संस्था</th><th>मुख्यालय</th></tr>\n      <tr><td>FIBA (बास्केटबॉल)</td><td>मीस (स्विट्ज़रलैंड)</td><td>FIVB (वॉलीबॉल)</td><td>लुसाने</td></tr>\n      <tr><td>ITTF (टेबल टेनिस)</td><td>लुसाने</td><td>वर्ल्ड आर्चरी</td><td>लुसाने</td></tr>\n      <tr><td>UCI (साइक्लिंग)</td><td>एगल (स्विट्ज़रलैंड)</td><td>वर्ल्ड रग्बी</td><td>डबलिन</td></tr>\n      <tr><td>FIA (मोटर स्पोर्ट / फ़ॉर्मूला-1)</td><td>पेरिस</td><td>FIDE (शतरंज, स्थापना 1924 पेरिस)</td><td>लुसाने</td></tr>\n      <tr><td>BCCI (1928)</td><td>मुंबई</td><td>FIFA (1904)</td><td>ज़्यूरिख</td></tr>\n    </table>\n\n    <h3>10. प्रमुख स्टेडियम</h3>\n    <table>\n      <tr><th>स्टेडियम</th><th>शहर</th><th>स्टेडियम</th><th>शहर</th></tr>\n      <tr><td>राजीव गांधी अंतरराष्ट्रीय (उप्पल)</td><td>हैदराबाद</td><td>सवाई मानसिंह</td><td>जयपुर</td></tr>\n      <tr><td>भारत रत्न श्री अटल बिहारी वाजपेयी इकाना</td><td>लखनऊ</td><td>बरसापारा</td><td>गुवाहाटी</td></tr>\n      <tr><td>JSCA अंतरराष्ट्रीय</td><td>राँची</td><td>HPCA</td><td>धर्मशाला</td></tr>\n      <tr><td>ग्रीनफ़ील्ड अंतरराष्ट्रीय</td><td>तिरुवनंतपुरम</td><td>कलिंग स्टेडियम (हॉकी)</td><td>भुवनेश्वर</td></tr>\n      <tr><td>ब्रेबोर्न (CCI)</td><td>मुंबई</td><td>VCA जामठा</td><td>नागपुर</td></tr>\n      <tr><td>SCG</td><td>सिडनी</td><td>गाबा</td><td>ब्रिस्बेन</td></tr>\n      <tr><td>एजबेस्टन</td><td>बर्मिंघम</td><td>हेडिंग्ले</td><td>लीड्स</td></tr>\n      <tr><td>ट्रेंट ब्रिज</td><td>नॉटिंघम</td><td>न्यूलैंड्स</td><td>केप टाउन</td></tr>\n      <tr><td>केंसिंग्टन ओवल</td><td>ब्रिजटाउन (बारबाडोस)</td><td>सबीना पार्क</td><td>किंग्स्टन (जमैका)</td></tr>\n      <tr><td>गद्दाफ़ी स्टेडियम</td><td>लाहौर</td><td>शेर-ए-बांग्ला</td><td>मीरपुर (ढाका)</td></tr>\n      <tr><td>सैंटियागो बर्नब्यू</td><td>मैड्रिड</td><td>ऐनफ़ील्ड</td><td>लिवरपूल</td></tr>\n    </table>\n\n    <h3>11. ट्रॉफी / कप ↔ खेल (कम चर्चित)</h3>\n    <table>\n      <tr><th>खेल</th><th>ट्रॉफियाँ</th></tr>\n      <tr><td>क्रिकेट (घरेलू)</td><td>देवधर ट्रॉफी (अंतर-क्षेत्रीय एकदिवसीय), विजय मर्चेंट ट्रॉफी (अंडर-16), सी. के. नायडू ट्रॉफी (अंडर-23/25), रोहिंटन बारिया ट्रॉफी (अंतर-विश्वविद्यालय)</td></tr>\n      <tr><td>हॉकी</td><td>लेडी रतन टाटा ट्रॉफी व इंदिरा गांधी गोल्ड कप (महिला), सिंधिया गोल्ड कप (ग्वालियर), मुरुगप्पा गोल्ड कप (चेन्नई), बॉम्बे गोल्ड कप</td></tr>\n      <tr><td>फ़ुटबॉल</td><td>DCM ट्रॉफी (दिल्ली), बोरदोलोई ट्रॉफी (गुवाहाटी), सैत नागजी ट्रॉफी (केरल), स्टैफ़ोर्ड कप (बेंगलुरु), कोपा अमेरिका (दक्षिण अमेरिका), हेनरी डेलौने ट्रॉफी (यूरो), बैलन डी'ओर (व्यक्तिगत)</td></tr>\n      <tr><td>पोलो</td><td>एज़रा कप, पृथी सिंह कप, राधा मोहन कप</td></tr>\n      <tr><td>बैडमिंटन / टेबल टेनिस</td><td>इब्राहिम रहीमतुल्ला ट्रॉफी, अमृत दीवान कप (बैडमिंटन); जयलक्ष्मी कप, बार्ना-बेलैक कप (टेबल टेनिस)</td></tr>\n      <tr><td>गोल्फ़ / रग्बी / अन्य</td><td>कर्टिस कप (महिला शौकिया गोल्फ़), सोलहेम कप (महिला पेशेवर गोल्फ़), क्लैरेट जग (द ओपन), ग्रीन जैकेट (मास्टर्स); ब्लेडिस्लो कप (रग्बी — ऑस्ट्रेलिया–न्यूज़ीलैंड); विंस लोम्बार्डी ट्रॉफी (अमेरिकी फ़ुटबॉल — सुपर बाउल); लैरी ओ'ब्रायन ट्रॉफी (NBA बास्केटबॉल); येलो जर्सी (टूर डी फ़्रांस साइक्लिंग)</td></tr>\n    </table>\n\n    <h3>12. राष्ट्रीय खेल पुरस्कार</h3>\n    <table>\n      <tr><th>पुरस्कार</th><th>आरंभ</th><th>प्रथम / उल्लेखनीय</th></tr>\n      <tr><td>अर्जुन पुरस्कार</td><td>1961</td><td>खिलाड़ियों को; अर्जुन की कांस्य प्रतिमा</td></tr>\n      <tr><td>द्रोणाचार्य पुरस्कार</td><td>1985</td><td>प्रथम (1985): भालचंद्र भास्कर भागवत (कुश्ती), ओ. एम. नांबियार (एथलेटिक्स — पी. टी. उषा के कोच), ओम प्रकाश भारद्वाज (मुक्केबाज़ी)</td></tr>\n      <tr><td>खेल रत्न (1991–92)</td><td>2021 से मेजर ध्यानचंद खेल रत्न</td><td>प्रथम — विश्वनाथन आनंद; दूसरे — गीत सेठी (बिलियर्ड्स, 1992–93); पहली पैरा-एथलीट महिला — दीपा मलिक (2019)</td></tr>\n      <tr><td>ध्यानचंद पुरस्कार (आजीवन)</td><td>2002</td><td>2023 से \"अर्जुन पुरस्कार (आजीवन)\"</td></tr>\n      <tr><td>MAKA ट्रॉफी</td><td>1956–57</td><td>अंतर-विश्वविद्यालय खेलों में सर्वश्रेष्ठ विश्वविद्यालय</td></tr>\n    </table>\n\n    <h3>13. अन्य पुरस्कार — त्वरित तालिका</h3>\n    <table>\n      <tr><th>पुरस्कार</th><th>मुख्य तथ्य</th></tr>\n      <tr><td>भारत रत्न (2 जनवरी 1954)</td><td>प्रथम: सी. राजगोपालाचारी, एस. राधाकृष्णन, सी. वी. रमन (1954); प्रथम खिलाड़ी — सचिन तेंदुलकर (2014)</td></tr>\n      <tr><td>पद्म विभूषण — खिलाड़ी</td><td>विश्वनाथन आनंद (2007, प्रथम खिलाड़ी), सचिन तेंदुलकर (2008), मैरी कॉम (2020)</td></tr>\n      <tr><td>ज्ञानपीठ (हिन्दी)</td><td>सुमित्रानंदन पंत (1968, चिदंबरा), रामधारी सिंह दिनकर (1972, उर्वशी), अज्ञेय (1978), महादेवी वर्मा (1982, यामा), नरेश मेहता (1992), निर्मल वर्मा (1999), कुँवर नारायण (2005), अमरकांत व श्रीलाल शुक्ल (2009), केदारनाथ सिंह (2013), कृष्णा सोबती (2017), विनोद कुमार शुक्ल (2024)</td></tr>\n      <tr><td>दादा साहब फाल्के (1969)</td><td>देविका रानी (1969, प्रथम), बी. एन. सरकार (1970), पृथ्वीराज कपूर (1971, मरणोपरांत), सत्यजीत रे (1984), मजरूह सुल्तानपुरी (1993), शिवाजी गणेशन (1996), देव आनंद (2002), मृणाल सेन (2003), अडूर गोपालकृष्णन (2004), श्याम बेनेगल (2005), मन्ना डे (2007), प्राण (2012), गुलज़ार (2013), मनोज कुमार (2015), विनोद खन्ना (2017, मरणोपरांत)</td></tr>\n      <tr><td>रेमन मैग्सेसे (फ़िलीपींस)</td><td>विनोबा भावे (1958, प्रथम भारतीय), सी. डी. देशमुख (1959), मदर टेरेसा (1962), जयप्रकाश नारायण (1965), सत्यजीत रे (1967), एम. एस. सुब्बुलक्ष्मी (1974), अरुण शौरी (1982), आर. के. लक्ष्मण (1984), महाश्वेता देवी (1997), पी. साईनाथ (2007), टी. एम. कृष्णा (2016), सोनम वांगचुक व भरत वटवानी (2018)</td></tr>\n      <tr><td>बुकर</td><td>वी. एस. नायपॉल (1971), सलमान रुश्दी (1981, \"मिडनाइट्स चिल्ड्रन\" — 1993 \"बुकर ऑफ़ बुकर्स\" व 2008 \"बेस्ट ऑफ़ द बुकर\"), अरुंधति रॉय (1997), किरण देसाई (2006), अरविंद अडिगा (2008); अंतरराष्ट्रीय बुकर — गीतांजलि श्री (2022, \"रेत समाधि\"), बानू मुश्ताक (2025, \"हार्ट लैम्प\", कन्नड़)</td></tr>\n    </table>\n  ",
  extra: "\n    <h3>गहन तथ्य — जो सामान्य पाठक नहीं जानता</h3>\n    <ul>\n      <li><b>1932 लॉस एंजिलिस ओलंपिक</b> में भारत ने हॉकी में अमेरिका को 24-1 से हराया — यह ओलंपिक हॉकी की सबसे बड़ी जीत मानी जाती है।</li>\n      <li><b>लेस्ली क्लॉडियस</b> और <b>उधम सिंह</b> — दोनों ने ओलंपिक हॉकी में 3 स्वर्ण व 1 रजत (कुल 4 पदक) जीते। बलबीर सिंह (सीनियर) ने 1948, 1952, 1956 में स्वर्ण जीता; 1956 में वे कप्तान थे।</li>\n      <li><b>1956 मेलबर्न ओलंपिक</b> एकमात्र ओलंपिक है जिसकी एक स्पर्धा (घुड़सवारी) दूसरे देश (स्टॉकहोम, स्वीडन) में हुई — ऑस्ट्रेलिया के क्वारंटीन नियमों के कारण।</li>\n      <li><b>क्रिकेट विश्व कप 2019</b> का फ़ाइनल और उसका सुपर ओवर दोनों टाई रहे; इंग्लैंड \"अधिक बाउंड्री\" के नियम से जीता। बाद में ICC ने यह नियम हटा दिया।</li>\n      <li><b>चैंपियंस ट्रॉफी 2002</b> (कोलंबो) का फ़ाइनल दो बार वर्षा से बाधित हुआ और भारत–श्रीलंका संयुक्त विजेता घोषित हुए।</li>\n      <li><b>राष्ट्रमंडल खेलों में क्रिकेट</b> केवल दो बार: 1998 कुआलालंपुर (पुरुष एकदिवसीय, विजेता दक्षिण अफ़्रीका) और 2022 बर्मिंघम (महिला T20, विजेता ऑस्ट्रेलिया, भारत रजत)।</li>\n      <li><b>एशियाई खेलों में कबड्डी</b> (1990 से): भारत पुरुष वर्ग में 1990–2014 तक लगातार 7 स्वर्ण; 2018 में ईरान ने यह क्रम तोड़ा; 2023 हांगझोउ में भारत ने पुरुष व महिला दोनों स्वर्ण पुनः जीते।</li>\n      <li><b>पेले</b> तीन फ़ीफ़ा विश्व कप (1958, 1962, 1970) जीतने वाले एकमात्र खिलाड़ी हैं। विश्व कप में सर्वाधिक गोल — किलियन एम्बाप्पे (फ़्रांस, 22 गोल; 2026 विश्व कप में रिकॉर्ड बनाया); इससे पहले रिकॉर्ड मिरोस्लाव क्लोज़ (जर्मनी, 16) के नाम था।</li>\n      <li><b>मेक्सिको</b> ने दो फ़ीफ़ा विश्व कप (1970, 1986) की मेज़बानी की; 1986 में अर्जेंटीना (माराडोना) विजेता।</li>\n      <li><b>डेविस कप 1974:</b> भारत फ़ाइनल में पहुँचा, पर दक्षिण अफ़्रीका की रंगभेद नीति के विरोध में खेलने से इनकार किया — दक्षिण अफ़्रीका बिना खेले विजेता बना।</li>\n      <li><b>स्नूकर</b> का आविष्कार 1875 में जबलपुर (मध्य प्रदेश) में ब्रिटिश सैन्य अधिकारी नेविल चेम्बरलेन ने किया माना जाता है। <b>लॉन टेनिस</b> को 1873 में मेजर वॉल्टर विंगफ़ील्ड ने \"स्फ़ेरिस्टिके\" नाम से आरंभ किया। <b>जूडो</b> के जनक जिगोरो कानो (जापान, 1882)।</li>\n      <li><b>मिल्खा सिंह</b> को \"उड़न सिख\" की उपाधि 1960 में लाहौर की दौड़ (अब्दुल ख़ालिक़ को हराकर) के बाद पाकिस्तान के राष्ट्रपति अयूब ख़ान ने दी। मिल्खा ने 1958 टोक्यो एशियाई खेलों में 200 मी व 400 मी दोनों के स्वर्ण जीते।</li>\n      <li><b>पी. टी. उषा</b> ने 1986 सियोल एशियाई खेलों में 4 स्वर्ण (200 मी, 400 मी, 400 मी बाधा, 4×400 मी रिले) और 1 रजत जीता।</li>\n      <li><b>नीरज चोपड़ा:</b> 2016 बिडगोश (पोलैंड) में U-20 विश्व रिकॉर्ड 86.48 मी; 2018 जकार्ता एशियाई खेलों के उद्घाटन में भारत के ध्वजवाहक; 2022 यूजीन विश्व चैंपियनशिप रजत; 2023 बुडापेस्ट स्वर्ण। पेरिस 2024 में स्वर्ण पाकिस्तान के अरशद नदीम (92.97 मी, ओलंपिक रिकॉर्ड) ने जीता।</li>\n      <li><b>पी. वी. सिंधु के विश्व चैंपियनशिप पदक:</b> 2013 व 2014 कांस्य, 2017 व 2018 रजत, 2019 स्वर्ण — कुल 5। रियो 2016 फ़ाइनल में वे स्पेन की कैरोलिना मारिन से हारीं।</li>\n      <li><b>बजरंग पूनिया</b> विश्व कुश्ती चैंपियनशिप में 4 पदक (2013, 2018, 2019, 2022) जीतने वाले एकमात्र भारतीय पहलवान हैं।</li>\n      <li><b>शतरंज ओलंपियाड 2022</b> (मामल्लपुरम/चेन्नई) में भारत ने ओपन वर्ग (भारत-B) और महिला वर्ग (भारत-A) दोनों में कांस्य जीता; 2024 बुडापेस्ट में दोनों वर्गों में स्वर्ण।</li>\n      <li><b>टेनिस ट्रॉफियों के नाम:</b> विंबलडन महिला एकल ट्रॉफी \"वीनस रोज़वाटर डिश\"; फ़्रेंच ओपन पुरुष \"कूप दे मूसक्वेतेयर\" (चार फ़्रांसीसी \"मस्केटियर्स\" के नाम पर), महिला \"कूप सुज़ान लेंगलेन\"; ऑस्ट्रेलियन ओपन पुरुष \"नॉर्मन ब्रूक्स चैलेंज कप\"।</li>\n      <li><b>राफ़ेल नडाल</b> ने फ़्रेंच ओपन रिकॉर्ड 14 बार जीता; <b>मार्टिना नवरातिलोवा</b> ने विंबलडन महिला एकल रिकॉर्ड 9 बार; <b>मार्गरेट कोर्ट</b> के नाम सर्वाधिक 24 एकल ग्रैंड स्लैम (महिला); ओपन युग में <b>सेरेना विलियम्स</b> 23।</li>\n      <li><b>भारत रत्न + खेल:</b> 2011 में नियम बदलकर \"किसी भी क्षेत्र\" में मानवीय प्रयास को पात्र बनाया गया, तभी 2014 में सचिन को भारत रत्न संभव हुआ।</li>\n      <li><b>ट्रिक — ओलंपिक हॉकी स्वर्ण के फ़ाइनल प्रतिद्वंद्वी:</b> 1948 ब्रिटेन (4-0), 1952 नीदरलैंड्स (6-1), 1956 व 1964 पाकिस्तान (1-0), 1980 स्पेन (4-3)।</li>\n      <li><b>ट्रिक — T20 विश्व कप में भारत:</b> \"पहले (2007) पाकिस्तान को, नौवें (2024) दक्षिण अफ़्रीका को\" हराकर ख़िताब; 2014 में श्रीलंका से फ़ाइनल हारा।</li>\n      <li><b>विश्व टेस्ट चैंपियनशिप:</b> भारत पहले दोनों फ़ाइनल (2021 साउथैम्प्टन — न्यूज़ीलैंड से, 2023 द ओवल — ऑस्ट्रेलिया से) हारा।</li>\n      <li><b>दारा सिंह</b> 2003 में राज्यसभा में मनोनीत होने वाले पहले खिलाड़ी थे; बाद में सचिन तेंदुलकर (2012) और मैरी कॉम (2016) भी मनोनीत हुए।</li>\n    </ul>\n  ",
  questions: [
    {"q":"वर्ष 1904 के ग्रीष्मकालीन ओलंपिक खेल किस शहर में आयोजित हुए थे?","o":["पेरिस","सेंट लुइस","लंदन","स्टॉकहोम"],"a":1,"e":"1904 के ओलंपिक अमेरिका के सेंट लुइस में हुए — यूरोप से बाहर पहला ओलंपिक। 1900 पेरिस और 1908 लंदन में हुए थे।"},
    {"q":"वर्ष 1912 के ग्रीष्मकालीन ओलंपिक खेलों का मेज़बान शहर कौन-सा था?","o":["एंटवर्प","एम्सटर्डम","स्टॉकहोम","हेलसिंकी"],"a":2,"e":"1912 ओलंपिक स्टॉकहोम (स्वीडन) में हुए। एंटवर्प 1920, एम्सटर्डम 1928 और हेलसिंकी 1952 के मेज़बान थे।"},
    {"q":"ग्रीष्मकालीन और शीतकालीन — दोनों ओलंपिक खेलों की मेज़बानी करने वाला विश्व का पहला शहर कौन-सा है?","o":["टोक्यो","लॉस एंजिलिस","मॉस्को","बीजिंग"],"a":3,"e":"बीजिंग ने 2008 में ग्रीष्मकालीन और 2022 में शीतकालीन ओलंपिक कराए। टोक्यो ने ग्रीष्मकालीन ओलंपिक (1964, 2020) कराए, पर जापान के शीतकालीन ओलंपिक साप्पोरो व नागानो में हुए।"},
    {"q":"1956 मेलबर्न ओलंपिक की घुड़सवारी (इक्वेस्ट्रियन) स्पर्धाएँ किस शहर में आयोजित की गईं?","o":["सिडनी","स्टॉकहोम","ऑकलैंड","लंदन"],"a":1,"e":"ऑस्ट्रेलिया के कठोर पशु-क्वारंटीन नियमों के कारण घुड़सवारी स्पर्धाएँ स्टॉकहोम (स्वीडन) में हुईं। इसी ओलंपिक में भारत ने हॉकी फ़ाइनल में पाकिस्तान को 1-0 से हराया।"},
    {"q":"निम्नलिखित ओलंपिक मेज़बान शहरों को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. हेलसिंकी<br>2. एंटवर्प<br>3. मॉन्ट्रियल<br>4. म्यूनिख","o":["1, 2, 3, 4","2, 1, 3, 4","2, 1, 4, 3","1, 2, 4, 3"],"a":2,"e":"एंटवर्प 1920 → हेलसिंकी 1952 → म्यूनिख 1972 → मॉन्ट्रियल 1976। अतः 2, 1, 4, 3। एंटवर्प 1920 में पहली बार ओलंपिक ध्वज फहराया गया था।"},
    {"q":"सूची-I (ओलंपिक वर्ष) को सूची-II (मेज़बान शहर) से सुमेलित कीजिए —<br>(A) 1968 (B) 1976 (C) 1992 (D) 2000<br>1. बार्सिलोना 2. सिडनी 3. मेक्सिको सिटी 4. मॉन्ट्रियल","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2"],"a":3,"e":"1968 — मेक्सिको सिटी (A-3); 1976 — मॉन्ट्रियल (B-4); 1992 — बार्सिलोना (C-1); 2000 — सिडनी (D-2)। 1968 में भारत को हॉकी कांस्य मिला था।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (ओलंपिक वर्ष — मेज़बान) सही सुमेलित नहीं है?","o":["1908 — लंदन","1928 — एम्सटर्डम","1964 — मेक्सिको सिटी","1952 — हेलसिंकी"],"a":2,"e":"1964 के ओलंपिक टोक्यो में हुए (एशिया में प्रथम); मेक्सिको सिटी 1968 का मेज़बान था। अन्य तीनों युग्म सही हैं।"},
    {"q":"लंदन ओलंपिक 2012 में गगन नारंग ने किस स्पर्धा में कांस्य पदक जीता?","o":["10 मी एयर राइफ़ल","50 मी राइफ़ल प्रोन","डबल ट्रैप","25 मी रैपिड फ़ायर पिस्टल"],"a":0,"e":"गगन नारंग ने लंदन 2012 में 10 मी एयर राइफ़ल का कांस्य जीता — इसी स्पर्धा में अभिनव बिंद्रा ने 2008 में स्वर्ण जीता था।"},
    {"q":"पहलवान योगेश्वर दत्त ने ओलंपिक कांस्य पदक किस ओलंपिक में जीता?","o":["एथेंस 2004","बीजिंग 2008","लंदन 2012","रियो 2016"],"a":2,"e":"योगेश्वर दत्त ने लंदन 2012 में 60 किग्रा फ़्रीस्टाइल कुश्ती में कांस्य जीता। लंदन 2012 में भारत ने कुल 6 पदक जीते थे।"},
    {"q":"नॉर्मन प्रिचर्ड ने 1900 के पेरिस ओलंपिक में भारत की ओर से कितने पदक जीते?","o":["1 स्वर्ण","1 रजत और 1 कांस्य","2 कांस्य","2 रजत"],"a":3,"e":"प्रिचर्ड ने 200 मी दौड़ और 200 मी बाधा दौड़ — दोनों में रजत जीते। IOC ये दोनों पदक भारत के नाम गिनती है।"},
    {"q":"1948 लंदन ओलंपिक के हॉकी फ़ाइनल में स्वतंत्र भारत ने किस टीम को 4-0 से हराकर स्वर्ण जीता?","o":["पाकिस्तान","नीदरलैंड्स","ग्रेट ब्रिटेन","जर्मनी"],"a":2,"e":"1948 में भारत ने मेज़बान ग्रेट ब्रिटेन को 4-0 से हराया — स्वतंत्र भारत का पहला ओलंपिक स्वर्ण। कप्तान किशन लाल थे।"},
    {"q":"1952 हेलसिंकी ओलंपिक हॉकी फ़ाइनल में भारत ने किस देश को 6-1 से हराया?","o":["नीदरलैंड्स","पाकिस्तान","स्पेन","ऑस्ट्रेलिया"],"a":0,"e":"भारत ने नीदरलैंड्स को 6-1 से हराया; इनमें से 5 गोल बलबीर सिंह (सीनियर) ने किए — ओलंपिक फ़ाइनल का रिकॉर्ड।"},
    {"q":"1980 मॉस्को ओलंपिक हॉकी फ़ाइनल में भारत ने किस टीम को 4-3 से हराकर अपना 8वाँ स्वर्ण जीता?","o":["पाकिस्तान","सोवियत संघ","पश्चिम जर्मनी","स्पेन"],"a":3,"e":"भारत ने स्पेन को 4-3 से हराया; कप्तान वासुदेवन भास्करन थे। यह ओलंपिक हॉकी में भारत का अंतिम स्वर्ण है।"},
    {"q":"1932 लॉस एंजिलिस ओलंपिक में भारतीय हॉकी टीम ने किस देश को 24-1 के रिकॉर्ड अंतर से हराया?","o":["संयुक्त राज्य अमेरिका","जापान","नीदरलैंड्स","ब्रिटेन"],"a":0,"e":"भारत ने मेज़बान अमेरिका को 24-1 से हराया — ओलंपिक हॉकी की सबसे बड़ी जीत। इस ओलंपिक में कप्तान लाल शाह बुख़ारी थे।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. लेस्ली क्लॉडियस ने ओलंपिक हॉकी में तीन स्वर्ण और एक रजत पदक जीते।<br>2. 1956 मेलबर्न ओलंपिक में भारतीय हॉकी टीम के कप्तान बलबीर सिंह (सीनियर) थे।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — क्लॉडियस ने 1948, 1952, 1956 में स्वर्ण और 1960 में रजत जीता। कथन 2 सही — 1956 में कप्तान बलबीर सिंह (सीनियर) थे; उधम सिंह के भी 3 स्वर्ण व 1 रजत हैं।"},
    {"q":"भारत के निम्नलिखित ओलंपिक पदकों को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. गगन नारंग का कांस्य<br>2. राज्यवर्धन सिंह राठौड़ का रजत<br>3. लिएंडर पेस का कांस्य<br>4. साक्षी मलिक का कांस्य","o":["3, 2, 1, 4","2, 3, 1, 4","3, 1, 2, 4","3, 2, 4, 1"],"a":0,"e":"पेस 1996 अटलांटा → राठौड़ 2004 एथेंस → नारंग 2012 लंदन → साक्षी 2016 रियो। अतः 3, 2, 1, 4।"},
    {"q":"सूची-I (लंदन 2012 पदक विजेता) को सूची-II (स्पर्धा) से सुमेलित कीजिए —<br>(A) विजय कुमार (B) सुशील कुमार (C) मैरी कॉम (D) योगेश्वर दत्त<br>1. मुक्केबाज़ी 51 किग्रा 2. 25 मी रैपिड फ़ायर पिस्टल 3. कुश्ती 60 किग्रा 4. कुश्ती 66 किग्रा","o":["A-2, B-3, C-1, D-4","A-2, B-4, C-1, D-3","A-1, B-4, C-2, D-3","A-4, B-2, C-1, D-3"],"a":1,"e":"विजय कुमार — 25 मी रैपिड फ़ायर पिस्टल रजत (A-2); सुशील — 66 किग्रा रजत (B-4); मैरी कॉम — 51 किग्रा कांस्य (C-1); योगेश्वर — 60 किग्रा कांस्य (D-3)।"},
    {"q":"निम्नलिखित में से किस ओलंपिक में भारत को एक भी पदक नहीं मिला?","o":["1968 मेक्सिको सिटी","1972 म्यूनिख","1984 लॉस एंजिलिस","1996 अटलांटा"],"a":2,"e":"1976, 1984, 1988 और 1992 में भारत पदकविहीन रहा। 1968 व 1972 में हॉकी कांस्य और 1996 में लिएंडर पेस का कांस्य मिला।"},
    {"q":"अभिकथन (A): टोक्यो 2020 में नीरज चोपड़ा का स्वर्ण ओलंपिक एथलेटिक्स में भारत का पहला स्वर्ण पदक था।<br>कारण (R): नॉर्मन प्रिचर्ड ने 1900 के ओलंपिक में एथलेटिक्स में दो रजत पदक जीते थे।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — नीरज (87.58 मी) से पहले भारत ने एथलेटिक्स में कभी स्वर्ण नहीं जीता था। R भी सही — प्रिचर्ड के 2 रजत। पर R, A का कारण नहीं है।"},
    {"q":"टोक्यो 2020 ओलंपिक में बजरंग पूनिया ने किस भार वर्ग में कांस्य पदक जीता?","o":["57 किग्रा","74 किग्रा","86 किग्रा","65 किग्रा"],"a":3,"e":"बजरंग ने 65 किग्रा फ़्रीस्टाइल में कांस्य जीता। वे विश्व चैंपियनशिप में 4 पदक जीतने वाले एकमात्र भारतीय पहलवान हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. सुशील कुमार ने 2008 में कांस्य और 2012 में रजत पदक जीता।<br>2. सुशील कुमार के दोनों ओलंपिक पदक 66 किग्रा भार वर्ग में आए।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","न तो 1 न ही 2","1 और 2 दोनों"],"a":3,"e":"कथन 1 सही — बीजिंग 2008 कांस्य, लंदन 2012 रजत। कथन 2 सही — दोनों 66 किग्रा फ़्रीस्टाइल में। सुशील 2010 में भारत के पहले विश्व कुश्ती चैंपियन भी बने।"},
    {"q":"किस ओलंपिक में भारत ने हॉकी स्वर्ण के साथ एक व्यक्तिगत पदक भी जीता?","o":["1948 लंदन","1956 मेलबर्न","1952 हेलसिंकी","1964 टोक्यो"],"a":2,"e":"1952 हेलसिंकी में हॉकी स्वर्ण के साथ के. डी. जाधव ने कुश्ती (बैंटमवेट) में कांस्य जीता — स्वतंत्र भारत का पहला व्यक्तिगत पदक।"},
    {"q":"एशियाई खेलों की सर्वाधिक (चार) बार मेज़बानी करने वाला शहर कौन-सा है?","o":["नई दिल्ली","बैंकॉक","टोक्यो","जकार्ता"],"a":1,"e":"बैंकॉक ने 1966, 1970, 1978 और 1998 में एशियाई खेल आयोजित किए। नई दिल्ली ने दो बार (1951, 1982) मेज़बानी की।"},
    {"q":"वर्ष 1974 के एशियाई खेल किस शहर में आयोजित हुए थे?","o":["तेहरान","मनीला","सियोल","बैंकॉक"],"a":0,"e":"7वें एशियाई खेल 1974 में तेहरान (ईरान) में हुए — पश्चिम एशिया में पहली बार।"},
    {"q":"दूसरे एशियाई खेल (1954) किस शहर में हुए?","o":["टोक्यो","जकार्ता","बैंकॉक","मनीला"],"a":3,"e":"1954 के दूसरे एशियाई खेल मनीला (फ़िलीपींस) में हुए। पहले (1951) नई दिल्ली और तीसरे (1958) टोक्यो में हुए।"},
    {"q":"निम्नलिखित एशियाई खेल मेज़बान शहरों को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. इंचियोन<br>2. दोहा<br>3. हिरोशिमा<br>4. सियोल","o":["3, 4, 2, 1","4, 3, 1, 2","4, 3, 2, 1","4, 2, 3, 1"],"a":2,"e":"सियोल 1986 → हिरोशिमा 1994 → दोहा 2006 → इंचियोन 2014। अतः 4, 3, 2, 1।"},
    {"q":"एशिया में पहली बार राष्ट्रमंडल खेल किस शहर में आयोजित हुए?","o":["नई दिल्ली","सिंगापुर","कुआलालंपुर","कोलंबो"],"a":2,"e":"1998 के राष्ट्रमंडल खेल कुआलालंपुर (मलेशिया) में हुए — एशिया में पहली बार। नई दिल्ली ने 2010 में मेज़बानी की।"},
    {"q":"मिल्खा सिंह ने 1958 में राष्ट्रमंडल खेलों का स्वर्ण पदक किस शहर में जीता?","o":["कार्डिफ़","वैंकूवर","पर्थ","किंग्स्टन"],"a":0,"e":"मिल्खा सिंह ने 1958 कार्डिफ़ (वेल्स) राष्ट्रमंडल खेलों में 440 गज़ दौड़ का स्वर्ण जीता। उसी वर्ष टोक्यो एशियाई खेलों में 200 मी व 400 मी के स्वर्ण भी जीते।"},
    {"q":"राष्ट्रमंडल खेलों में क्रिकेट के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. 1998 कुआलालंपुर में पुरुष एकदिवसीय क्रिकेट शामिल किया गया।<br>2. 2022 बर्मिंघम में महिला T20 क्रिकेट का स्वर्ण भारत ने जीता।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — 1998 में पुरुष क्रिकेट शामिल था (स्वर्ण दक्षिण अफ़्रीका)। कथन 2 गलत — 2022 महिला T20 स्वर्ण ऑस्ट्रेलिया ने जीता, भारत को रजत मिला।"},
    {"q":"सूची-I (राष्ट्रमंडल खेल वर्ष) को सूची-II (मेज़बान) से सुमेलित कीजिए —<br>(A) 1966 (B) 1982 (C) 2006 (D) 2014<br>1. मेलबर्न 2. ग्लासगो 3. किंग्स्टन 4. ब्रिस्बेन","o":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1"],"a":0,"e":"1966 — किंग्स्टन, जमैका (A-3); 1982 — ब्रिस्बेन (B-4); 2006 — मेलबर्न (C-1); 2014 — ग्लासगो (D-2)।"},
    {"q":"एशियाई खेलों में क्रिकेट पहली बार किस संस्करण में शामिल किया गया?","o":["2006 दोहा","2002 बुसान","2014 इंचियोन","2010 ग्वांगझू"],"a":3,"e":"क्रिकेट 2010 ग्वांगझू एशियाई खेलों में पहली बार शामिल हुआ। भारत ने तब टीम नहीं भेजी थी; 2023 हांगझोउ में भारत ने पुरुष व महिला दोनों स्वर्ण जीते।"},
    {"q":"एशियाई खेलों में व्यक्तिगत स्वर्ण जीतने वाली पहली भारतीय महिला कौन हैं?","o":["पी. टी. उषा","शाइनी विल्सन","कमलजीत संधू","एम. डी. वलसम्मा"],"a":2,"e":"कमलजीत संधू ने 1970 बैंकॉक एशियाई खेलों में 400 मी दौड़ का स्वर्ण जीता। उन्हें 1971 में पद्मश्री मिला।"},
    {"q":"पी. टी. उषा के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. उन्होंने 1986 सियोल एशियाई खेलों में चार स्वर्ण पदक जीते।<br>2. उनके 1986 के स्वर्ण पदकों में 100 मी दौड़ भी शामिल थी।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — 200 मी, 400 मी, 400 मी बाधा दौड़ और 4×400 मी रिले में स्वर्ण। कथन 2 गलत — 100 मी में उन्हें रजत मिला था।"},
    {"q":"मिल्खा सिंह ने 1958 टोक्यो एशियाई खेलों में किन दो स्पर्धाओं में स्वर्ण पदक जीते?","o":["100 मी और 200 मी","400 मी और 800 मी","200 मी और 400 मी","400 मी और 4×400 मी रिले"],"a":2,"e":"मिल्खा ने 1958 टोक्यो में 200 मी और 400 मी — दोनों स्वर्ण जीते। 1960 रोम ओलंपिक 400 मी में वे चौथे रहे।"},
    {"q":"2018 जकार्ता एशियाई खेलों के उद्घाटन समारोह में भारत के ध्वजवाहक कौन थे?","o":["नीरज चोपड़ा","पी. वी. सिंधु","मनप्रीत सिंह","बजरंग पूनिया"],"a":0,"e":"नीरज चोपड़ा 2018 एशियाई खेलों में ध्वजवाहक थे और उन्होंने वहाँ भाला फेंक का स्वर्ण भी जीता। उसी वर्ष गोल्ड कोस्ट राष्ट्रमंडल खेलों में भी स्वर्ण जीता।"},
    {"q":"एशियाई खेलों में बैडमिंटन का भारत का पहला स्वर्ण पदक (हांगझोउ 2023) किसने जीता?","o":["पी. वी. सिंधु","एच. एस. प्रणय","साइना नेहवाल","सात्विकसाईराज रंकीरेड्डी–चिराग शेट्टी"],"a":3,"e":"सात्विक–चिराग की पुरुष युगल जोड़ी ने 2023 में एशियाई खेलों का पहला बैडमिंटन स्वर्ण जीता। यह जोड़ी 2023 में पुरुष युगल विश्व नंबर 1 भी बनी।"},
    {"q":"अभिकथन (A): 2018 जकार्ता एशियाई खेलों में भारत पुरुष कबड्डी का स्वर्ण नहीं जीत सका।<br>कारण (R): कबड्डी 1990 से एशियाई खेलों में शामिल है और भारत ने 1990 से 2014 तक इसके सभी स्वर्ण जीते थे।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A सही है, R गलत है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A गलत है, R सही है"],"a":2,"e":"A सही — 2018 में ईरान ने स्वर्ण जीता, भारत सेमीफ़ाइनल में हारा। R भी सही — भारत के लगातार 7 स्वर्ण। पर R, A की हार का कारण नहीं बताता।"},
    {"q":"भारतीय ओलंपिक संघ (IOA) की स्थापना किस वर्ष हुई?","o":["1920","1927","1936","1947"],"a":1,"e":"IOA की स्थापना 1927 में हुई; सर दोराबजी टाटा इसके पहले अध्यक्ष थे। भारत ने 1920 एंटवर्प ओलंपिक में पहली बार आधिकारिक दल भेजा था।"},
    {"q":"1928 एम्सटर्डम ओलंपिक में स्वर्ण जीतने वाली भारतीय हॉकी टीम के कप्तान कौन थे?","o":["मेजर ध्यानचंद","जयपाल सिंह मुंडा","लाल शाह बुख़ारी","किशन लाल"],"a":1,"e":"1928 में कप्तान जयपाल सिंह मुंडा थे — बाद में वे झारखंड आंदोलन के प्रमुख आदिवासी नेता और संविधान सभा के सदस्य बने।"},
    {"q":"1936 बर्लिन ओलंपिक हॉकी फ़ाइनल में भारत ने किस देश को 8-1 से हराया?","o":["नीदरलैंड्स","जर्मनी","ग्रेट ब्रिटेन","अमेरिका"],"a":1,"e":"भारत ने मेज़बान जर्मनी को 8-1 से हराया; कप्तान मेजर ध्यानचंद थे। यह भारत का लगातार तीसरा ओलंपिक हॉकी स्वर्ण था।"},
    {"q":"1928 एम्सटर्डम ओलंपिक हॉकी फ़ाइनल में भारत ने किस टीम को 3-0 से हराया?","o":["जर्मनी","नीदरलैंड्स","बेल्जियम","स्पेन"],"a":1,"e":"भारत ने मेज़बान नीदरलैंड्स को 3-0 से हराकर पहला ओलंपिक हॉकी स्वर्ण जीता। ध्यानचंद इस ओलंपिक के सर्वाधिक गोल करने वाले खिलाड़ी थे।"},
    {"q":"1964 टोक्यो ओलंपिक में हॉकी स्वर्ण जीतने वाली भारतीय टीम के कप्तान कौन थे?","o":["पृथीपाल सिंह","चरणजीत सिंह","बलबीर सिंह (सीनियर)","अजीतपाल सिंह"],"a":1,"e":"1964 में कप्तान चरणजीत सिंह थे; भारत ने फ़ाइनल में पाकिस्तान को 1-0 से हराकर 1960 की हार का बदला लिया। अजीतपाल सिंह 1975 विश्व कप विजेता कप्तान थे।"},
    {"q":"सूची-I (ओलंपिक हॉकी स्वर्ण) को सूची-II (भारतीय कप्तान) से सुमेलित कीजिए —<br>(A) 1928 एम्सटर्डम (B) 1936 बर्लिन (C) 1948 लंदन (D) 1980 मॉस्को<br>1. किशन लाल 2. वासुदेवन भास्करन 3. जयपाल सिंह मुंडा 4. ध्यानचंद","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2","A-3, B-4, C-1, D-2"],"a":3,"e":"1928 — जयपाल सिंह मुंडा (A-3); 1936 — ध्यानचंद (B-4); 1948 — किशन लाल (C-1); 1980 — वी. भास्करन (D-2)। 1932 में कप्तान लाल शाह बुख़ारी थे।"},
    {"q":"1960 रोम ओलंपिक हॉकी फ़ाइनल में भारत किस टीम से 0-1 से हारकर रजत पर रुका?","o":["पाकिस्तान","ऑस्ट्रेलिया","जर्मनी","ग्रेट ब्रिटेन"],"a":0,"e":"1960 में पाकिस्तान ने भारत को 1-0 से हराकर भारत का लगातार 6 स्वर्णों (1928–1956) का क्रम तोड़ा।"},
    {"q":"ओलंपिक आदर्श वाक्य \"सिटियस, अल्टियस, फ़ोर्टियस\" मूल रूप से किसने सुझाया था?","o":["पियरे डी कूबर्टिन","फ़ादर हेनरी डिडॉन","एवरी ब्रंडेज","जुआन एंटोनियो समरांच"],"a":1,"e":"यह वाक्य फ़्रांसीसी पादरी हेनरी डिडॉन का था, जिसे कूबर्टिन ने 1894 में अपनाया। अर्थ — \"तेज़, ऊँचा, मज़बूत\"।"},
    {"q":"ओलंपिक खिलाड़ी शपथ पहली बार किस ओलंपिक में ली गई?","o":["1896 एथेंस","1912 स्टॉकहोम","1936 बर्लिन","1920 एंटवर्प"],"a":3,"e":"1920 एंटवर्प में बेल्जियम के तलवारबाज़ विक्टर बोइन ने पहली खिलाड़ी शपथ ली। इसी ओलंपिक में पाँच छल्लों वाला ओलंपिक ध्वज पहली बार फहराया गया।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. ओलंपिक ज्योति पहली बार 1928 एम्सटर्डम ओलंपिक में प्रज्वलित की गई।<br>2. पाँच छल्लों वाला ओलंपिक ध्वज पहली बार 1920 एंटवर्प ओलंपिक में फहराया गया।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 1928 एम्सटर्डम में स्टेडियम की मीनार पर ज्योति जलाई गई। कथन 2 सही — ध्वज (कूबर्टिन द्वारा 1913 में डिज़ाइन) 1920 में पहली बार फहराया गया।"},
    {"q":"निम्नलिखित शीतकालीन ओलंपिक मेज़बान शहरों को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. नागानो<br>2. साप्पोरो<br>3. सोची<br>4. कैलगरी","o":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","2, 4, 3, 1"],"a":0,"e":"साप्पोरो 1972 → कैलगरी 1988 → नागानो 1998 → सोची 2014। अतः 2, 4, 1, 3।"},
    {"q":"वर्ष 2018 के शीतकालीन ओलंपिक खेल कहाँ आयोजित हुए?","o":["सोची (रूस)","प्योंगचांग (दक्षिण कोरिया)","बीजिंग (चीन)","वैंकूवर (कनाडा)"],"a":1,"e":"2018 के शीतकालीन ओलंपिक प्योंगचांग में हुए; 2014 सोची, 2010 वैंकूवर और 2022 बीजिंग में हुए।"},
    {"q":"पैरालंपिक आंदोलन का जनक किसे माना जाता है?","o":["पियरे डी कूबर्टिन","एवरी ब्रंडेज","थॉमस बाख","सर लुडविग गुटमान"],"a":3,"e":"जर्मन मूल के चिकित्सक लुडविग गुटमान ने 1948 में इंग्लैंड के स्टोक मैंडविल अस्पताल में खेल आयोजित किए, जो आगे चलकर 1960 रोम के पहले पैरालंपिक बने।"},
    {"q":"पैरालंपिक में दो स्वर्ण पदक जीतने वाले पहले भारतीय भाला फेंक खिलाड़ी कौन हैं?","o":["देवेंद्र झाझड़िया","सुमित अंतिल","मरियप्पन थंगावेलु","मुरलीकांत पेटकर"],"a":0,"e":"देवेंद्र झाझड़िया ने 2004 एथेंस और 2016 रियो पैरालंपिक में भाला फेंक (F46) का स्वर्ण जीता। उन्हें 2017 में खेल रत्न मिला।"},
    {"q":"रियो पैरालंपिक 2016 में ऊँची कूद (T42) का स्वर्ण जीतने वाले भारतीय कौन हैं?","o":["वरुण सिंह भाटी","मरियप्पन थंगावेलु","शरद कुमार","निषाद कुमार"],"a":1,"e":"तमिलनाडु के मरियप्पन थंगावेलु ने रियो 2016 में ऊँची कूद का स्वर्ण जीता; वरुण भाटी को उसी स्पर्धा में कांस्य मिला।"},
    {"q":"एशियाई ओलंपिक परिषद (OCA) का मुख्यालय कहाँ है?","o":["टोक्यो","नई दिल्ली","बैंकॉक","कुवैत सिटी"],"a":3,"e":"OCA (1982 में गठित) का मुख्यालय कुवैत सिटी में है; यही एशियाई खेलों का संचालन करती है।"},
    {"q":"एशियाई खेलों का आदर्श वाक्य \"एवर ऑनवर्ड\" (सदा आगे बढ़ते रहो) किसने दिया था?","o":["जवाहरलाल नेहरू","गुरु दत्त सोंधी","महात्मा गांधी","सर दोराबजी टाटा"],"a":0,"e":"\"एवर ऑनवर्ड\" पंडित नेहरू ने दिया। एशियाई खेलों के विचार के प्रणेता भारत के गुरु दत्त सोंधी थे; पहले खेल 1951 में नई दिल्ली में हुए।"},
    {"q":"भारत में रंगीन टेलीविज़न प्रसारण किस खेल आयोजन के अवसर पर आरंभ हुआ?","o":["1951 नई दिल्ली एशियाई खेल","1982 नई दिल्ली एशियाई खेल","1987 क्रिकेट विश्व कप","2010 राष्ट्रमंडल खेल"],"a":1,"e":"1982 के नौवें एशियाई खेलों (नई दिल्ली) के लिए दूरदर्शन ने रंगीन प्रसारण शुरू किया। इन खेलों का शुभंकर हाथी \"अप्पू\" था।"},
    {"q":"राष्ट्रमंडल खेल प्रारंभ में (1930 में) किस नाम से आयोजित हुए थे?","o":["इंपीरियल गेम्स","कॉमनवेल्थ यूथ गेम्स","ब्रिटिश ओलंपिक गेम्स","ब्रिटिश एम्पायर गेम्स"],"a":3,"e":"1930–1950 तक \"ब्रिटिश एम्पायर गेम्स\", फिर \"ब्रिटिश एम्पायर एंड कॉमनवेल्थ गेम्स\" (1954–66), \"ब्रिटिश कॉमनवेल्थ गेम्स\" (1970–74) और 1978 से \"कॉमनवेल्थ गेम्स\" नाम पड़ा।"},
    {"q":"सूची-I (शुभंकर) को सूची-II (खेल आयोजन) से सुमेलित कीजिए —<br>(A) अप्पू (B) शेरा (C) मिराइतोवा (D) फ़्रीज<br>1. पेरिस ओलंपिक 2024 2. नई दिल्ली राष्ट्रमंडल खेल 2010 3. टोक्यो ओलंपिक 2020 4. नई दिल्ली एशियाई खेल 1982","o":["A-4, B-2, C-3, D-1","A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-4, B-3, C-2, D-1"],"a":0,"e":"अप्पू (हाथी) — 1982 एशियाड (A-4); शेरा (बाघ) — 2010 राष्ट्रमंडल खेल (B-2); मिराइतोवा — टोक्यो 2020 (C-3); फ़्रीज (फ़्रीजियन टोपी) — पेरिस 2024 (D-1)।"},
    {"q":"2010 नई दिल्ली राष्ट्रमंडल खेलों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. भारत ने कुल 101 पदक जीतकर पदक तालिका में दूसरा स्थान पाया।<br>2. पदक तालिका में शीर्ष स्थान इंग्लैंड का रहा।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — भारत ने 38 स्वर्ण सहित 101 पदक जीते (अब तक का सर्वश्रेष्ठ)। कथन 2 गलत — शीर्ष पर ऑस्ट्रेलिया रहा, इंग्लैंड तीसरे स्थान पर था।"},
    {"q":"भारत में आयोजित पहला फ़ीफ़ा टूर्नामेंट — फ़ीफ़ा अंडर-17 विश्व कप 2017 — किस देश ने जीता?","o":["स्पेन","इंग्लैंड","ब्राज़ील","माली"],"a":1,"e":"कोलकाता के साल्ट लेक स्टेडियम में फ़ाइनल में इंग्लैंड ने स्पेन को 5-2 से हराया। मेज़बान होने के कारण भारत ने पहली बार किसी फ़ीफ़ा विश्व कप में भाग लिया।"},
    {"q":"डूरंड कप फ़ुटबॉल प्रतियोगिता का नाम किसके नाम पर रखा गया है?","o":["लॉर्ड डलहौज़ी","सर ड्यूरंड कूपर","सर मॉर्टिमर डूरंड","लॉर्ड कर्ज़न"],"a":2,"e":"डूरंड कप (1888) का नाम तत्कालीन विदेश सचिव सर मॉर्टिमर डूरंड पर है — यह एशिया की सबसे पुरानी फ़ुटबॉल प्रतियोगिता है। डूरंड रेखा भी उन्हीं के नाम पर है।"},
    {"q":"1911 में IFA शील्ड फ़ाइनल में ईस्ट यॉर्कशायर रेजिमेंट को नंगे पाँव खेलकर हराने वाला भारतीय क्लब कौन-सा था?","o":["ईस्ट बंगाल","मोहम्मडन स्पोर्टिंग","डेम्पो","मोहन बागान"],"a":3,"e":"मोहन बागान ने 29 जुलाई 1911 को 2-1 से जीत दर्ज की — किसी अंग्रेज़ टीम को हराकर IFA शील्ड जीतने वाला पहला भारतीय क्लब; इसे राष्ट्रवादी गौरव का प्रतीक माना गया।"},
    {"q":"1956 मेलबर्न ओलंपिक फ़ुटबॉल में भारत किस स्थान पर रहा?","o":["तीसरे","चौथे","दूसरे","आठवें"],"a":1,"e":"भारत सेमीफ़ाइनल तक पहुँचा और चौथे स्थान पर रहा — ओलंपिक फ़ुटबॉल में किसी एशियाई देश का तब तक का सर्वश्रेष्ठ प्रदर्शन। कोच सैयद अब्दुल रहीम थे।"},
    {"q":"ओलंपिक फ़ुटबॉल में हैट्रिक लगाने वाले पहले एशियाई खिलाड़ी कौन थे?","o":["चुन्नी गोस्वामी","पी. के. बनर्जी","नेविल डिसूज़ा","सैलेन मन्ना"],"a":2,"e":"नेविल डिसूज़ा ने 1956 मेलबर्न ओलंपिक के क्वार्टर फ़ाइनल में ऑस्ट्रेलिया के विरुद्ध हैट्रिक लगाई; भारत 4-2 से जीता।"},
    {"q":"भारतीय फ़ुटबॉल के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. भारत ने एशियाई खेलों में फ़ुटबॉल का स्वर्ण 1951 और 1962 में जीता।<br>2. अखिल भारतीय फ़ुटबॉल महासंघ (AIFF) की स्थापना 1937 में हुई।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 1951 नई दिल्ली व 1962 जकार्ता में स्वर्ण (1962 में दक्षिण कोरिया को 2-1 से हराया)। कथन 2 सही — AIFF 1937 में बना; मुख्यालय नई दिल्ली (द्वारका)।"},
    {"q":"बैलन डी'ओर (फ़ुटबॉल) सर्वाधिक बार जीतने वाले खिलाड़ी कौन हैं (2025 तक)?","o":["क्रिस्टियानो रोनाल्डो","मिशेल प्लातिनी","योहान क्रूफ़","लियोनेल मेसी"],"a":3,"e":"मेसी ने 8 बार (अंतिम 2023) यह पुरस्कार जीता; रोनाल्डो 5 बार। फ़्रांस फ़ुटबॉल पत्रिका ने 1956 में इसे शुरू किया; पहले विजेता स्टैनली मैथ्यूज़ थे।"},
    {"q":"फ़ीफ़ा विश्व कप के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. एशिया में पहला फ़ीफ़ा विश्व कप 2002 में दक्षिण कोरिया और जापान ने संयुक्त रूप से आयोजित किया।<br>2. अफ़्रीका में पहला फ़ीफ़ा विश्व कप 2010 में दक्षिण अफ़्रीका में हुआ, जिसे स्पेन ने जीता।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 2002 में पहली बार दो देशों की संयुक्त मेज़बानी; विजेता ब्राज़ील। कथन 2 सही — 2010 में स्पेन ने नीदरलैंड्स को हराकर पहला विश्व कप जीता।"},
    {"q":"पहली यूरोपीय फ़ुटबॉल चैंपियनशिप (यूरो, 1960) किस देश ने जीती?","o":["सोवियत संघ","स्पेन","इटली","पश्चिम जर्मनी"],"a":0,"e":"1960 में फ़्रांस में हुई पहली यूरो चैंपियनशिप सोवियत संघ ने जीती। इसकी ट्रॉफी का नाम हेनरी डेलौने ट्रॉफी है।"},
    {"q":"अंतरराष्ट्रीय हॉकी महासंघ (FIH) की स्थापना किस वर्ष और कहाँ हुई?","o":["1908, लंदन","1924, पेरिस","1928, एम्सटर्डम","1894, पेरिस"],"a":1,"e":"FIH की स्थापना 7 जनवरी 1924 को पेरिस में हुई (संस्थापक पॉल लेओते); अब मुख्यालय लुसाने में है। इसी वर्ष FIDE (शतरंज) भी पेरिस में बना।"},
    {"q":"भारतीय महिला हॉकी के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. भारतीय महिला हॉकी टीम ने 1982 नई दिल्ली एशियाई खेलों में स्वर्ण जीता।<br>2. भारतीय महिला हॉकी टीम ने 2002 मैनचेस्टर राष्ट्रमंडल खेलों में स्वर्ण जीता।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 1982 में महिला हॉकी पहली बार एशियाई खेलों में शामिल हुई और भारत ने स्वर्ण जीता। कथन 2 सही — 2002 मैनचेस्टर स्वर्ण (फ़िल्म \"चक दे! इंडिया\" इसी से प्रेरित मानी जाती है)।"},
    {"q":"भारतीय पुरुष हॉकी टीम ने एशियाई खेलों का पहला स्वर्ण किस वर्ष जीता?","o":["1958","1962","1982","1966"],"a":3,"e":"1966 बैंकॉक एशियाई खेलों में भारत ने फ़ाइनल में पाकिस्तान को हराकर पहला एशियाई हॉकी स्वर्ण जीता; बाद में 1998, 2014 और 2023 में भी स्वर्ण जीते।"},
    {"q":"हॉकी की चैंपियंस ट्रॉफी प्रतियोगिता पहली बार 1978 में कहाँ आयोजित हुई?","o":["लाहौर","एम्सटर्डम","नई दिल्ली","सिडनी"],"a":0,"e":"चैंपियंस ट्रॉफी पाकिस्तान के एयर मार्शल नूर ख़ान की पहल पर 1978 में लाहौर में शुरू हुई; पहला ख़िताब पाकिस्तान ने जीता।"},
    {"q":"मेजर ध्यानचंद का जन्म (29 अगस्त 1905) किस शहर में हुआ था?","o":["झाँसी","इलाहाबाद (प्रयागराज)","लखनऊ","ग्वालियर"],"a":1,"e":"ध्यानचंद का जन्म इलाहाबाद में हुआ, पर उनका कर्मक्षेत्र झाँसी रहा। उनकी जयंती 29 अगस्त राष्ट्रीय खेल दिवस है।"},
    {"q":"मेजर ध्यानचंद के छोटे भाई, जो 1932 व 1936 की स्वर्ण विजेता हॉकी टीमों में थे, कौन थे?","o":["केशव दत्त","गुरबख़्श सिंह","मोहम्मद शाहिद","रूप सिंह"],"a":3,"e":"रूप सिंह ने 1932 लॉस एंजिलिस ओलंपिक में अमेरिका के विरुद्ध 24-1 की जीत में 10 गोल किए थे; ग्वालियर का कैप्टन रूप सिंह स्टेडियम उन्हीं के नाम पर है।"},
    {"q":"मेजर ध्यानचंद को पद्म भूषण किस वर्ष प्रदान किया गया?","o":["1956","1966","1972","1980"],"a":0,"e":"ध्यानचंद को 1956 में पद्म भूषण मिला। उनकी आत्मकथा \"गोल\" (1952) है।"},
    {"q":"विश्व का पहला आधिकारिक टेस्ट क्रिकेट मैच (1877) कहाँ खेला गया?","o":["लॉर्ड्स, लंदन","मेलबर्न क्रिकेट ग्राउंड","द ओवल, लंदन","सिडनी क्रिकेट ग्राउंड"],"a":1,"e":"मार्च 1877 में MCG पर ऑस्ट्रेलिया और इंग्लैंड के बीच पहला टेस्ट खेला गया; ऑस्ट्रेलिया 45 रन से जीता। 1977 का शताब्दी टेस्ट भी MCG पर हुआ।"},
    {"q":"भारत ने अपना पहला टेस्ट मैच (1932) किस मैदान पर और किसकी कप्तानी में खेला?","o":["द ओवल — लाला अमरनाथ","ईडन गार्डन्स — सी. के. नायडू","लॉर्ड्स — महाराजा पटियाला","लॉर्ड्स — सी. के. नायडू"],"a":3,"e":"जून 1932 में लॉर्ड्स में इंग्लैंड के विरुद्ध भारत ने पहला टेस्ट खेला; कप्तान सी. के. नायडू थे। भारत यह मैच हार गया।"},
    {"q":"भारत ने अपनी पहली टेस्ट जीत (1952) किस टीम के विरुद्ध दर्ज की?","o":["इंग्लैंड","पाकिस्तान","ऑस्ट्रेलिया","न्यूज़ीलैंड"],"a":0,"e":"फ़रवरी 1952 में मद्रास (चेन्नई) में विजय हज़ारे की कप्तानी में भारत ने इंग्लैंड को पारी से हराया — 20 वर्ष बाद पहली टेस्ट जीत।"},
    {"q":"भारत ने विदेश में पहली टेस्ट श्रृंखला (1967-68) किस देश में जीती?","o":["इंग्लैंड","न्यूज़ीलैंड","वेस्ट इंडीज़","ऑस्ट्रेलिया"],"a":1,"e":"मंसूर अली ख़ान पटौदी की कप्तानी में भारत ने 1967-68 में न्यूज़ीलैंड को 3-1 से हराया। 1971 में अजीत वाडेकर की कप्तानी में वेस्ट इंडीज़ व इंग्लैंड में श्रृंखला जीती।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. भारत ने 1971 में अजीत वाडेकर की कप्तानी में वेस्ट इंडीज़ और इंग्लैंड — दोनों देशों में टेस्ट श्रृंखला जीती।<br>2. भारत ने अपना पहला एकदिवसीय अंतरराष्ट्रीय मैच 1974 में इंग्लैंड के विरुद्ध खेला।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 1971 में दोनों विदेशी श्रृंखला जीत (सुनील गावस्कर का पदार्पण भी इसी वर्ष वेस्ट इंडीज़ में)। कथन 2 सही — जुलाई 1974 में हेडिंग्ले (लीड्स) में, कप्तान अजीत वाडेकर।"},
    {"q":"पहला एकदिवसीय अंतरराष्ट्रीय (ODI) क्रिकेट मैच 1971 में किन टीमों के बीच खेला गया?","o":["भारत और इंग्लैंड","वेस्ट इंडीज़ और इंग्लैंड","ऑस्ट्रेलिया और न्यूज़ीलैंड","ऑस्ट्रेलिया और इंग्लैंड"],"a":3,"e":"5 जनवरी 1971 को MCG पर टेस्ट वर्षा से धुल जाने पर पहला ODI खेला गया; ऑस्ट्रेलिया जीता।"},
    {"q":"पहला अंतरराष्ट्रीय T20 क्रिकेट मैच (2005) किन दो टीमों के बीच खेला गया?","o":["ऑस्ट्रेलिया और न्यूज़ीलैंड","इंग्लैंड और ऑस्ट्रेलिया","भारत और दक्षिण अफ़्रीका","पाकिस्तान और इंग्लैंड"],"a":0,"e":"17 फ़रवरी 2005 को ऑकलैंड (ईडन पार्क) में ऑस्ट्रेलिया-न्यूज़ीलैंड के बीच पहला T20I हुआ। भारत ने पहला T20I 2006 में दक्षिण अफ़्रीका के विरुद्ध जोहान्सबर्ग में खेला।"},
    {"q":"टेस्ट क्रिकेट में एक पारी में 400* रन (2004) बनाने वाले एकमात्र बल्लेबाज़ कौन हैं?","o":["मैथ्यू हेडन","ब्रायन लारा","वीरेंद्र सहवाग","डॉन ब्रैडमैन"],"a":1,"e":"ब्रायन लारा ने अप्रैल 2004 में एंटीगुआ में इंग्लैंड के विरुद्ध 400* बनाए। प्रथम श्रेणी का सर्वोच्च स्कोर 501* (1994, वारविकशायर बनाम डरहम) भी लारा के नाम है।"},
    {"q":"एक टेस्ट मैच में 19 विकेट लेने का रिकॉर्ड (1956, ओल्ड ट्रैफ़र्ड) किसके नाम है?","o":["अनिल कुंबले","मुथैया मुरलीधरन","जिम लेकर","सिडनी बार्न्स"],"a":2,"e":"इंग्लैंड के ऑफ़-स्पिनर जिम लेकर ने 1956 में ऑस्ट्रेलिया के विरुद्ध 19/90 लिए, जिसमें एक पारी के सभी 10 विकेट शामिल थे।"},
    {"q":"अनिल कुंबले ने टेस्ट की एक पारी में सभी 10 विकेट (10/74, फ़रवरी 1999) किस टीम के विरुद्ध लिए?","o":["ऑस्ट्रेलिया","इंग्लैंड","श्रीलंका","पाकिस्तान"],"a":3,"e":"कुंबले ने फ़िरोज़शाह कोटला (दिल्ली) में पाकिस्तान के विरुद्ध यह कारनामा किया — जिम लेकर (1956) के बाद ऐसा करने वाले दूसरे गेंदबाज़।"},
    {"q":"टेस्ट क्रिकेट में तिहरा शतक लगाने वाले पहले भारतीय कौन हैं?","o":["वीरेंद्र सहवाग","सुनील गावस्कर","राहुल द्रविड़","करुण नायर"],"a":0,"e":"सहवाग ने 2004 में मुल्तान में पाकिस्तान के विरुद्ध 309 रन बनाए (\"मुल्तान का सुल्तान\")। करुण नायर (303*, 2016, चेन्नई) दूसरे भारतीय हैं।"},
    {"q":"ODI क्रिकेट में पहला दोहरा शतक (200*, फ़रवरी 2010) किस मैदान पर बना?","o":["ईडन गार्डन्स, कोलकाता","ग्वालियर (कैप्टन रूप सिंह स्टेडियम)","वानखेड़े, मुंबई","इंदौर (होल्कर स्टेडियम)"],"a":1,"e":"सचिन तेंदुलकर ने दक्षिण अफ़्रीका के विरुद्ध ग्वालियर में ODI इतिहास का पहला दोहरा शतक बनाया।"},
    {"q":"ODI क्रिकेट का सर्वोच्च व्यक्तिगत स्कोर 264 रन (नवंबर 2014) किसने बनाया?","o":["मार्टिन गप्टिल","वीरेंद्र सहवाग","रोहित शर्मा","क्रिस गेल"],"a":2,"e":"रोहित शर्मा ने ईडन गार्डन्स में श्रीलंका के विरुद्ध 264 रन बनाए; ODI में तीन दोहरे शतक लगाने वाले वे एकमात्र बल्लेबाज़ हैं।"},
    {"q":"सचिन तेंदुलकर ने अपना 100वाँ अंतरराष्ट्रीय शतक (मार्च 2012) किस टीम के विरुद्ध बनाया?","o":["श्रीलंका","पाकिस्तान","दक्षिण अफ़्रीका","बांग्लादेश"],"a":3,"e":"एशिया कप 2012 में मीरपुर (ढाका) में बांग्लादेश के विरुद्ध — 51 टेस्ट + 49 ODI शतक = 100।"},
    {"q":"टेस्ट क्रिकेट में 10,000 रन पूरे करने वाले विश्व के पहले बल्लेबाज़ कौन थे?","o":["सुनील गावस्कर","एलन बॉर्डर","सचिन तेंदुलकर","डॉन ब्रैडमैन"],"a":0,"e":"गावस्कर ने मार्च 1987 में अहमदाबाद में पाकिस्तान के विरुद्ध 10,000 टेस्ट रन पूरे किए। उनके नाम 34 टेस्ट शतक थे, जो लंबे समय तक रिकॉर्ड रहा।"},
    {"q":"1983 विश्व कप में कपिल देव ने 175* रन की ऐतिहासिक पारी किस टीम के विरुद्ध खेली?","o":["वेस्ट इंडीज़","ज़िम्बाब्वे","ऑस्ट्रेलिया","इंग्लैंड"],"a":1,"e":"टनब्रिज वेल्स में ज़िम्बाब्वे के विरुद्ध भारत 17/5 पर संकट में था, तब कपिल ने 175* बनाए — उस समय का ODI सर्वोच्च स्कोर।"},
    {"q":"क्रिकेट विश्व कप में पहली हैट्रिक (1987) लेने वाले गेंदबाज़ कौन थे?","o":["कपिल देव","वसीम अकरम","चेतन शर्मा","मनोज प्रभाकर"],"a":2,"e":"चेतन शर्मा ने 1987 विश्व कप में नागपुर में न्यूज़ीलैंड के विरुद्ध हैट्रिक ली — विश्व कप इतिहास की पहली हैट्रिक।"},
    {"q":"टेस्ट क्रिकेट में हैट्रिक लेने वाले पहले भारतीय गेंदबाज़ कौन हैं?","o":["इरफ़ान पठान","अनिल कुंबले","जसप्रीत बुमराह","हरभजन सिंह"],"a":3,"e":"हरभजन सिंह ने मार्च 2001 में कोलकाता टेस्ट में ऑस्ट्रेलिया के विरुद्ध हैट्रिक ली। इरफ़ान पठान ने 2006 में कराची में टेस्ट के पहले ही ओवर में हैट्रिक ली।"},
    {"q":"सूची-I (एक ओवर में छह छक्के) को सूची-II (अवसर) से सुमेलित कीजिए —<br>(A) गैरी सोबर्स (B) रवि शास्त्री (C) हर्शल गिब्स (D) युवराज सिंह<br>1. T20 विश्व कप 2007, डरबन 2. ODI विश्व कप 2007, नीदरलैंड्स के विरुद्ध 3. रणजी ट्रॉफी 1985, बड़ौदा के विरुद्ध 4. काउंटी क्रिकेट 1968","o":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1"],"a":0,"e":"सोबर्स — 1968 नॉटिंघमशायर बनाम ग्लैमरगन (A-4); शास्त्री — 1985 बॉम्बे बनाम बड़ौदा (B-3); गिब्स — 2007 ODI विश्व कप, पहली बार अंतरराष्ट्रीय मैच में (C-2); युवराज — 2007 T20 विश्व कप, स्टुअर्ट ब्रॉड के ओवर में (D-1)।"},
    {"q":"टेस्ट क्रिकेट में 800 विकेट लेने वाले एकमात्र गेंदबाज़ कौन हैं?","o":["शेन वॉर्न","मुथैया मुरलीधरन","जेम्स एंडरसन","अनिल कुंबले"],"a":1,"e":"श्रीलंका के मुरलीधरन ने 2010 में अपने अंतिम टेस्ट की अंतिम गेंद पर 800वाँ विकेट लिया। भारत के लिए सर्वाधिक टेस्ट विकेट अनिल कुंबले (619) के नाम हैं।"},
    {"q":"डॉन ब्रैडमैन का टेस्ट बल्लेबाज़ी औसत कितना था?","o":["100.00","89.78","99.94","95.14"],"a":2,"e":"1948 में अंतिम पारी में शून्य पर आउट होने से वे 100 के औसत से चूक गए; केवल 4 रन चाहिए थे।"},
    {"q":"रणजी ट्रॉफी का पहला संस्करण (1934-35) किस टीम ने जीता?","o":["मद्रास","होल्कर","बड़ौदा","बॉम्बे"],"a":3,"e":"पहली रणजी ट्रॉफी बॉम्बे (मुंबई) ने जीती; मुंबई सर्वाधिक बार यह ट्रॉफी जीतने वाली टीम है।"},
    {"q":"सूची-I (घरेलू क्रिकेट ट्रॉफी) को सूची-II (प्रारूप/वर्ग) से सुमेलित कीजिए —<br>(A) दलीप ट्रॉफी (B) कूच बिहार ट्रॉफी (C) विजय हज़ारे ट्रॉफी (D) ईरानी कप<br>1. रणजी विजेता बनाम शेष भारत 2. अंडर-19 बहु-दिवसीय 3. अंतर-क्षेत्रीय प्रथम श्रेणी 4. राज्य स्तरीय एकदिवसीय (लिस्ट-A)","o":["A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-3, B-2, C-1, D-4","A-1, B-2, C-4, D-3"],"a":0,"e":"दलीप ट्रॉफी (1961-62) — अंतर-क्षेत्रीय (A-3); कूच बिहार — अंडर-19 बहु-दिवसीय (B-2); विजय हज़ारे — एकदिवसीय (C-4); ईरानी कप — रणजी विजेता बनाम शेष भारत (D-1)।"},
    {"q":"अंतरराष्ट्रीय क्रिकेट परिषद (ICC) के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. ICC की स्थापना 1909 में \"इंपीरियल क्रिकेट कॉन्फ़्रेंस\" के रूप में इंग्लैंड, ऑस्ट्रेलिया और दक्षिण अफ़्रीका ने की।<br>2. क्रिकेट के नियमों (Laws of Cricket) का संरक्षक ICC नहीं, बल्कि मेरिलबोन क्रिकेट क्लब (MCC) है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 1909 में इंपीरियल क्रिकेट कॉन्फ़्रेंस; 1965 में इंटरनेशनल क्रिकेट कॉन्फ़्रेंस, 1989 में वर्तमान नाम। कथन 2 सही — नियमों का कॉपीराइट लॉर्ड्स स्थित MCC के पास है।"},
    {"q":"अभिकथन (A): इंग्लैंड-ऑस्ट्रेलिया टेस्ट श्रृंखला को \"एशेज़\" कहा जाता है।<br>कारण (R): 1882 में ओवल में ऑस्ट्रेलिया की जीत के बाद एक अंग्रेज़ी समाचार-पत्र ने इंग्लिश क्रिकेट की व्यंग्यात्मक \"मृत्यु-सूचना\" छापी थी, जिसमें राख (ऐशेज़) का उल्लेख था।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही, R सही और यही नाम की उत्पत्ति है — \"स्पोर्टिंग टाइम्स\" ने लिखा कि शव जला दिया गया और राख ऑस्ट्रेलिया ले जाई जाएगी; अगली श्रृंखला \"राख वापस लाने\" की श्रृंखला बनी।"},
    {"q":"सूची-I (द्विपक्षीय क्रिकेट ट्रॉफी) को सूची-II (देश) से सुमेलित कीजिए —<br>(A) फ़्रैंक वॉरेल ट्रॉफी (B) गांधी–मंडेला ट्रॉफी (C) बेसिल डी'ओलिवेरा ट्रॉफी (D) चैपल–हैडली ट्रॉफी<br>1. इंग्लैंड–दक्षिण अफ़्रीका 2. ऑस्ट्रेलिया–न्यूज़ीलैंड (ODI) 3. ऑस्ट्रेलिया–वेस्ट इंडीज़ 4. भारत–दक्षिण अफ़्रीका","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2"],"a":1,"e":"फ़्रैंक वॉरेल — ऑस्ट्रेलिया–वेस्ट इंडीज़ (A-3); गांधी–मंडेला (2015 से, पहले \"फ़्रीडम ट्रॉफी\") — भारत–दक्षिण अफ़्रीका (B-4); डी'ओलिवेरा — इंग्लैंड–दक्षिण अफ़्रीका (C-1); चैपल–हैडली — ऑस्ट्रेलिया–न्यूज़ीलैंड (D-2)।"},
    {"q":"पहला महिला क्रिकेट विश्व कप किस वर्ष और कहाँ आयोजित हुआ?","o":["1975, इंग्लैंड","1978, भारत","1982, न्यूज़ीलैंड","1973, इंग्लैंड"],"a":3,"e":"महिला विश्व कप (1973, इंग्लैंड) पुरुष विश्व कप (1975) से दो वर्ष पहले हुआ और इंग्लैंड ने जीता। भारत ने 1978 में पहली बार मेज़बानी की।"},
    {"q":"पुरुष एकल में सर्वाधिक 24 ग्रैंड स्लैम ख़िताब जीतने का रिकॉर्ड किसके नाम है (2025 तक)?","o":["राफ़ेल नडाल","नोवाक जोकोविच","रोजर फ़ेडरर","पीट सम्प्रास"],"a":1,"e":"जोकोविच ने 2023 यूएस ओपन जीतकर 24वाँ ग्रैंड स्लैम पाया; नडाल 22 और फ़ेडरर 20 पर रहे। महिलाओं में मार्गरेट कोर्ट के 24 हैं।"},
    {"q":"विंबलडन पुरुष एकल सर्वाधिक 8 बार जीतने वाले खिलाड़ी कौन हैं?","o":["पीट सम्प्रास","नोवाक जोकोविच","रोजर फ़ेडरर","ब्योर्न बोर्ग"],"a":2,"e":"फ़ेडरर ने 8 विंबलडन (अंतिम 2017) जीते; जोकोविच 7 और सम्प्रास 7। महिलाओं में मार्टिना नवरातिलोवा के 9 विंबलडन एकल हैं।"},
    {"q":"एक ही वर्ष में चारों ग्रैंड स्लैम और ओलंपिक स्वर्ण जीतकर \"गोल्डन स्लैम\" (1988) पूरा करने वाली खिलाड़ी कौन हैं?","o":["मार्टिना नवरातिलोवा","सेरेना विलियम्स","मोनिका सेलेस","स्टेफ़ी ग्राफ़"],"a":3,"e":"जर्मनी की स्टेफ़ी ग्राफ़ ने 1988 में चारों ग्रैंड स्लैम और सियोल ओलंपिक स्वर्ण जीता — एकल में अब तक एकमात्र कैलेंडर गोल्डन स्लैम।"},
    {"q":"पुरुष एकल में दो बार (1962, 1969) कैलेंडर ग्रैंड स्लैम जीतने वाले एकमात्र खिलाड़ी कौन हैं?","o":["रॉड लेवर","डॉन बज","रॉय एमर्सन","ब्योर्न बोर्ग"],"a":0,"e":"ऑस्ट्रेलिया के रॉड लेवर ने 1962 और 1969 में एक ही वर्ष में चारों ग्रैंड स्लैम जीते। पहला कैलेंडर ग्रैंड स्लैम डॉन बज (1938) का था।"},
    {"q":"टेनिस की टीम प्रतियोगिताओं के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. डेविस कप 1900 में अमेरिका और ब्रिटेन के बीच मुक़ाबले से आरंभ हुआ।<br>2. महिलाओं का \"फ़ेड कप\" 2020 में \"बिली जीन किंग कप\" नाम से जाना जाने लगा।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — अमेरिकी खिलाड़ी ड्वाइट डेविस ने ट्रॉफी दान की; पहला मुक़ाबला 1900 में। कथन 2 सही — 1963 में शुरू फ़ेड कप का नाम 2020 में बिली जीन किंग कप हुआ।"},
    {"q":"विंबलडन एकल के सेमीफ़ाइनल में (1960 व 1961) पहुँचने वाले भारतीय टेनिस खिलाड़ी कौन थे?","o":["विजय अमृतराज","रामनाथन कृष्णन","आनंद अमृतराज","जयदीप मुखर्जी"],"a":1,"e":"रामनाथन कृष्णन लगातार दो वर्ष विंबलडन सेमीफ़ाइनल में पहुँचे — ग्रैंड स्लैम एकल में किसी भारतीय का सर्वश्रेष्ठ प्रदर्शन। उनके पुत्र रमेश कृष्णन भी प्रसिद्ध खिलाड़ी रहे।"},
    {"q":"लिएंडर पेस–महेश भूपति जोड़ी के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. इस जोड़ी ने 1999 में फ़्रेंच ओपन और विंबलडन — दोनों का पुरुष युगल ख़िताब जीता।<br>2. यह जोड़ी 1999 में चारों ग्रैंड स्लैम के पुरुष युगल फ़ाइनल में पहुँची।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 1999 में फ़्रेंच ओपन और विंबलडन युगल जीते (2001 में फिर फ़्रेंच ओपन)। कथन 2 सही — 1999 में चारों ग्रैंड स्लैम के फ़ाइनल खेले; इसी वर्ष यह जोड़ी विश्व नंबर 1 बनी।"},
    {"q":"WTA एकल ख़िताब जीतने वाली पहली भारतीय महिला कौन हैं?","o":["निरुपमा वैद्यनाथन","अंकिता रैना","रुतुजा भोसले","सानिया मिर्ज़ा"],"a":3,"e":"सानिया मिर्ज़ा ने फ़रवरी 2005 में हैदराबाद ओपन जीतकर पहला WTA एकल ख़िताब पाया। 2015 में वे महिला युगल में विश्व नंबर 1 बनीं।"},
    {"q":"विंबलडन टेनिस प्रतियोगिता के पहले (1877) पुरुष एकल विजेता कौन थे?","o":["स्पेंसर गोर","विलियम रेनशॉ","फ़्रेड पेरी","आर्थर गोर"],"a":0,"e":"1877 में ऑल इंग्लैंड क्लब में पहली विंबलडन प्रतियोगिता हुई, जिसे स्पेंसर गोर ने जीता — यह विश्व की सबसे पुरानी टेनिस प्रतियोगिता है।"},
    {"q":"विश्व बैडमिंटन महासंघ (BWF) का मुख्यालय कहाँ है?","o":["जकार्ता","क्वालालंपुर","लंदन","कोपेनहेगन"],"a":1,"e":"BWF (1934 में \"अंतरराष्ट्रीय बैडमिंटन महासंघ\" के रूप में स्थापित) का मुख्यालय मलेशिया की राजधानी क्वालालंपुर में है।"},
    {"q":"निम्नलिखित बैडमिंटन टीम प्रतियोगिताओं को उनके आरंभ के कालक्रम में व्यवस्थित कीजिए —<br>1. सुदीरमन कप<br>2. थॉमस कप<br>3. उबेर कप","o":["3, 2, 1","2, 1, 3","1, 2, 3","2, 3, 1"],"a":3,"e":"थॉमस कप (पुरुष, 1948-49) → उबेर कप (महिला, 1956-57) → सुदीरमन कप (मिश्रित, 1989 जकार्ता)। अतः 2, 3, 1।"},
    {"q":"ऑल इंग्लैंड बैडमिंटन चैंपियनशिप के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. प्रकाश पादुकोण ने 1980 में पुरुष एकल ख़िताब जीता।<br>2. पुलेला गोपीचंद ने 2001 में पुरुष एकल ख़िताब जीता।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 1980 में पादुकोण यह ख़िताब जीतने वाले पहले भारतीय बने। कथन 2 सही — गोपीचंद 2001 में दूसरे भारतीय विजेता; बाद में वे सिंधु व साइना के कोच बने।"},
    {"q":"महिला बैडमिंटन में विश्व नंबर 1 रैंकिंग (2015) पाने वाली पहली भारतीय कौन हैं?","o":["साइना नेहवाल","पी. वी. सिंधु","ज्वाला गुट्टा","अपर्णा पोपट"],"a":0,"e":"साइना नेहवाल अप्रैल 2015 में विश्व नंबर 1 बनीं; लंदन 2012 में वे ओलंपिक बैडमिंटन पदक जीतने वाली पहली भारतीय भी बनीं।"},
    {"q":"शतरंज का प्राचीन भारतीय रूप किस नाम से जाना जाता था?","o":["पच्चीसी","चतुरंग","चौपड़","शतपद"],"a":1,"e":"गुप्त काल में \"चतुरंग\" खेला जाता था — सेना के चार अंगों (पैदल, अश्व, गज, रथ) के आधार पर। यही फ़ारस होकर \"शतरंज\" बना।"},
    {"q":"पहले आधिकारिक विश्व शतरंज चैंपियन (1886) कौन थे?","o":["इमैनुअल लास्कर","जोसे राउल कापाब्लांका","पॉल मॉर्फ़ी","विल्हेम स्टाइनिट्ज़"],"a":3,"e":"स्टाइनिट्ज़ ने 1886 में ज़ुकरटॉर्ट को हराकर पहला आधिकारिक विश्व ख़िताब जीता। गुकेश (2024) 18वें निर्विवाद विश्व चैंपियन हैं।"},
    {"q":"1997 में IBM के कंप्यूटर \"डीप ब्लू\" से मैच हारने वाले विश्व शतरंज चैंपियन कौन थे?","o":["गैरी कास्परोव","अनातोली कार्पोव","विश्वनाथन आनंद","व्लादिमीर क्रैमनिक"],"a":0,"e":"मई 1997 में डीप ब्लू ने कास्परोव को 6 खेलों के मैच में हराया — किसी मौजूदा विश्व चैंपियन पर कंप्यूटर की पहली मैच-जीत।"},
    {"q":"पहला आधिकारिक शतरंज ओलंपियाड (1927) कहाँ आयोजित हुआ?","o":["पेरिस","लंदन","मॉस्को","बुडापेस्ट"],"a":1,"e":"FIDE द्वारा आयोजित पहला आधिकारिक शतरंज ओलंपियाड 1927 में लंदन में हुआ; विजेता हंगरी। भारत ने पहली बार 2022 में (मामल्लपुरम) मेज़बानी की।"},
    {"q":"मैग्नस कार्लसन के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. उन्होंने 2013 में चेन्नई में विश्वनाथन आनंद को हराकर पहला विश्व ख़िताब जीता।<br>2. उन्होंने 2023 में स्वेच्छा से विश्व चैंपियनशिप मैच न खेलने का निर्णय लिया, जिसके बाद डिंग लिरेन चैंपियन बने।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 2013 चेन्नई में आनंद को हराया; 2014 सोची में फिर हराया। कथन 2 सही — कार्लसन (5 बार चैंपियन: 2013, 2014, 2016, 2018, 2021) ने ख़िताब नहीं बचाया; 2023 में डिंग लिरेन ने नेपोम्नियाची को हराया।"},
    {"q":"आर. प्रज्ञानानंद लगभग कितनी आयु में (2018) ग्रैंडमास्टर बने, जो तब विश्व में दूसरा सबसे कम आयु का रिकॉर्ड था?","o":["15 वर्ष","14 वर्ष","16 वर्ष","12 वर्ष"],"a":3,"e":"प्रज्ञानानंद 2018 में 12 वर्ष 10 महीने की आयु में GM बने — तब सर्गेई कर्याकिन के बाद दूसरे सबसे युवा। उनकी बहन आर. वैशाली भी GM हैं।"},
    {"q":"पुरुष 100 मीटर दौड़ का विश्व रिकॉर्ड (9.58 सेकंड) उसैन बोल्ट ने किस प्रतियोगिता में बनाया?","o":["2009 बर्लिन विश्व चैंपियनशिप","2008 बीजिंग ओलंपिक","2012 लंदन ओलंपिक","2011 डेगू विश्व चैंपियनशिप"],"a":0,"e":"अगस्त 2009 में बर्लिन विश्व चैंपियनशिप में बोल्ट ने 9.58 सेकंड (100 मी) और 19.19 सेकंड (200 मी) के विश्व रिकॉर्ड बनाए।"},
    {"q":"अभिकथन (A): पी. टी. उषा 1984 लॉस एंजिलिस ओलंपिक में 400 मी बाधा दौड़ का पदक नहीं जीत सकीं।<br>कारण (R): वे कांस्य पदक से एक सेकंड के सौवें भाग (1/100 सेकंड) से चूक गईं और चौथे स्थान पर रहीं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही और R ही उसका कारण है — उषा 400 मी बाधा दौड़ के फ़ाइनल में चौथी रहीं; ओलंपिक ट्रैक फ़ाइनल में पहुँचने वाली वे पहली भारतीय महिला थीं।"},
    {"q":"विश्व अंडर-20 एथलेटिक्स चैंपियनशिप (2018, टैम्पेरे) में 400 मी का स्वर्ण जीतने वाली भारतीय कौन हैं?","o":["दुती चंद","हिमा दास","एस. धनलक्ष्मी","पूवम्मा"],"a":1,"e":"असम की हिमा दास (\"ढिंग एक्सप्रेस\") विश्व स्तर की ट्रैक स्पर्धा में स्वर्ण जीतने वाली पहली भारतीय बनीं।"},
    {"q":"मैराथन दौड़ किस ऐतिहासिक घटना की स्मृति से जुड़ी है?","o":["रोमन सेना का कूच","सिकंदर का भारत अभियान","यूनानी संदेशवाहक फ़िडिप्पिडीज़ की मैराथन से एथेंस तक दौड़","ट्रॉय का युद्ध"],"a":2,"e":"490 ई.पू. मैराथन के युद्ध में फ़ारस पर विजय का समाचार देने फ़िडिप्पिडीज़ के एथेंस दौड़ने की कथा से मैराथन का नाम पड़ा; 1896 एथेंस ओलंपिक से यह शामिल है।"},
    {"q":"विश्व निशानेबाज़ी चैंपियनशिप में व्यक्तिगत स्वर्ण जीतने वाले पहले भारतीय (2006, ज़ाग्रेब) कौन हैं?","o":["राज्यवर्धन सिंह राठौड़","गगन नारंग","जसपाल राणा","अभिनव बिंद्रा"],"a":3,"e":"अभिनव बिंद्रा 2006 में 10 मी एयर राइफ़ल के विश्व चैंपियन बने और 2008 बीजिंग में ओलंपिक स्वर्ण जीता — दोनों ख़िताब एक साथ रखने वाले पहले भारतीय।"},
    {"q":"अभिकथन (A): राज्यवर्धन सिंह राठौड़ का 2004 एथेंस रजत स्वतंत्र भारत का पहला व्यक्तिगत ओलंपिक रजत पदक था।<br>कारण (R): नॉर्मन प्रिचर्ड ने 1900 में भारत के लिए दो रजत पदक जीते थे।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — राठौड़ (डबल ट्रैप) से पहले स्वतंत्र भारत को कोई व्यक्तिगत रजत नहीं मिला था। R सही — प्रिचर्ड के 2 रजत (1900) औपनिवेशिक भारत के थे; R, A की व्याख्या नहीं करता।"},
    {"q":"डॉ. कर्णी सिंह शूटिंग रेंज कहाँ स्थित है?","o":["भोपाल","पुणे","नई दिल्ली (तुगलकाबाद)","जयपुर"],"a":2,"e":"2010 राष्ट्रमंडल खेलों की निशानेबाज़ी स्पर्धाएँ दिल्ली की इसी रेंज में हुईं; कर्णी सिंह बीकानेर के महाराजा और ओलंपिक निशानेबाज़ थे।"},
    {"q":"मुक्केबाज़ एम. सी. मैरी कॉम के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. वे छह बार विश्व एमेच्योर मुक्केबाज़ी चैंपियन बनीं।<br>2. उन्होंने लंदन 2012 ओलंपिक में 51 किग्रा वर्ग में रजत पदक जीता।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — 2002, 2005, 2006, 2008, 2010 व 2018 में विश्व चैंपियन। कथन 2 गलत — 2012 में उन्हें कांस्य मिला था। 2016 में वे राज्यसभा के लिए मनोनीत हुईं।"},
    {"q":"निकहत ज़रीन ने किन वर्षों में विश्व महिला मुक्केबाज़ी चैंपियनशिप का स्वर्ण जीता?","o":["2018 और 2019","2019 और 2022","2023 और 2024","2022 और 2023"],"a":3,"e":"तेलंगाना की निकहत ज़रीन ने 2022 (इस्तांबुल) और 2023 (नई दिल्ली) में स्वर्ण जीता; वे मैरी कॉम के बाद दो बार विश्व चैंपियन बनने वाली दूसरी भारतीय हैं।"},
    {"q":"मीराबाई चानू ने विश्व भारोत्तोलन चैंपियनशिप का स्वर्ण (2017) किस भार वर्ग में जीता?","o":["49 किग्रा","48 किग्रा","53 किग्रा","55 किग्रा"],"a":1,"e":"2017 अनाहाइम (अमेरिका) में 48 किग्रा स्वर्ण — कर्णम मल्लेश्वरी (1994–95) के बाद विश्व चैंपियन बनने वाली भारतीय। टोक्यो 2020 में उन्होंने 49 किग्रा रजत जीता।"},
    {"q":"\"रुस्तम-ए-ज़माँ\" की उपाधि पाने वाले प्रसिद्ध पहलवान \"द ग्रेट गामा\" का वास्तविक नाम क्या था?","o":["ग़ुलाम मोहिउद्दीन","दारा सिंह रंधावा","ग़ुलाम मोहम्मद बख़्श","इमाम बख़्श"],"a":2,"e":"गामा पहलवान (ग़ुलाम मोहम्मद बख़्श) 1910 में लंदन में विश्व हैवीवेट ख़िताब के दावेदार बने और जीवनभर अपराजित रहे माने जाते हैं। इमाम बख़्श उनके भाई थे।"},
    {"q":"माउंट एवरेस्ट आरोहण के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. संतोष यादव दो बार एवरेस्ट पर चढ़ने वाली विश्व की पहली महिला हैं।<br>2. अरुणिमा सिन्हा एवरेस्ट पर चढ़ने वाली विश्व की पहली महिला दिव्यांग (कृत्रिम पैर) पर्वतारोही हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — संतोष यादव ने 1992 और 1993 में एवरेस्ट फ़तह किया। कथन 2 सही — अरुणिमा सिन्हा (पूर्व राष्ट्रीय वॉलीबॉल खिलाड़ी) ने 2013 में यह उपलब्धि पाई।"},
    {"q":"माउंट एवरेस्ट पर पहुँचने वाले पहले भारतीय (1965) कौन थे?","o":["नवांग गोम्बू","तेनज़िंग नोर्गे","मोहन सिंह कोहली","अवतार सिंह चीमा"],"a":3,"e":"20 मई 1965 को कैप्टन एम. एस. कोहली के नेतृत्व वाले अभियान में अवतार सिंह चीमा भारत के पहले एवरेस्ट विजेता बने; उनके साथ नवांग गोम्बू थे, जो दो बार एवरेस्ट चढ़ने वाले पहले व्यक्ति बने।"},
    {"q":"2014 में 13 वर्ष की आयु में एवरेस्ट पर चढ़कर सबसे कम आयु की महिला पर्वतारोही बनने वाली भारतीय कौन हैं?","o":["मालावत पूर्णा","बछेंद्री पाल","प्रेमलता अग्रवाल","अंशु जामसेंपा"],"a":0,"e":"तेलंगाना की मालावत पूर्णा ने मई 2014 में एवरेस्ट फ़तह किया। अंशु जामसेंपा एक ही सीज़न में दो बार एवरेस्ट चढ़ने वाली पहली महिला हैं।"},
    {"q":"इंग्लिश चैनल तैराकी के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. मिहिर सेन 1958 में इंग्लिश चैनल पार करने वाले पहले भारतीय (और पहले एशियाई) बने।<br>2. आरती साहा 1959 में इंग्लिश चैनल पार करने वाली पहली एशियाई महिला बनीं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — मिहिर सेन ने 1958 में चैनल पार किया; 1966 में उन्होंने पाँच महाद्वीपों के समुद्री जलडमरूमध्य पार किए। कथन 2 सही — आरती साहा 1960 में पद्मश्री पाने वाली पहली भारतीय खिलाड़ी महिला बनीं।"},
    {"q":"एक ही ओलंपिक (2008 बीजिंग) में 8 स्वर्ण पदक जीतने का रिकॉर्ड किस तैराक के नाम है?","o":["मार्क स्पिट्ज़","माइकल फ़ेल्प्स","इयान थॉर्प","रयान लोक्टे"],"a":1,"e":"फ़ेल्प्स ने 2008 में 8 स्वर्ण जीतकर मार्क स्पिट्ज़ (7 स्वर्ण, 1972) का रिकॉर्ड तोड़ा; उनके कुल 23 ओलंपिक स्वर्ण (28 पदक) हैं।"},
    {"q":"फ़ॉर्मूला-1 रेस में भाग लेने वाले पहले भारतीय ड्राइवर (2005) कौन थे?","o":["करुण चंडोक","जेहान दारूवाला","अर्जुन मैनी","नारायण कार्तिकेयन"],"a":3,"e":"तमिलनाडु के नारायण कार्तिकेयन ने 2005 में जॉर्डन टीम से F1 में पदार्पण किया; करुण चंडोक (2010) दूसरे भारतीय F1 ड्राइवर बने।"},
    {"q":"इंडियन ग्रां प्री (फ़ॉर्मूला-1) के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. यह ग्रेटर नोएडा के बुद्ध इंटरनेशनल सर्किट पर 2011 से 2013 तक आयोजित हुई।<br>2. तीनों संस्करण सेबेस्टियन वेटेल ने जीते।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — भारत में केवल तीन F1 रेस (2011–13) हुईं। कथन 2 सही — तीनों रेड बुल के वेटेल ने जीतीं। F1 में सर्वाधिक 7 विश्व ख़िताब शूमाकर और हैमिल्टन के हैं।"},
    {"q":"अमेरिकी PGA टूर प्रतियोगिता जीतने वाले पहले भारतीय मूल के गोल्फ़र (2010) कौन हैं?","o":["अर्जुन अटवाल","जीव मिल्खा सिंह","ज्योति रंधावा","अनिर्बान लाहिड़ी"],"a":0,"e":"अर्जुन अटवाल ने अगस्त 2010 में विंडहैम चैंपियनशिप जीती। जीव मिल्खा सिंह (मिल्खा सिंह के पुत्र) भी अंतरराष्ट्रीय ख्याति के भारतीय गोल्फ़र हैं।"},
    {"q":"मास्टर्स गोल्फ़ टूर्नामेंट, जिसके विजेता को \"ग्रीन जैकेट\" मिलती है, स्थायी रूप से कहाँ खेला जाता है?","o":["सेंट एंड्रयूज़ (स्कॉटलैंड)","ऑगस्टा (जॉर्जिया, अमेरिका)","पेबल बीच (कैलिफ़ोर्निया)","विंटवर्थ (इंग्लैंड)"],"a":1,"e":"मास्टर्स चार पुरुष \"मेजर\" में से एकमात्र है जो हर वर्ष एक ही स्थान — ऑगस्टा नेशनल गोल्फ़ क्लब — पर होता है। सेंट एंड्रयूज़ को \"गोल्फ़ का घर\" कहा जाता है।"},
    {"q":"बिलियर्ड्स में विश्व ख़िताब जीतने वाले पहले भारतीय (1958) कौन थे?","o":["माइकल फ़ेरेरा","गीत सेठी","पंकज आडवाणी","विल्सन जोन्स"],"a":3,"e":"विल्सन जोन्स 1958 में विश्व एमेच्योर बिलियर्ड्स चैंपियन बने और 1964 में पुनः जीते; बाद में माइकल फ़ेरेरा, गीत सेठी और पंकज आडवाणी ने यह परंपरा बढ़ाई।"},
    {"q":"बिलियर्ड्स और स्नूकर — दोनों के विश्व ख़िताब जीतने के लिए प्रसिद्ध भारतीय क्यू-खिलाड़ी कौन हैं?","o":["पंकज आडवाणी","गीत सेठी","आदित्य मेहता","यासिन मर्चेंट"],"a":0,"e":"पंकज आडवाणी के नाम बिलियर्ड्स और स्नूकर दोनों में अनेक IBSF विश्व ख़िताब हैं; उन्हें 2006 में खेल रत्न मिला।"},
    {"q":"भारत के निम्नलिखित खेल संस्थानों को उनकी स्थापना के कालक्रम में व्यवस्थित कीजिए —<br>1. भारतीय खेल प्राधिकरण (SAI)<br>2. लक्ष्मीबाई राष्ट्रीय शारीरिक शिक्षा संस्थान (LNIPE), ग्वालियर<br>3. नेताजी सुभाष राष्ट्रीय खेल संस्थान (NIS), पटियाला<br>4. राष्ट्रीय खेल विश्वविद्यालय, मणिपुर","o":["3, 2, 1, 4","2, 3, 1, 4","2, 1, 3, 4","3, 1, 2, 4"],"a":1,"e":"LNIPE ग्वालियर 1957 → NIS पटियाला 1961 → SAI 1984 → राष्ट्रीय खेल विश्वविद्यालय (इम्फाल) 2018। अतः 2, 3, 1, 4।"},
    {"q":"\"फ़िट इंडिया मूवमेंट\" किस तिथि को आरंभ किया गया?","o":["15 अगस्त 2018","21 जून 2015","2 अक्टूबर 2019","29 अगस्त 2019"],"a":3,"e":"प्रधानमंत्री ने राष्ट्रीय खेल दिवस 29 अगस्त 2019 को फ़िट इंडिया मूवमेंट शुरू किया। 21 जून अंतरराष्ट्रीय योग दिवस है।"},
    {"q":"भारत की खेल योजनाओं के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. टारगेट ओलंपिक पोडियम स्कीम (TOPS) 2014 में आरंभ हुई।<br>2. पहले खेलो इंडिया स्कूल गेम्स 2018 में नई दिल्ली में आयोजित हुए।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — TOPS (सितंबर 2014) ओलंपिक संभावित खिलाड़ियों को सहायता देती है। कथन 2 सही — जनवरी-फ़रवरी 2018 में दिल्ली में पहले खेलो इंडिया स्कूल गेम्स; बाद में इन्हें \"यूथ गेम्स\" कहा गया।"},
    {"q":"पहला कबड्डी विश्व कप (2004) कहाँ आयोजित हुआ?","o":["मुंबई","अहमदाबाद","पटना","नई दिल्ली"],"a":0,"e":"2004 में मुंबई में पहला कबड्डी विश्व कप हुआ, भारत ने फ़ाइनल में ईरान को हराया। 2007 (पनवेल) और 2016 (अहमदाबाद) में भी भारत विजेता रहा।"},
    {"q":"\"राष्ट्रीय खेल\" (National Games) का पहला आयोजन 1924 में किस नाम और स्थान पर हुआ?","o":["अखिल भारतीय खेल, दिल्ली","भारतीय ओलंपिक खेल, लाहौर","राष्ट्रीय क्रीड़ा, कलकत्ता","भारतीय एथलेटिक मीट, बंबई"],"a":1,"e":"1924 में लाहौर में \"भारतीय ओलंपिक खेल\" के रूप में आरंभ हुए राष्ट्रीय खेल 1940 के बाद \"राष्ट्रीय खेल\" कहलाए; आधुनिक ओलंपिक-शैली का पहला संस्करण 1985 में दिल्ली में हुआ।"},
    {"q":"सूची-I (खिलाड़ी) को सूची-II (खेल) से सुमेलित कीजिए —<br>(A) विल्सन जोन्स (B) अर्जुन अटवाल (C) नारायण कार्तिकेयन (D) रामनाथन कृष्णन<br>1. मोटर रेसिंग 2. टेनिस 3. बिलियर्ड्स 4. गोल्फ़","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"a":3,"e":"विल्सन जोन्स — बिलियर्ड्स (A-3); अर्जुन अटवाल — गोल्फ़ (B-4); कार्तिकेयन — F1 मोटर रेसिंग (C-1); रामनाथन कृष्णन — टेनिस (D-2)।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (खिलाड़ी — उपलब्धि) सही सुमेलित नहीं है?","o":["मालावत पूर्णा — एवरेस्ट आरोहण करने वाली पहली भारतीय महिला","मिहिर सेन — इंग्लिश चैनल पार करने वाले पहले भारतीय","अवतार सिंह चीमा — एवरेस्ट पर पहुँचने वाले पहले भारतीय","अरुणिमा सिन्हा — एवरेस्ट पर पहुँचने वाली पहली दिव्यांग महिला"],"a":0,"e":"मालावत पूर्णा (2014) एवरेस्ट चढ़ने वाली सबसे कम आयु की महिला हैं; पहली भारतीय महिला बछेंद्री पाल (1984) थीं। शेष तीनों युग्म सही हैं।"},
    {"q":"भारतीय शतरंज के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. कोनेरू हम्पी ने 2019 में विश्व रैपिड शतरंज (महिला) चैंपियनशिप जीती।<br>2. भारत ने पहली बार शतरंज ओलंपियाड की मेज़बानी 2022 में मामल्लपुरम (तमिलनाडु) में की।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — हम्पी ने 2019 मॉस्को में विश्व रैपिड ख़िताब जीता (दिसंबर 2024 में दूसरी बार)। कथन 2 सही — 44वाँ ओलंपियाड 2022 मामल्लपुरम में; इसी से ओलंपियाड मशाल रिले की परंपरा शुरू हुई।"},
    {"q":"निम्नलिखित ओलंपिक पदकों को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. साइना नेहवाल का कांस्य (बैडमिंटन)<br>2. विजेंदर सिंह का कांस्य (मुक्केबाज़ी)<br>3. कर्णम मल्लेश्वरी का कांस्य (भारोत्तोलन)<br>4. लवलीना बोरगोहेन का कांस्य (मुक्केबाज़ी)","o":["2, 3, 1, 4","3, 2, 1, 4","3, 1, 2, 4","3, 2, 4, 1"],"a":1,"e":"मल्लेश्वरी 2000 सिडनी → विजेंदर 2008 बीजिंग → साइना 2012 लंदन → लवलीना 2020 टोक्यो। अतः 3, 2, 1, 4।"},
    {"q":"सूची-I (खिलाड़ी) को सूची-II (उपलब्धि) से सुमेलित कीजिए —<br>(A) अभिनव बिंद्रा (B) तेजस्विनी सावंत (C) हिमा दास (D) मीराबाई चानू<br>1. 2017 विश्व भारोत्तोलन चैंपियन 2. 2006 विश्व निशानेबाज़ी चैंपियन (एयर राइफ़ल) 3. 2018 विश्व U-20 400 मी चैंपियन 4. 2010 विश्व निशानेबाज़ी चैंपियन (50 मी राइफ़ल प्रोन)","o":["A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1"],"a":3,"e":"बिंद्रा — 2006 ज़ाग्रेब (A-2); तेजस्विनी — 2010 म्यूनिख, पहली भारतीय महिला विश्व चैंपियन (B-4); हिमा — 2018 टैम्पेरे (C-3); मीराबाई — 2017 अनाहाइम (D-1)।"},
    {"q":"अभिकथन (A): 1974 के डेविस कप फ़ाइनल में भारत और दक्षिण अफ़्रीका के बीच कोई मैच नहीं खेला गया।<br>कारण (R): भारत ने दक्षिण अफ़्रीका की रंगभेद नीति के विरोध में फ़ाइनल खेलने से इनकार कर दिया था।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A और R दोनों सही, R ही कारण है — भारत के बहिष्कार से दक्षिण अफ़्रीका बिना खेले विजेता घोषित हुआ; किसी डेविस कप फ़ाइनल का एकमात्र वॉकओवर।"},
    {"q":"अभिकथन (A): टेनिस में \"गोल्डन स्लैम\" को \"कैलेंडर ग्रैंड स्लैम\" से भी कठिन माना जाता है।<br>कारण (R): गोल्डन स्लैम में चारों ग्रैंड स्लैम के साथ ओलंपिक स्वर्ण भी जीतना होता है, जो चार वर्ष में एक बार होता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A और R सही, R ही व्याख्या है — इसलिए एकल में केवल स्टेफ़ी ग्राफ़ (1988) एक ही वर्ष में गोल्डन स्लैम पूरा कर सकीं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (ट्रॉफी — खेल) सही सुमेलित नहीं है?","o":["थॉमस कप — पुरुष बैडमिंटन","सुदीरमन कप — टेबल टेनिस","स्वेथलिंग कप — पुरुष टेबल टेनिस","डेविस कप — पुरुष टेनिस"],"a":1,"e":"सुदीरमन कप मिश्रित टीम बैडमिंटन की प्रतियोगिता है (इंडोनेशिया के डिक सुदीरमन के नाम पर, 1989 से)। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. मुरलीकांत पेटकर ने 1972 हाइडेलबर्ग पैरालंपिक में तैराकी में भारत का पहला पैरालंपिक स्वर्ण जीता।<br>2. पैरालंपिक पदक जीतने वाली पहली भारतीय महिला अवनि लेखरा हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — पेटकर (1965 युद्ध में घायल सैनिक) ने 50 मी फ़्रीस्टाइल में स्वर्ण जीता; उन पर फ़िल्म \"चंदू चैंपियन\" बनी। कथन 2 गलत — पहली महिला पदक विजेता दीपा मलिक (2016, गोला फेंक रजत) हैं; अवनि पैरालंपिक स्वर्ण जीतने वाली पहली भारतीय महिला हैं।"},
    {"q":"1975 पुरुष हॉकी विश्व कप (कुआलालंपुर) फ़ाइनल में भारत के लिए विजयी गोल किसने किया?","o":["असलम शेर ख़ान","अजीतपाल सिंह","अशोक कुमार","सुरजीत सिंह"],"a":2,"e":"फ़ाइनल में भारत ने पाकिस्तान को 2-1 से हराया; निर्णायक गोल ध्यानचंद के पुत्र अशोक कुमार ने किया, कप्तान अजीतपाल सिंह थे।"},
    {"q":"हॉकी का पहला (1971) पुरुष विश्व कप किस शहर में आयोजित हुआ?","o":["एम्सटर्डम","कुआलालंपुर","लाहौर","बार्सिलोना"],"a":3,"e":"पहला हॉकी विश्व कप 1971 में बार्सिलोना (स्पेन) में हुआ, पाकिस्तान विजेता और भारत को कांस्य मिला। इसके विचारक पाकिस्तान के एयर मार्शल नूर ख़ान थे।"},
    {"q":"भारत रत्न के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. एक वर्ष में अधिकतम तीन व्यक्तियों को भारत रत्न दिया जा सकता है।<br>2. भारत रत्न का पदक पीपल के पत्ते के आकार का होता है, जिस पर सूर्य की आकृति अंकित होती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — सामान्य नियम अधिकतम तीन प्रति वर्ष (2024 में अपवादस्वरूप पाँच)। कथन 2 सही — कांस्य का पीपल-पत्र, एक ओर सूर्य व \"भारत रत्न\" (देवनागरी) तथा दूसरी ओर राष्ट्रीय प्रतीक।"},
    {"q":"वर्ष 1955 में भारत रत्न पाने वालों में निम्नलिखित में से कौन शामिल थे?","o":["सी. राजगोपालाचारी, एस. राधाकृष्णन और सी. वी. रमन","जवाहरलाल नेहरू, एम. विश्वेश्वरैया और भगवान दास","गोविंद बल्लभ पंत, डी. के. कर्वे और बी. सी. रॉय","राजेंद्र प्रसाद, ज़ाकिर हुसैन और पी. वी. काणे"],"a":1,"e":"1955 में नेहरू, सर एम. विश्वेश्वरैया (जिनकी जयंती 15 सितंबर अभियंता दिवस है) और डॉ. भगवान दास को भारत रत्न मिला। विकल्प A के व्यक्तियों (राजगोपालाचारी, राधाकृष्णन, रमन) को 1954 में मिला; पंत 1957, कर्वे 1958, बी. सी. रॉय 1961; राजेंद्र प्रसाद 1962, ज़ाकिर हुसैन व पी. वी. काणे 1963।"},
    {"q":"भारत रत्न प्राप्ति के कालक्रम में निम्नलिखित को व्यवस्थित कीजिए —<br>1. डॉ. बी. आर. आंबेडकर<br>2. के. कामराज<br>3. एम. विश्वेश्वरैया<br>4. ए. पी. जे. अब्दुल कलाम","o":["2, 3, 1, 4","3, 1, 2, 4","3, 2, 4, 1","3, 2, 1, 4"],"a":3,"e":"विश्वेश्वरैया 1955 → कामराज 1976 (मरणोपरांत) → आंबेडकर 1990 (मरणोपरांत) → कलाम 1997। अतः 3, 2, 1, 4।"},
    {"q":"भारत रत्न पाने वाली पहली संगीतज्ञ (1998) कौन हैं?","o":["लता मंगेशकर","एम. एस. सुब्बुलक्ष्मी","गंगूबाई हंगल","किशोरी अमोनकर"],"a":1,"e":"कर्नाटक संगीत की गायिका एम. एस. सुब्बुलक्ष्मी को 1998 में भारत रत्न मिला; 1974 में वे रेमन मैग्सेसे पाने वाली पहली संगीतज्ञ भी बनीं। लता मंगेशकर को 2001 में मिला।"},
    {"q":"सूची-I (भारत रत्न वर्ष) को सूची-II (प्राप्तकर्ता) से सुमेलित कीजिए —<br>(A) 1992 (B) 1999 (C) 2001 (D) 2019<br>1. लता मंगेशकर व बिस्मिल्लाह ख़ाँ 2. सत्यजीत रे व जे. आर. डी. टाटा 3. प्रणब मुखर्जी व भूपेन हज़ारिका 4. अमर्त्य सेन व पंडित रविशंकर","o":["A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3"],"a":2,"e":"1992 — सत्यजीत रे, जे. आर. डी. टाटा, मौलाना आज़ाद (A-2); 1999 — अमर्त्य सेन, रविशंकर, जयप्रकाश नारायण, गोपीनाथ बोरदोलोई (B-4); 2001 — लता व बिस्मिल्लाह ख़ाँ (C-1); 2019 — प्रणब, भूपेन हज़ारिका, नानाजी देशमुख (D-3)।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. सचिन तेंदुलकर भारत रत्न पाने वाले पहले खिलाड़ी और अब तक के सबसे कम आयु के प्राप्तकर्ता हैं।<br>2. सचिन तेंदुलकर के साथ 2014 में भारत रत्न पाने वाले दूसरे व्यक्ति वैज्ञानिक सी. एन. आर. राव थे।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — सचिन को 40 वर्ष की आयु में (घोषणा नवंबर 2013, प्रदान 2014) भारत रत्न मिला। कथन 2 सही — रसायनशास्त्री सी. एन. आर. राव को भी 2014 में यह सम्मान मिला।"},
    {"q":"परमवीर चक्र पाने वाले पहले व्यक्ति कौन थे?","o":["कैप्टन विक्रम बत्रा","लांस नायक करम सिंह","सेकंड लेफ़्टिनेंट राम राघोबा राणे","मेजर सोमनाथ शर्मा"],"a":3,"e":"मेजर सोमनाथ शर्मा को नवंबर 1947 में कश्मीर के बडगाम में पाकिस्तानी कबायली हमले के विरुद्ध वीरता के लिए मरणोपरांत पहला परमवीर चक्र मिला।"},
    {"q":"परमवीर चक्र के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. इसकी डिज़ाइन सावित्री खानोलकर ने तैयार की थी।<br>2. इस पर इंद्र के वज्र की आकृति अंकित है, जो महर्षि दधीचि के त्याग का प्रतीक है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — स्विस मूल की सावित्री खानोलकर (ईव यवोन मैडे) ने 1950 में डिज़ाइन बनाई। कथन 2 सही — कांस्य के गोल पदक पर चार वज्र अंकित हैं।"},
    {"q":"परमवीर चक्र पाने वाले भारतीय वायुसेना के एकमात्र अधिकारी कौन हैं?","o":["फ़्लाइंग ऑफ़िसर निर्मलजीत सिंह सेखों","स्क्वाड्रन लीडर अजमद बोपैया देवय्या","विंग कमांडर अभिनंदन वर्धमान","फ़्लाइट लेफ़्टिनेंट गुंजन सक्सेना"],"a":0,"e":"निर्मलजीत सिंह सेखों को 1971 के युद्ध में श्रीनगर हवाई अड्डे की रक्षा के लिए मरणोपरांत परमवीर चक्र मिला।"},
    {"q":"अंतरिक्ष में जाने वाले पहले भारतीय राकेश शर्मा को कौन-सा वीरता/शौर्य सम्मान दिया गया?","o":["परमवीर चक्र","अशोक चक्र","कीर्ति चक्र","वीर चक्र"],"a":1,"e":"1984 में सोयूज़ T-11 से अंतरिक्ष यात्रा के बाद राकेश शर्मा को शांतिकाल का सर्वोच्च वीरता सम्मान अशोक चक्र दिया गया। युद्धकाल का सर्वोच्च सम्मान परमवीर चक्र है।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (कारगिल युद्ध के परमवीर चक्र विजेता — स्थिति) सही सुमेलित नहीं है?","o":["कैप्टन विक्रम बत्रा — मरणोपरांत","कैप्टन मनोज कुमार पांडेय — मरणोपरांत","ग्रेनेडियर योगेंद्र सिंह यादव — जीवित रहते","मेजर सोमनाथ शर्मा — कारगिल 1999"],"a":3,"e":"सोमनाथ शर्मा 1947 के युद्ध के पहले परमवीर चक्र विजेता थे, कारगिल के नहीं। कारगिल के चार PVC — बत्रा व पांडेय (मरणोपरांत), योगेंद्र सिंह यादव व संजय कुमार (जीवित)।"},
    {"q":"पहला ज्ञानपीठ पुरस्कार (1965) किसे मिला?","o":["जी. शंकर कुरुप","ताराशंकर बंद्योपाध्याय","सुमित्रानंदन पंत","उमाशंकर जोशी"],"a":0,"e":"मलयालम कवि जी. शंकर कुरुप को उनकी कृति \"ओडक्कुझल\" (बाँसुरी) के लिए पहला ज्ञानपीठ मिला। पंत (1968) हिन्दी के पहले विजेता थे।"},
    {"q":"ज्ञानपीठ पुरस्कार के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. यह भारतीय ज्ञानपीठ न्यास द्वारा दिया जाता है, जिसकी स्थापना साहू शांति प्रसाद जैन ने की थी।<br>2. पुरस्कार में वाग्देवी (सरस्वती) की कांस्य प्रतिमा दी जाती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — भारतीय ज्ञानपीठ की स्थापना 1944 में साहू शांति प्रसाद जैन ने की। कथन 2 सही — वाग्देवी की प्रतिमा, प्रशस्ति-पत्र और ₹11 लाख की राशि दी जाती है।"},
    {"q":"अंग्रेज़ी भाषा में लेखन के लिए ज्ञानपीठ पुरस्कार पाने वाले पहले लेखक (2018) कौन हैं?","o":["विक्रम सेठ","अमिताव घोष","रस्किन बॉन्ड","सलमान रुश्दी"],"a":1,"e":"अमिताव घोष को 54वाँ ज्ञानपीठ (2018) मिला। उनकी प्रसिद्ध \"आइबिस त्रयी\" है।"},
    {"q":"सूची-I (हिन्दी के ज्ञानपीठ विजेता) को सूची-II (कृति) से सुमेलित कीजिए —<br>(A) सुमित्रानंदन पंत (B) रामधारी सिंह दिनकर (C) अज्ञेय (D) महादेवी वर्मा<br>1. यामा 2. कितनी नावों में कितनी बार 3. उर्वशी 4. चिदंबरा","o":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"a":3,"e":"पंत — चिदंबरा, 1968 (A-4); दिनकर — उर्वशी, 1972 (B-3); अज्ञेय — कितनी नावों में कितनी बार, 1978 (C-2); महादेवी — यामा, 1982 (D-1)।"},
    {"q":"हिन्दी भाषा के लिए पहला साहित्य अकादमी पुरस्कार (1955) किसे और किस कृति के लिए मिला?","o":["माखनलाल चतुर्वेदी — हिम तरंगिनी","रामधारी सिंह दिनकर — संस्कृति के चार अध्याय","सुमित्रानंदन पंत — कला और बूढ़ा चाँद","राहुल सांकृत्यायन — मध्य एशिया का इतिहास"],"a":0,"e":"साहित्य अकादमी (स्थापना 12 मार्च 1954) का पहला हिन्दी पुरस्कार 1955 में माखनलाल चतुर्वेदी (\"एक भारतीय आत्मा\") को \"हिम तरंगिनी\" के लिए मिला। दिनकर को 1959 में मिला।"},
    {"q":"के. के. बिड़ला फ़ाउंडेशन के पुरस्कारों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. पहला सरस्वती सम्मान (1991) हरिवंश राय बच्चन को उनकी आत्मकथा के लिए दिया गया।<br>2. पहला व्यास सम्मान (1991) रामविलास शर्मा को दिया गया।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — बच्चन की चार खंडों वाली आत्मकथा (\"क्या भूलूँ क्या याद करूँ\" आदि) के लिए। कथन 2 सही — व्यास सम्मान केवल हिन्दी कृतियों के लिए है; पहले विजेता रामविलास शर्मा।"},
    {"q":"भारत की पहली पूर्ण-लंबाई की फ़ीचर फ़िल्म \"राजा हरिश्चंद्र\" (1913) के निर्माता कौन थे, जिनके नाम पर भारतीय सिनेमा का सर्वोच्च सम्मान है?","o":["वी. शांताराम","दादासाहेब फाल्के","हिमांशु राय","अर्देशिर ईरानी"],"a":1,"e":"धुंडीराज गोविंद फाल्के (दादासाहेब) ने 1913 में \"राजा हरिश्चंद्र\" बनाई; 1969 से उनके नाम पर पुरस्कार दिया जाता है। अर्देशिर ईरानी ने पहली बोलती फ़िल्म \"आलम आरा\" (1931) बनाई।"},
    {"q":"सूची-I (दादासाहेब फाल्के पुरस्कार विजेता) को सूची-II (पुरस्कार वर्ष) से सुमेलित कीजिए —<br>(A) राज कपूर (B) लता मंगेशकर (C) दिलीप कुमार (D) अमिताभ बच्चन<br>1. 2018 2. 1994 3. 1989 4. 1987","o":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"a":3,"e":"राज कपूर — 1987 (A-4); लता मंगेशकर — 1989 (B-3); दिलीप कुमार — 1994 (C-2); अमिताभ बच्चन — 2018 (D-1)। रजनीकांत को 2019 का पुरस्कार मिला।"},
    {"q":"पहला राष्ट्रीय फ़िल्म पुरस्कार (स्वर्ण कमल) सर्वश्रेष्ठ फ़ीचर फ़िल्म के रूप में किस फ़िल्म को मिला?","o":["श्यामची आई (मराठी)","पाथेर पांचाली (बांग्ला)","दो बीघा ज़मीन (हिन्दी)","मदर इंडिया (हिन्दी)"],"a":0,"e":"आचार्य पी. के. अत्रे निर्देशित मराठी फ़िल्म \"श्यामची आई\" (साने गुरुजी की कृति पर आधारित) ने 1954 में पहला राष्ट्रपति स्वर्ण पदक जीता।"},
    {"q":"ऑस्कर (अकादमी पुरस्कार) और भारत के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. सत्यजीत रे को 1992 में मानद ऑस्कर (आजीवन उपलब्धि) प्रदान किया गया।<br>2. ए. आर. रहमान ने 2009 में \"स्लमडॉग मिलियनेयर\" के लिए दो ऑस्कर जीते।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — मृत्यु से कुछ सप्ताह पहले रे को कोलकाता में मानद ऑस्कर दिया गया। कथन 2 सही — रहमान को मूल संगीत और गीत \"जय हो\" के लिए दो ऑस्कर; रेसुल पूकुट्टी को ध्वनि-मिश्रण का ऑस्कर मिला।"},
    {"q":"95वें ऑस्कर (2023) में सर्वश्रेष्ठ मौलिक गीत का पुरस्कार किस भारतीय गीत को मिला?","o":["जय हो (स्लमडॉग मिलियनेयर)","नाटू नाटू (RRR)","छैयाँ छैयाँ (दिल से)","केसरिया (ब्रह्मास्त्र)"],"a":1,"e":"एम. एम. कीरवाणी (संगीत) और चंद्रबोस (गीत) को \"नाटू नाटू\" के लिए ऑस्कर मिला। इसी वर्ष \"द एलिफ़ेंट व्हिस्परर्स\" ने सर्वश्रेष्ठ लघु वृत्तचित्र का ऑस्कर जीता।"},
    {"q":"ग्रैमी पुरस्कार जीतने वाले पहले भारतीय (1968) कौन थे?","o":["ज़ाकिर हुसैन","ए. आर. रहमान","विश्व मोहन भट्ट","पंडित रविशंकर"],"a":3,"e":"रविशंकर को येहुदी मेनुहिन के साथ एल्बम \"वेस्ट मीट्स ईस्ट\" के लिए 1968 में ग्रैमी मिला। विश्व मोहन भट्ट को 1994 में ग्रैमी मिला।"},
    {"q":"कान फ़िल्म महोत्सव में शीर्ष पुरस्कार (ग्रां प्री, 1946) जीतने वाली पहली भारतीय फ़िल्म कौन-सी थी?","o":["नीचा नगर","दो बीघा ज़मीन","पाथेर पांचाली","सलाम बॉम्बे"],"a":0,"e":"चेतन आनंद की \"नीचा नगर\" ने 1946 के पहले कान महोत्सव में ग्रां प्री (तब का सर्वोच्च पुरस्कार) जीता। 2024 में पायल कपाड़िया की \"ऑल वी इमेजिन ऐज़ लाइट\" ने ग्रां प्री जीता।"},
    {"q":"वास्तुकला का \"नोबेल\" कहे जाने वाले प्रित्ज़कर पुरस्कार को पाने वाले पहले भारतीय (2018) कौन हैं?","o":["चार्ल्स कोरिया","बालकृष्ण दोशी","लॉरी बेकर","राज रेवाल"],"a":1,"e":"बी. वी. दोशी (अहमदाबाद) को 2018 में प्रित्ज़कर मिला; वे ले कॉर्बूज़िए के साथ चंडीगढ़ परियोजना में काम कर चुके थे। IIM बेंगलुरु का परिसर उनकी प्रसिद्ध कृति है।"},
    {"q":"गणित के अंतरराष्ट्रीय पुरस्कारों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. फ़ील्ड्स पदक हर चार वर्ष में 40 वर्ष से कम आयु के गणितज्ञों को दिया जाता है।<br>2. भारतीय मूल के मंजुल भार्गव (2014) और अक्षय वेंकटेश (2018) को फ़ील्ड्स पदक मिला।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — अंतरराष्ट्रीय गणितज्ञ कांग्रेस में हर चार वर्ष पर प्रदान। कथन 2 सही — भार्गव 2014 और वेंकटेश 2018। एस. आर. श्रीनिवास वर्धन को 2007 में एबेल पुरस्कार मिला।"},
    {"q":"गणित का एबेल पुरस्कार (2007) पाने वाले भारतीय मूल के गणितज्ञ कौन हैं?","o":["सी. आर. राव","हरीश-चंद्र","मंजुल भार्गव","एस. आर. श्रीनिवास वर्धन"],"a":3,"e":"नॉर्वे सरकार द्वारा 2003 से दिया जाने वाला एबेल पुरस्कार श्रीनिवास वर्धन को प्रायिकता सिद्धांत (बड़े विचलन) में योगदान के लिए मिला।"},
    {"q":"नोबेल पुरस्कार के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. नोबेल पुरस्कार पहली बार 1901 में दिए गए।<br>2. अर्थशास्त्र का नोबेल (स्वेरिजेस रिक्सबैंक पुरस्कार) भी 1901 से दिया जा रहा है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — डायनामाइट के आविष्कारक अल्फ्रेड नोबेल की वसीयत (1895) के अनुसार 1901 से। कथन 2 गलत — अर्थशास्त्र पुरस्कार 1968 में स्थापित हुआ और पहली बार 1969 में दिया गया।"},
    {"q":"नोबेल शांति पुरस्कार किस शहर में प्रदान किया जाता है?","o":["स्टॉकहोम","ओस्लो","जिनेवा","हेग"],"a":1,"e":"शांति पुरस्कार नॉर्वे की नोबेल समिति ओस्लो में देती है; अन्य सभी नोबेल स्टॉकहोम (स्वीडन) में दिए जाते हैं। समारोह 10 दिसंबर (नोबेल की पुण्यतिथि) को होता है।"},
    {"q":"सूची-I (नोबेल विजेता) को सूची-II (क्षेत्र व वर्ष) से सुमेलित कीजिए —<br>(A) हरगोविंद खुराना (B) सुब्रह्मण्यन चंद्रशेखर (C) वेंकटरमन रामकृष्णन (D) अभिजीत बनर्जी<br>1. रसायन 2009 2. अर्थशास्त्र 2019 3. चिकित्सा 1968 4. भौतिकी 1983","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"a":3,"e":"खुराना — आनुवंशिक कूट, चिकित्सा 1968 (A-3); चंद्रशेखर — \"चंद्रशेखर सीमा\", भौतिकी 1983 (B-4); वेंकी रामकृष्णन — राइबोसोम संरचना, रसायन 2009 (C-1); अभिजीत बनर्जी — निर्धनता उन्मूलन, अर्थशास्त्र 2019 (D-2)।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. मैरी क्यूरी दो अलग-अलग विज्ञान विषयों (भौतिकी 1903, रसायन 1911) में नोबेल जीतने वाली एकमात्र व्यक्ति हैं।<br>2. मलाला यूसुफ़ज़ई 17 वर्ष की आयु में सबसे कम आयु की नोबेल विजेता बनीं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — मैरी क्यूरी नोबेल पाने वाली पहली महिला भी थीं। कथन 2 सही — मलाला को 2014 में कैलाश सत्यार्थी के साथ शांति नोबेल मिला।"},
    {"q":"1964 में साहित्य का नोबेल पुरस्कार लेने से इनकार करने वाले लेखक कौन थे?","o":["ज्याँ-पॉल सार्त्र","अल्बेयर कामू","बोरिस पास्तरनाक","अर्नेस्ट हेमिंग्वे"],"a":0,"e":"फ़्रांसीसी दार्शनिक सार्त्र ने स्वेच्छा से नोबेल अस्वीकार किया। पास्तरनाक (1958) को सोवियत दबाव में पुरस्कार ठुकराना पड़ा; ले डुक थो ने 1973 का शांति नोबेल अस्वीकार किया।"},
    {"q":"पहला बुकर पुरस्कार (1969) किसे मिला?","o":["वी. एस. नायपॉल","आइरिस मर्डोक","सलमान रुश्दी","पी. एच. न्यूबी"],"a":3,"e":"पी. एच. न्यूबी को \"समथिंग टू आंसर फ़ॉर\" के लिए पहला बुकर मिला। नायपॉल (1971, \"इन अ फ़्री स्टेट\") भारतीय मूल के पहले बुकर विजेता थे।"},
    {"q":"पुलित्ज़र पुरस्कार के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. पुलित्ज़र पुरस्कार पाने वाले पहले भारतीय पत्रकार गोबिंद बिहारी लाल (1937) थे।<br>2. झुम्पा लाहिड़ी को 2000 में \"इंटरप्रेटर ऑफ़ मैलाडीज़\" के लिए कथा-साहित्य का पुलित्ज़र मिला।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — गोबिंद बिहारी लाल को विज्ञान पत्रकारिता के लिए 1937 में। कथन 2 सही — लाहिड़ी का कहानी-संग्रह; सिद्धार्थ मुखर्जी को 2011 में \"द एम्परर ऑफ़ ऑल मैलाडीज़\" के लिए पुलित्ज़र मिला।"},
    {"q":"सूची-I (रेमन मैग्सेसे विजेता) को सूची-II (वर्ष) से सुमेलित कीजिए —<br>(A) किरण बेदी (B) अरुणा रॉय (C) राजेंद्र सिंह (D) अरविंद केजरीवाल<br>1. 2006 2. 2001 3. 2000 4. 1994","o":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"a":0,"e":"किरण बेदी — 1994 (A-4); अरुणा रॉय (MKSS, सूचना का अधिकार) — 2000 (B-3); राजेंद्र सिंह (\"जलपुरुष\") — 2001 (C-2); केजरीवाल — 2006 (D-1)।"},
    {"q":"रेमन मैग्सेसे पुरस्कार किस देश के राष्ट्रपति की स्मृति में दिया जाता है?","o":["इंडोनेशिया","फ़िलीपींस","मलेशिया","थाईलैंड"],"a":1,"e":"1957 में विमान दुर्घटना में मारे गए फ़िलीपींस के राष्ट्रपति रेमन मैग्सेसे की स्मृति में स्थापित; इसे \"एशिया का नोबेल\" कहा जाता है। विनोबा भावे (1958) पहले भारतीय विजेता थे।"},
    {"q":"टेम्पलटन पुरस्कार (1973) की पहली विजेता कौन थीं?","o":["इंदिरा गांधी","एनी बेसेंट","सरोजिनी नायडू","मदर टेरेसा"],"a":3,"e":"आध्यात्मिक/धार्मिक क्षेत्र में योगदान हेतु जॉन टेम्पलटन द्वारा स्थापित यह पुरस्कार पहली बार मदर टेरेसा को मिला; 1979 में उन्हें शांति नोबेल मिला।"},
    {"q":"गांधी शांति पुरस्कार के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. यह महात्मा गांधी की 125वीं जयंती के अवसर पर 1995 में आरंभ किया गया।<br>2. इसके पहले विजेता तंज़ानिया के पूर्व राष्ट्रपति जूलियस न्येरेरे थे।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — भारत सरकार ने 1995 में आरंभ किया (राशि ₹1 करोड़)। कथन 2 सही — 1995 में जूलियस न्येरेरे; बाद में ISRO (2014) और गीता प्रेस, गोरखपुर (2021) को भी मिला।"},
    {"q":"गांधी शांति पुरस्कार 2014 किस भारतीय संस्था को प्रदान किया गया?","o":["भारतीय अंतरिक्ष अनुसंधान संगठन (ISRO)","रामकृष्ण मिशन","सुलभ इंटरनेशनल","भारतीय विद्या भवन"],"a":0,"e":"ISRO को 2014 का गांधी शांति पुरस्कार मिला। रामकृष्ण मिशन (1998), भारतीय विद्या भवन (2002) और सुलभ इंटरनेशनल (2016) को भी यह सम्मान मिल चुका है।"},
    {"q":"शांति स्वरूप भटनागर पुरस्कार किस क्षेत्र में दिया जाता है?","o":["साहित्य","विज्ञान एवं प्रौद्योगिकी","शास्त्रीय संगीत","समाज सेवा"],"a":1,"e":"CSIR द्वारा 1958 से 45 वर्ष से कम आयु के वैज्ञानिकों को दिया जाने वाला यह पुरस्कार CSIR के संस्थापक निदेशक शांति स्वरूप भटनागर के नाम पर है। 2023 से यह राष्ट्रीय विज्ञान पुरस्कार के अंतर्गत \"विज्ञान युवा–शांति स्वरूप भटनागर पुरस्कार\" के रूप में दिया जाता है।"},
    {"q":"पहला विश्व खाद्य पुरस्कार (1987) किसे मिला?","o":["नॉर्मन बोरलॉग","वर्गीज़ कुरियन","सी. सुब्रमण्यम","एम. एस. स्वामीनाथन"],"a":3,"e":"नॉर्मन बोरलॉग द्वारा स्थापित विश्व खाद्य पुरस्कार पहली बार भारत की हरित क्रांति के प्रणेता स्वामीनाथन को मिला। वर्गीज़ कुरियन (1989) व सी. सुब्रमण्यम (1996) को भी मिला।"},
    {"q":"विज्ञान को लोकप्रिय बनाने के लिए यूनेस्को का कलिंग पुरस्कार (1952) किसने स्थापित किया?","o":["बीजू पटनायक","होमी जहाँगीर भाभा","जवाहरलाल नेहरू","सी. वी. रमन"],"a":0,"e":"ओडिशा के उद्योगपति-राजनेता बीजू पटनायक ने कलिंग फ़ाउंडेशन ट्रस्ट के माध्यम से यह पुरस्कार यूनेस्को को सौंपा।"},
    {"q":"कालिदास सम्मान किस राज्य सरकार द्वारा दिया जाता है?","o":["उत्तर प्रदेश","मध्य प्रदेश","महाराष्ट्र","छत्तीसगढ़"],"a":1,"e":"मध्य प्रदेश सरकार 1980 से शास्त्रीय संगीत, नृत्य, रंगमंच व रूपंकर कलाओं के लिए कालिदास सम्मान देती है। तानसेन सम्मान भी म. प्र. का है।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (पुरस्कार — क्षेत्र) सही सुमेलित नहीं है?","o":["एबेल पुरस्कार — गणित","ग्रैमी पुरस्कार — संगीत","प्रित्ज़कर पुरस्कार — पत्रकारिता","टेम्पलटन पुरस्कार — आध्यात्मिक/धार्मिक योगदान"],"a":2,"e":"प्रित्ज़कर पुरस्कार वास्तुकला का है; पत्रकारिता का प्रमुख पुरस्कार पुलित्ज़र है। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (भारत रत्न — वर्ष) सही सुमेलित नहीं है?","o":["मदन मोहन मालवीय — 2015","एम. एस. सुब्बुलक्ष्मी — 1998","जयप्रकाश नारायण — 1999","भीमसेन जोशी — 1992"],"a":3,"e":"पंडित भीमसेन जोशी को 2008 में (2009 में प्रदत्त) भारत रत्न मिला। मालवीय व वाजपेयी को 2015 में मिला। शेष युग्म सही हैं।"},
    {"q":"अभिकथन (A): खिलाड़ियों को भारत रत्न 2011 से पहले नहीं दिया जा सकता था।<br>कारण (R): 2011 से पहले भारत रत्न केवल कला, साहित्य, विज्ञान और सार्वजनिक सेवा के क्षेत्रों तक सीमित था।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही और R उसकी सही व्याख्या है — 2011 में मानदंड बदलकर \"मानवीय प्रयास का कोई भी क्षेत्र\" किया गया, जिसके बाद 2014 में सचिन तेंदुलकर पहले खिलाड़ी विजेता बने।"},
    {"q":"राष्ट्रीय खेल प्रोत्साहन पुरस्कार किसे प्रदान किया जाता है?","o":["सर्वश्रेष्ठ विश्वविद्यालय को","खेलों के विकास में योगदान देने वाली संस्थाओं/कॉर्पोरेट को","युवा खिलाड़ियों को छात्रवृत्ति हेतु","सेवानिवृत्त प्रशिक्षकों को"],"a":1,"e":"2009 से दिया जाने वाला यह पुरस्कार खेल प्रोत्साहन व विकास में योगदान देने वाले संगठनों (सरकारी/निजी/कॉर्पोरेट) को दिया जाता है।"},
    {"q":"राष्ट्रीय खेल पुरस्कारों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. अर्जुन पुरस्कार में अर्जुन की कांस्य प्रतिमा दी जाती है।<br>2. द्रोणाचार्य पुरस्कार खिलाड़ियों को उनके चार वर्ष के उत्कृष्ट प्रदर्शन के लिए दिया जाता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — अर्जुन पुरस्कार (1961) में कांस्य प्रतिमा, प्रशस्ति-पत्र व राशि दी जाती है। कथन 2 गलत — द्रोणाचार्य पुरस्कार (1985) प्रशिक्षकों (कोच) को दिया जाता है; खिलाड़ियों को अर्जुन पुरस्कार मिलता है।"},
    {"q":"पद्म पुरस्कारों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. पद्म पुरस्कारों की घोषणा प्रतिवर्ष गणतंत्र दिवस की पूर्व संध्या पर की जाती है।<br>2. पद्म विभूषण, पद्म भूषण से उच्च श्रेणी का सम्मान है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — घोषणा 25 जनवरी को होती है और अलंकरण राष्ट्रपति भवन में बाद में होता है। कथन 2 सही — क्रम: भारत रत्न → पद्म विभूषण → पद्म भूषण → पद्म श्री। पद्म पुरस्कार 1954 में स्थापित हुए।"},
    {"q":"पद्म विभूषण से सम्मानित पहले खिलाड़ी (2007) कौन थे?","o":["सचिन तेंदुलकर","मिल्खा सिंह","प्रकाश पादुकोण","विश्वनाथन आनंद"],"a":3,"e":"शतरंज के विश्वनाथन आनंद को 2007 में पद्म विभूषण मिला; सचिन को 2008 में। मैरी कॉम (2020) पद्म विभूषण पाने वाली पहली महिला खिलाड़ी बनीं।"},
    {"q":"अभिकथन (A): कैलाश सत्यार्थी को 2014 का नोबेल शांति पुरस्कार मिला।<br>कारण (R): उन्होंने \"बचपन बचाओ आंदोलन\" के माध्यम से बाल श्रम और बाल दासता के विरुद्ध दशकों तक संघर्ष किया।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही, R सही और R ही पुरस्कार का कारण है — नोबेल समिति ने बच्चों के दमन के विरुद्ध और शिक्षा के अधिकार हेतु संघर्ष के लिए उन्हें मलाला यूसुफ़ज़ई के साथ सम्मानित किया।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. दिलीप कुमार को दादासाहेब फाल्के पुरस्कार और पाकिस्तान का सर्वोच्च नागरिक सम्मान \"निशान-ए-इम्तियाज़\" — दोनों मिले।<br>2. दादासाहेब फाल्के पुरस्कार पाने वाले पहले पुरुष पृथ्वीराज कपूर थे।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — दिलीप कुमार को फाल्के (1994) और निशान-ए-इम्तियाज़ (1998) मिला। कथन 2 गलत — पहले पुरुष विजेता बी. एन. सरकार (1970) थे; पृथ्वीराज कपूर को 1971 में मरणोपरांत मिला।"},
    {"q":"निम्नलिखित भारतीय नोबेल विजेताओं को पुरस्कार-वर्ष के कालक्रम में व्यवस्थित कीजिए —<br>1. वेंकटरमन रामकृष्णन<br>2. सुब्रह्मण्यन चंद्रशेखर<br>3. कैलाश सत्यार्थी<br>4. हरगोविंद खुराना","o":["2, 4, 1, 3","4, 2, 1, 3","4, 1, 2, 3","4, 2, 3, 1"],"a":1,"e":"खुराना 1968 → चंद्रशेखर 1983 → रामकृष्णन 2009 → सत्यार्थी 2014। अतः 4, 2, 1, 3।"},
    {"q":"2023 में ऑस्कर जीतने वाला भारतीय वृत्तचित्र \"द एलिफ़ेंट व्हिस्परर्स\" किस राज्य के मुदुमलाई टाइगर रिज़र्व पर आधारित है?","o":["कर्नाटक","केरल","तमिलनाडु","असम"],"a":2,"e":"कार्तिकी गोंज़ाल्विस निर्देशित यह लघु वृत्तचित्र तमिलनाडु के मुदुमलाई में अनाथ हाथी \"रघु\" की देखभाल करने वाले बोमन–बेल्ली दंपती पर है; निर्माता गुनीत मोंगा।"},
    {"q":"सूची-I (क्रिकेट स्टेडियम) को सूची-II (शहर) से सुमेलित कीजिए —<br>(A) राजीव गांधी अंतरराष्ट्रीय (उप्पल) (B) इकाना (C) बरसापारा (D) HPCA<br>1. लखनऊ 2. धर्मशाला 3. गुवाहाटी 4. हैदराबाद","o":["A-1, B-4, C-3, D-2","A-4, B-1, C-2, D-3","A-4, B-3, C-1, D-2","A-4, B-1, C-3, D-2"],"a":3,"e":"उप्पल — हैदराबाद (A-4); भारत रत्न श्री अटल बिहारी वाजपेयी इकाना — लखनऊ (B-1); बरसापारा — गुवाहाटी (C-3); HPCA — धर्मशाला (D-2)।"},
    {"q":"सूची-I (विदेशी क्रिकेट मैदान) को सूची-II (शहर) से सुमेलित कीजिए —<br>(A) हेडिंग्ले (B) ट्रेंट ब्रिज (C) न्यूलैंड्स (D) सबीना पार्क<br>1. नॉटिंघम 2. लीड्स 3. किंग्स्टन 4. केप टाउन","o":["A-1, B-2, C-4, D-3","A-2, B-1, C-4, D-3","A-2, B-1, C-3, D-4","A-4, B-1, C-2, D-3"],"a":1,"e":"हेडिंग्ले — लीड्स (A-2); ट्रेंट ब्रिज — नॉटिंघम (B-1); न्यूलैंड्स — केप टाउन (C-4); सबीना पार्क — किंग्स्टन, जमैका (D-3)।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (स्टेडियम — शहर) सही सुमेलित नहीं है?","o":["कलिंग स्टेडियम — भुवनेश्वर","गद्दाफ़ी स्टेडियम — लाहौर","ऐनफ़ील्ड — मैनचेस्टर","शेर-ए-बांग्ला स्टेडियम — मीरपुर (ढाका)"],"a":2,"e":"ऐनफ़ील्ड लिवरपूल फ़ुटबॉल क्लब का मैदान है (लिवरपूल शहर); मैनचेस्टर में ओल्ड ट्रैफ़र्ड है। शेष युग्म सही हैं।"},
    {"q":"सूची-I (भारतीय स्टेडियम) को सूची-II (शहर) से सुमेलित कीजिए —<br>(A) ब्रेबोर्न (CCI) (B) VCA जामठा (C) ग्रीनफ़ील्ड अंतरराष्ट्रीय (D) JSCA अंतरराष्ट्रीय<br>1. तिरुवनंतपुरम 2. नागपुर 3. मुंबई 4. राँची","o":["A-2, B-3, C-1, D-4","A-3, B-1, C-2, D-4","A-3, B-2, C-4, D-1","A-3, B-2, C-1, D-4"],"a":3,"e":"ब्रेबोर्न — मुंबई (A-3); VCA जामठा — नागपुर (B-2); ग्रीनफ़ील्ड — तिरुवनंतपुरम (C-1); JSCA — राँची (D-4)।"},
    {"q":"सूची-I (अंतरराष्ट्रीय खेल संस्था) को सूची-II (मुख्यालय) से सुमेलित कीजिए —<br>(A) FIBA (बास्केटबॉल) (B) UCI (साइक्लिंग) (C) वर्ल्ड रग्बी (D) FIA (मोटर स्पोर्ट)<br>1. डबलिन 2. एगल (स्विट्ज़रलैंड) 3. मीस (स्विट्ज़रलैंड) 4. पेरिस","o":["A-2, B-3, C-1, D-4","A-3, B-2, C-1, D-4","A-3, B-1, C-2, D-4","A-3, B-2, C-4, D-1"],"a":1,"e":"FIBA — मीस (A-3); UCI — एगल (B-2); वर्ल्ड रग्बी — डबलिन, आयरलैंड (C-1); FIA — पेरिस (D-4)। अधिकांश ओलंपिक महासंघ स्विट्ज़रलैंड में हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. विश्व शतरंज महासंघ (FIDE) की स्थापना 1924 में पेरिस में हुई थी, पर अब इसका मुख्यालय लुसाने में है।<br>2. अंतरराष्ट्रीय टेबल टेनिस महासंघ (ITTF) और वर्ल्ड आर्चरी — दोनों का मुख्यालय लुसाने में है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — FIDE (फ़्रांसीसी संक्षिप्ताक्षर) 20 जुलाई 1924 को पेरिस में बना; 20 जुलाई विश्व शतरंज दिवस है। कथन 2 सही — लुसाने को \"ओलंपिक राजधानी\" कहा जाता है।"},
    {"q":"सूची-I (ट्रॉफी) को सूची-II (खेल) से सुमेलित कीजिए —<br>(A) बोरदोलोई ट्रॉफी (B) एज़रा कप (C) इब्राहिम रहीमतुल्ला ट्रॉफी (D) जयलक्ष्मी कप<br>1. फ़ुटबॉल 2. पोलो 3. बैडमिंटन 4. टेबल टेनिस","o":["A-2, B-1, C-3, D-4","A-1, B-3, C-2, D-4","A-1, B-2, C-4, D-3","A-1, B-2, C-3, D-4"],"a":3,"e":"बोरदोलोई ट्रॉफी (गुवाहाटी) — फ़ुटबॉल (A-1); एज़रा कप — पोलो (B-2); इब्राहिम रहीमतुल्ला ट्रॉफी — बैडमिंटन (C-3); जयलक्ष्मी कप — टेबल टेनिस (D-4)।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (ट्रॉफी — खेल/लीग) सही सुमेलित नहीं है?","o":["लैरी ओ'ब्रायन ट्रॉफी — आइस हॉकी (NHL)","ब्लेडिस्लो कप — रग्बी","विंस लोम्बार्डी ट्रॉफी — अमेरिकी फ़ुटबॉल (सुपर बाउल)","कर्टिस कप — महिला शौकिया गोल्फ़"],"a":0,"e":"लैरी ओ'ब्रायन ट्रॉफी NBA बास्केटबॉल चैंपियन को मिलती है; आइस हॉकी (NHL) की ट्रॉफी स्टेनली कप है। शेष युग्म सही हैं।"},
    {"q":"सूची-I (पुरस्कार/प्रतीक) को सूची-II (प्रतियोगिता) से सुमेलित कीजिए —<br>(A) क्लैरेट जग (B) येलो जर्सी (C) हेनरी डेलौने ट्रॉफी (D) सोलहेम कप<br>1. महिला पेशेवर गोल्फ़ (अमेरिका बनाम यूरोप) 2. द ओपन चैंपियनशिप (गोल्फ़) 3. टूर डी फ़्रांस साइक्लिंग 4. यूरोपीय फ़ुटबॉल चैंपियनशिप","o":["A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-1, D-4"],"a":1,"e":"क्लैरेट जग — द ओपन गोल्फ़ (A-2); येलो जर्सी (मायो जौन) — टूर डी फ़्रांस का अग्रणी (B-3); हेनरी डेलौने — यूरो (C-4); सोलहेम कप — महिला पेशेवर गोल्फ़ (D-1)।"},
    {"q":"निम्नलिखित ग्रीष्मकालीन ओलंपिक मेज़बान शहरों को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. रोम<br>2. स्टॉकहोम<br>3. मेलबर्न<br>4. एम्सटर्डम","o":["4, 2, 3, 1","2, 3, 4, 1","2, 4, 3, 1","2, 4, 1, 3"],"a":2,"e":"स्टॉकहोम 1912 → एम्सटर्डम 1928 → मेलबर्न 1956 → रोम 1960। अतः 2, 4, 3, 1।"},
    {"q":"ग्रीष्मकालीन ओलंपिक की मेज़बानी के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. लंदन ने तीन बार — 1908, 1948 और 2012 में — मेज़बानी की।<br>2. पेरिस ने तीन बार — 1900, 1924 और 2024 में — मेज़बानी की।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — लंदन तीन बार मेज़बानी करने वाला पहला शहर बना (2012)। कथन 2 सही — पेरिस ने 2024 में ठीक 100 वर्ष बाद पुनः मेज़बानी की। लॉस एंजिलिस 2028 में तीसरी बार मेज़बानी करेगा।"},
    {"q":"अभिकथन (A): संयुक्त राज्य अमेरिका सहित अनेक देशों ने 1980 के मॉस्को ओलंपिक का बहिष्कार किया।<br>कारण (R): दिसंबर 1979 में सोवियत संघ ने अफ़ग़ानिस्तान पर सैन्य आक्रमण किया था।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A और R सही, R ही बहिष्कार का कारण है। जवाब में सोवियत संघ और उसके सहयोगियों ने 1984 लॉस एंजिलिस ओलंपिक का बहिष्कार किया। इसी कमज़ोर प्रतिस्पर्धा वाले 1980 ओलंपिक में भारत ने अंतिम हॉकी स्वर्ण जीता।"},
    {"q":"किस ओलंपिक के दौरान \"ब्लैक सितंबर\" आतंकी गुट ने इज़राइली खिलाड़ियों की हत्या कर दी थी?","o":["1968 मेक्सिको सिटी","1976 मॉन्ट्रियल","1936 बर्लिन","1972 म्यूनिख"],"a":3,"e":"सितंबर 1972 में म्यूनिख ओलंपिक खेल गाँव में 11 इज़राइली खिलाड़ियों/अधिकारियों की हत्या हुई — ओलंपिक इतिहास की सबसे दुखद घटना।"},
    {"q":"1936 बर्लिन ओलंपिक में 4 स्वर्ण पदक जीतकर हिटलर के \"नस्लीय श्रेष्ठता\" के दावे को चुनौती देने वाले अमेरिकी एथलीट कौन थे?","o":["कार्ल लुईस","जेसी ओवेन्स","जिम थॉर्प","पावो नुर्मी"],"a":1,"e":"जेसी ओवेन्स ने 100 मी, 200 मी, लंबी कूद और 4×100 मी रिले में स्वर्ण जीते। कार्ल लुईस ने 1984 में यही चार स्वर्ण जीतकर उनकी बराबरी की।"},
    {"q":"ओलंपिक खेलों में महिलाओं ने पहली बार किस संस्करण में भाग लिया?","o":["1896 एथेंस","1908 लंदन","1928 एम्सटर्डम","1900 पेरिस"],"a":3,"e":"1900 पेरिस ओलंपिक में पहली बार महिलाओं ने भाग लिया; ब्रिटेन की टेनिस खिलाड़ी शार्लोट कूपर पहली महिला ओलंपिक चैंपियन बनीं।"},
    {"q":"आधुनिक ओलंपिक इतिहास के पहले चैंपियन (1896, ट्रिपल जंप) कौन थे?","o":["जेम्स कोनोली","स्पिरिडॉन लुइस","अल्फ्रेड हायोस","कार्ल शुहमान"],"a":0,"e":"अमेरिका के जेम्स कोनोली ने 6 अप्रैल 1896 को ट्रिपल जंप जीतकर पहला आधुनिक ओलंपिक ख़िताब पाया। यूनान के स्पिरिडॉन लुइस ने पहली ओलंपिक मैराथन जीती।"},
    {"q":"अंतरराष्ट्रीय ओलंपिक समिति (IOC) के पहले अध्यक्ष कौन थे?","o":["पियरे डी कूबर्टिन","डेमेट्रियस विकेलास","एवरी ब्रंडेज","हेनरी डी बैले-लातूर"],"a":1,"e":"यूनान के डेमेट्रियस विकेलास (1894–96) पहले IOC अध्यक्ष थे, क्योंकि पहले खेल एथेंस में होने थे; कूबर्टिन दूसरे अध्यक्ष (1896–1925) बने।"},
    {"q":"IOC की सदस्य बनने वाली पहली भारतीय महिला (2016) कौन हैं?","o":["पी. टी. उषा","अंजू बॉबी जॉर्ज","नीता अंबानी","कर्णम मल्लेश्वरी"],"a":2,"e":"नीता अंबानी अगस्त 2016 (रियो) में IOC सदस्य चुनी गईं। पी. टी. उषा दिसंबर 2022 में भारतीय ओलंपिक संघ की पहली महिला अध्यक्ष बनीं।"},
    {"q":"एशियाई खेलों की मेज़बानी के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. भारत ने एशियाई खेलों की मेज़बानी दो बार — 1951 और 1982 में — की है।<br>2. कबड्डी को 1990 बीजिंग एशियाई खेलों में शामिल किया गया।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — दोनों बार नई दिल्ली में। कथन 2 सही — 1990 बीजिंग से कबड्डी शामिल है; महिला कबड्डी 2010 ग्वांगझू से।"},
    {"q":"निम्नलिखित राष्ट्रमंडल खेल मेज़बान शहरों को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. कुआलालंपुर<br>2. एडिनबर्ग (पहली बार)<br>3. किंग्स्टन<br>4. ब्रिस्बेन","o":["2, 3, 4, 1","3, 4, 2, 1","3, 2, 1, 4","3, 2, 4, 1"],"a":3,"e":"किंग्स्टन 1966 → एडिनबर्ग 1970 → ब्रिस्बेन 1982 → कुआलालंपुर 1998। अतः 3, 2, 4, 1।"},
    {"q":"राष्ट्रमंडल खेलों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. भारत ने राष्ट्रमंडल खेलों में पहली बार 1930 हैमिल्टन खेलों में भाग लिया।<br>2. मिल्खा सिंह ने 1958 कार्डिफ़ राष्ट्रमंडल खेलों में स्वर्ण पदक जीता।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — भारत ने पहली बार 1934 लंदन खेलों में भाग लिया (पहलवान राशिद अनवर को कांस्य)। कथन 2 सही — 440 गज़ दौड़ में स्वर्ण।"},
    {"q":"सूची-I (ODI विश्व कप वर्ष) को सूची-II (विजेता कप्तान) से सुमेलित कीजिए —<br>(A) 1987 (B) 1992 (C) 1996 (D) 2019<br>1. अर्जुन रणतुंगा 2. एलन बॉर्डर 3. इमरान ख़ान 4. इयोन मॉर्गन","o":["A-2, B-3, C-1, D-4","A-3, B-2, C-1, D-4","A-2, B-1, C-3, D-4","A-2, B-3, C-4, D-1"],"a":0,"e":"1987 ऑस्ट्रेलिया — एलन बॉर्डर (A-2); 1992 पाकिस्तान — इमरान ख़ान (B-3); 1996 श्रीलंका — रणतुंगा (C-1); 2019 इंग्लैंड — मॉर्गन (D-4)।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (पुरुष T20 विश्व कप — विजेता) सही सुमेलित नहीं है?","o":["2010 — इंग्लैंड","2012 — वेस्ट इंडीज़","2014 — श्रीलंका","2009 — ऑस्ट्रेलिया"],"a":3,"e":"2009 का T20 विश्व कप (लॉर्ड्स) पाकिस्तान ने जीता; ऑस्ट्रेलिया ने पहला T20 ख़िताब 2021 (दुबई) में जीता। शेष युग्म सही हैं।"},
    {"q":"क्रिकेट विश्व कप के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. 1996 विश्व कप का फ़ाइनल लाहौर (गद्दाफ़ी स्टेडियम) में खेला गया।<br>2. 1987 विश्व कप का फ़ाइनल मुंबई के वानखेड़े स्टेडियम में खेला गया।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — 1996 में श्रीलंका ने ऑस्ट्रेलिया को लाहौर में हराया। कथन 2 गलत — 1987 (इंग्लैंड से बाहर पहला विश्व कप) का फ़ाइनल कोलकाता के ईडन गार्डन्स में हुआ।"},
    {"q":"अभिकथन (A): 2019 क्रिकेट विश्व कप फ़ाइनल में इंग्लैंड को \"अधिक बाउंड्री\" के आधार पर विजेता घोषित किया गया।<br>कारण (R): फ़ाइनल मैच और उसके बाद का सुपर ओवर — दोनों बराबरी (टाई) पर समाप्त हुए थे।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A और R सही, R ही कारण है — लॉर्ड्स में न्यूज़ीलैंड के विरुद्ध मैच व सुपर ओवर टाई होने पर बाउंड्री-गणना से इंग्लैंड जीता; बाद में ICC ने यह नियम हटा दिया।"},
    {"q":"ICC चैंपियंस ट्रॉफी के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. इसका पहला संस्करण 1998 में \"ICC नॉकआउट\" नाम से ढाका में हुआ, जिसे दक्षिण अफ़्रीका ने जीता।<br>2. 2000 नैरोबी फ़ाइनल में भारत ने न्यूज़ीलैंड को हराकर ख़िताब जीता।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — 1998 ढाका, विजेता दक्षिण अफ़्रीका। कथन 2 गलत — 2000 में न्यूज़ीलैंड ने भारत को हराया। भारत 2002 (श्रीलंका के साथ संयुक्त), 2013 और 2025 में विजेता बना।"},
    {"q":"भारत के निम्नलिखित ICC ख़िताबों को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. चैंपियंस ट्रॉफी — एजबेस्टन<br>2. T20 विश्व कप — जोहान्सबर्ग<br>3. चैंपियंस ट्रॉफी — कोलंबो (संयुक्त)<br>4. ODI विश्व कप — वानखेड़े","o":["2, 3, 4, 1","3, 2, 4, 1","3, 4, 2, 1","3, 2, 1, 4"],"a":1,"e":"कोलंबो 2002 (संयुक्त) → जोहान्सबर्ग 2007 → वानखेड़े 2011 → एजबेस्टन 2013। अतः 3, 2, 4, 1।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (फ़ीफ़ा विश्व कप — विजेता) सही सुमेलित नहीं है?","o":["1966 — इंग्लैंड","1998 — फ़्रांस","2014 — अर्जेंटीना","2010 — स्पेन"],"a":2,"e":"2014 (ब्राज़ील) का विश्व कप जर्मनी ने फ़ाइनल में अर्जेंटीना को 1-0 से हराकर जीता। शेष युग्म सही हैं; 1966 और 1998 में मेज़बान ही विजेता बने।"},
    {"q":"सूची-I (फ़ीफ़ा विश्व कप वर्ष) को सूची-II (विजेता) से सुमेलित कीजिए —<br>(A) 1954 (B) 1978 (C) 1982 (D) 1994<br>1. अर्जेंटीना 2. इटली 3. ब्राज़ील 4. पश्चिम जर्मनी","o":["A-1, B-4, C-2, D-3","A-4, B-2, C-1, D-3","A-4, B-1, C-3, D-2","A-4, B-1, C-2, D-3"],"a":3,"e":"1954 — पश्चिम जर्मनी (A-4); 1978 — अर्जेंटीना, मेज़बान (B-1); 1982 — इटली (C-2); 1994 — ब्राज़ील, अमेरिका में (D-3)।"},
    {"q":"तीन फ़ीफ़ा विश्व कप (1958, 1962, 1970) जीतने वाले एकमात्र खिलाड़ी कौन हैं?","o":["डिएगो माराडोना","पेले","फ़्रांत्ज़ बेकनबावर","रोनाल्डो (ब्राज़ील)"],"a":1,"e":"ब्राज़ील के पेले तीन विश्व कप जीतने वाले एकमात्र खिलाड़ी हैं। विश्व कप में सर्वाधिक गोल का रिकॉर्ड अब किलियन एम्बाप्पे (फ़्रांस, 22 गोल — 2026 विश्व कप में) के नाम है; इससे पहले यह मिरोस्लाव क्लोज़ (जर्मनी, 16) के नाम था।"},
    {"q":"दो फ़ीफ़ा विश्व कप (1970 और 1986) की मेज़बानी करने वाला पहला देश कौन-सा है?","o":["इटली","फ़्रांस","मेक्सिको","ब्राज़ील"],"a":2,"e":"मेक्सिको ने 1970 और 1986 में मेज़बानी की; 1986 में माराडोना की अर्जेंटीना विजेता बनी। 2026 में मेक्सिको तीसरी बार (सह-मेज़बान के रूप में) मेज़बान बना।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (पुरुष हॉकी विश्व कप — विजेता) सही सुमेलित नहीं है?","o":["1975 — भारत","1986 — ऑस्ट्रेलिया","2018 — बेल्जियम","1973 — पाकिस्तान"],"a":3,"e":"1973 (एम्सटेलवीन) का विश्व कप नीदरलैंड्स ने जीता, भारत उपविजेता रहा। शेष युग्म सही हैं।"},
    {"q":"पुरुष हॉकी विश्व कप की भारत में मेज़बानी के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. भारत ने 1982 (बॉम्बे) और 2010 (नई दिल्ली) में मेज़बानी की।<br>2. 2018 और 2023 के संस्करण ओडिशा में आयोजित हुए।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 1982 में पाकिस्तान और 2010 में ऑस्ट्रेलिया विजेता। कथन 2 सही — 2018 भुवनेश्वर (बेल्जियम विजेता) और 2023 भुवनेश्वर–राउरकेला (जर्मनी विजेता)।"},
    {"q":"सूची-I (टेनिस ट्रॉफी) को सूची-II (ग्रैंड स्लैम) से सुमेलित कीजिए —<br>(A) नॉर्मन ब्रूक्स चैलेंज कप (B) कूप दे मूसक्वेतेयर (C) वीनस रोज़वाटर डिश (D) डैफ़्ने अखर्स्ट मेमोरियल कप<br>1. ऑस्ट्रेलियन ओपन पुरुष एकल 2. फ़्रेंच ओपन पुरुष एकल 3. विंबलडन महिला एकल 4. ऑस्ट्रेलियन ओपन महिला एकल","o":["A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-1, B-3, C-2, D-4","A-1, B-2, C-4, D-3"],"a":1,"e":"नॉर्मन ब्रूक्स — ऑस्ट्रेलियन ओपन पुरुष (A-1); कूप दे मूसक्वेतेयर — फ़्रेंच ओपन पुरुष (B-2); वीनस रोज़वाटर डिश — विंबलडन महिला (C-3); डैफ़्ने अखर्स्ट — ऑस्ट्रेलियन ओपन महिला (D-4)।"},
    {"q":"भारतीय टेनिस खिलाड़ियों के ग्रैंड स्लैम के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. लिएंडर पेस ने कुल 18 ग्रैंड स्लैम (8 पुरुष युगल + 10 मिश्रित युगल) जीते।<br>2. सानिया मिर्ज़ा ने कुल 6 ग्रैंड स्लैम (3 महिला युगल + 3 मिश्रित युगल) जीते।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — पेस भारत के सर्वाधिक ग्रैंड स्लैम विजेता हैं। कथन 2 सही — सानिया का पहला ग्रैंड स्लैम 2009 ऑस्ट्रेलियन ओपन मिश्रित (भूपति के साथ) था।"},
    {"q":"रोहन बोपन्ना ने अपना पहला ग्रैंड स्लैम ख़िताब (2017) किस प्रतियोगिता में जीता?","o":["विंबलडन पुरुष युगल","यूएस ओपन मिश्रित युगल","ऑस्ट्रेलियन ओपन पुरुष युगल","फ़्रेंच ओपन मिश्रित युगल"],"a":3,"e":"बोपन्ना ने कनाडा की गैब्रिएला डाब्रोव्स्की के साथ 2017 फ़्रेंच ओपन मिश्रित युगल जीता — ग्रैंड स्लैम जीतने वाले चौथे भारतीय।"},
    {"q":"सूची-I (विश्वनाथन आनंद का विश्व चैंपियनशिप मैच) को सूची-II (प्रतिद्वंद्वी) से सुमेलित कीजिए —<br>(A) 2008 बॉन (B) 2010 सोफ़िया (C) 2012 मॉस्को (D) 2013 चेन्नई<br>1. वेसेलिन टोपालोव 2. बोरिस गेलफ़ंड 3. मैग्नस कार्लसन 4. व्लादिमीर क्रैमनिक","o":["A-4, B-1, C-2, D-3","A-1, B-4, C-2, D-3","A-4, B-2, C-1, D-3","A-4, B-1, C-3, D-2"],"a":0,"e":"2008 बॉन — क्रैमनिक को हराया (A-4); 2010 सोफ़िया — टोपालोव को (B-1); 2012 मॉस्को — गेलफ़ंड को (C-2); 2013 चेन्नई — कार्लसन से हारे (D-3)।"},
    {"q":"भारत के ग्रैंडमास्टरों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. दिव्येंदु बरुआ (1991) भारत के दूसरे ग्रैंडमास्टर बने।<br>2. प्रवीण थिप्से (1997) भारत के तीसरे ग्रैंडमास्टर बने।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — आनंद (1988) के बाद बंगाल के दिव्येंदु बरुआ। कथन 2 सही — महाराष्ट्र के प्रवीण थिप्से तीसरे। महिलाओं में कोनेरू हम्पी (2002) पहली GM बनीं।"},
    {"q":"विश्व बैडमिंटन चैंपियनशिप में भारत का पहला पदक (1983, कांस्य) किसने जीता?","o":["सैयद मोदी","प्रकाश पादुकोण","पुलेला गोपीचंद","नंदू नाटेकर"],"a":1,"e":"प्रकाश पादुकोण ने 1983 कोपेनहेगन विश्व चैंपियनशिप में कांस्य जीता। तीन वर्ष पहले (1980) वे ऑल इंग्लैंड जीतने वाले पहले भारतीय बने थे।"},
    {"q":"पी. वी. सिंधु के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. उन्होंने विश्व बैडमिंटन चैंपियनशिप में कुल 5 पदक जीते हैं।<br>2. रियो 2016 ओलंपिक फ़ाइनल में उन्हें स्पेन की कैरोलिना मारिन ने हराया।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 2013, 2014 कांस्य; 2017, 2018 रजत; 2019 स्वर्ण (बासेल)। कथन 2 सही — रियो में रजत; टोक्यो 2020 में कांस्य जीतकर दो ओलंपिक व्यक्तिगत पदक जीतने वाली पहली भारतीय महिला बनीं।"},
    {"q":"BWF विश्व रैंकिंग में पुरुष एकल में नंबर 1 (अप्रैल 2018) बनने वाले पहले भारतीय कौन हैं?","o":["लक्ष्य सेन","एच. एस. प्रणय","पारुपल्ली कश्यप","किदांबी श्रीकांत"],"a":3,"e":"किदांबी श्रीकांत अप्रैल 2018 में BWF रैंकिंग में पुरुष एकल विश्व नंबर 1 बने; 2021 विश्व चैंपियनशिप में उन्होंने रजत जीता। (प्रकाश पादुकोण 1980 में पुरानी IBF रैंकिंग में विश्व नंबर 1 रहे थे।)"},
    {"q":"भारतीय महिला कुश्ती के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. गीता फोगाट राष्ट्रमंडल खेलों (2010) में स्वर्ण जीतने वाली पहली भारतीय महिला पहलवान हैं।<br>2. साक्षी मलिक एशियाई खेलों में कुश्ती का स्वर्ण जीतने वाली पहली भारतीय महिला हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — गीता ने 2010 दिल्ली में 55 किग्रा स्वर्ण जीता। कथन 2 गलत — यह उपलब्धि विनेश फोगाट (2018 जकार्ता, 50 किग्रा) की है; साक्षी ने रियो 2016 में ओलंपिक कांस्य जीता।"},
    {"q":"विश्व कुश्ती चैंपियनशिप में स्वर्ण जीतने वाले पहले भारतीय (2010, मॉस्को) कौन हैं?","o":["योगेश्वर दत्त","सुशील कुमार","बजरंग पूनिया","नरसिंह यादव"],"a":1,"e":"सुशील कुमार 2010 में 66 किग्रा में विश्व चैंपियन बने; वे दो व्यक्तिगत ओलंपिक पदक (2008, 2012) जीतने वाले पहले भारतीय भी हैं।"},
    {"q":"विश्व कुश्ती चैंपियनशिप में चार पदक जीतने वाले एकमात्र भारतीय पहलवान कौन हैं?","o":["सुशील कुमार","रवि दहिया","दीपक पूनिया","बजरंग पूनिया"],"a":3,"e":"बजरंग पूनिया ने 2013, 2018, 2019 और 2022 में विश्व चैंपियनशिप पदक जीते; टोक्यो 2020 में 65 किग्रा कांस्य जीता।"},
    {"q":"सूची-I (निशानेबाज़) को सूची-II (उपलब्धि) से सुमेलित कीजिए —<br>(A) जसपाल राणा (B) हिना सिद्धू (C) रुद्रांक्ष पाटिल (D) विजय कुमार<br>1. 2022 विश्व चैंपियन (10 मी एयर राइफ़ल) 2. विश्व नंबर 1 बनने वाली पहली भारतीय पिस्टल निशानेबाज़ 3. 1994 हिरोशिमा एशियाई खेल स्वर्ण 4. लंदन 2012 ओलंपिक रजत","o":["A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-3, B-1, C-2, D-4","A-3, B-2, C-4, D-1"],"a":0,"e":"जसपाल राणा — 1994 एशियाई खेल स्वर्ण (A-3); हिना सिद्धू — विश्व नंबर 1 पिस्टल (B-2); रुद्रांक्ष — 2022 काहिरा विश्व चैंपियन (C-1); विजय कुमार — 2012 रजत, 25 मी रैपिड फ़ायर (D-4)।"},
    {"q":"नीरज चोपड़ा के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. वे डायमंड लीग का ख़िताब (2022, ज़्यूरिख) जीतने वाले पहले भारतीय हैं।<br>2. उन्होंने 2022 यूजीन विश्व एथलेटिक्स चैंपियनशिप में स्वर्ण पदक जीता।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — 2022 में डायमंड लीग फ़ाइनल जीता। कथन 2 गलत — 2022 यूजीन में उन्हें रजत मिला; विश्व चैंपियनशिप स्वर्ण 2023 बुडापेस्ट में जीता।"},
    {"q":"सूची-I (मुक्केबाज़) को सूची-II (उपलब्धि) से सुमेलित कीजिए —<br>(A) हवा सिंह (B) डिंको सिंह (C) अमित पंघाल (D) विजेंदर सिंह<br>1. बीजिंग 2008 ओलंपिक कांस्य 2. 1998 बैंकॉक एशियाई खेल स्वर्ण 3. 1966 व 1970 एशियाई खेल हैवीवेट स्वर्ण 4. 2019 विश्व चैंपियनशिप रजत","o":["A-2, B-3, C-4, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-1, D-4"],"a":1,"e":"हवा सिंह — 1966, 1970 स्वर्ण (A-3); डिंको सिंह (मणिपुर) — 1998 स्वर्ण (B-2); अमित पंघाल — 2019 रजत, विश्व चैंपियनशिप फ़ाइनल में पहुँचने वाले पहले भारतीय पुरुष (C-4); विजेंदर — 2008 कांस्य (D-1)।"},
    {"q":"सूची-I (पैरा खिलाड़ी) को सूची-II (पैरालंपिक उपलब्धि) से सुमेलित कीजिए —<br>(A) मुरलीकांत पेटकर (B) दीपा मलिक (C) भाविना पटेल (D) प्रमोद भगत<br>1. 1972 हाइडेलबर्ग तैराकी स्वर्ण 2. टोक्यो 2020 टेबल टेनिस रजत 3. टोक्यो 2020 बैडमिंटन SL3 स्वर्ण 4. रियो 2016 गोला फेंक रजत","o":["A-4, B-1, C-2, D-3","A-1, B-2, C-4, D-3","A-1, B-4, C-3, D-2","A-1, B-4, C-2, D-3"],"a":3,"e":"पेटकर — 1972 तैराकी स्वर्ण (A-1); दीपा मलिक — 2016 रजत, पहली भारतीय महिला पैरालंपिक पदक विजेता (B-4); भाविना — 2020 टेबल टेनिस रजत (C-2); प्रमोद भगत — 2020 बैडमिंटन स्वर्ण (D-3)।"},
    {"q":"पहले द्रोणाचार्य पुरस्कार (1985) विजेताओं में शामिल ओ. एम. नांबियार किस प्रसिद्ध एथलीट के कोच थे?","o":["मिल्खा सिंह","पी. टी. उषा","शाइनी विल्सन","अंजू बॉबी जॉर्ज"],"a":1,"e":"ओ. एम. नांबियार पी. टी. उषा के कोच थे। 1985 में उनके साथ भालचंद्र भागवत (कुश्ती) और ओम प्रकाश भारद्वाज (मुक्केबाज़ी) को पहला द्रोणाचार्य पुरस्कार मिला।"},
    {"q":"खेल रत्न पाने वाले दूसरे खिलाड़ी (1992-93) कौन थे?","o":["सचिन तेंदुलकर","लिएंडर पेस","गीत सेठी","कर्णम मल्लेश्वरी"],"a":2,"e":"पहला खेल रत्न विश्वनाथन आनंद (1991-92) और दूसरा बिलियर्ड्स के गीत सेठी (1992-93) को मिला; सचिन (1997-98) पहले क्रिकेटर विजेता थे।"},
    {"q":"खेल रत्न (2019) पाने वाली पहली महिला पैरा-एथलीट कौन हैं?","o":["अवनि लेखरा","भाविना पटेल","मानसी जोशी","दीपा मलिक"],"a":3,"e":"दीपा मलिक को 2019 में बजरंग पूनिया के साथ खेल रत्न मिला। देवेंद्र झाझड़िया (2017) खेल रत्न पाने वाले पहले पैरा-एथलीट थे।"},
    {"q":"खेल पुरस्कारों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. आजीवन योगदान हेतु \"ध्यानचंद पुरस्कार\" 2002 में आरंभ हुआ था।<br>2. 2023 से \"ध्यानचंद पुरस्कार\" को \"अर्जुन पुरस्कार (आजीवन)\" के नाम से दिया जाता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 2002 में खेल-जीवन के बाद भी योगदान देने वालों के लिए आरंभ। कथन 2 सही — 2023 में नाम बदलकर अर्जुन पुरस्कार (आजीवन) किया गया, क्योंकि खेल रत्न का नाम पहले ही (2021) ध्यानचंद पर रखा जा चुका था।"},
    {"q":"राज्यसभा में मनोनीत होने वाले पहले खिलाड़ी (2003) कौन थे?","o":["दारा सिंह","सचिन तेंदुलकर","मैरी कॉम","पी. टी. उषा"],"a":0,"e":"\"रुस्तम-ए-हिंद\" पहलवान व अभिनेता दारा सिंह 2003 में मनोनीत हुए; सचिन (2012), मैरी कॉम (2016) और पी. टी. उषा (2022) भी मनोनीत हुईं।"},
    {"q":"स्नूकर खेल का आविष्कार 1875 में भारत के किस नगर में हुआ माना जाता है?","o":["ऊटी","जबलपुर","शिमला","मेरठ"],"a":1,"e":"ब्रिटिश सैन्य अधिकारी नेविल चेम्बरलेन ने 1875 में जबलपुर (म.प्र.) के ऑफ़िसर्स मेस में स्नूकर विकसित किया; बाद में ऊटी क्लब में इसके नियम बने।"},
    {"q":"लॉन टेनिस को 1873 में \"स्फ़ेरिस्टिके\" नाम से किसने आरंभ किया?","o":["विलियम वेब एलिस","जेम्स नाइस्मिथ","अब्नेर डबलडे","मेजर वॉल्टर विंगफ़ील्ड"],"a":3,"e":"मेजर वॉल्टर क्लॉप्टन विंगफ़ील्ड ने 1873 में यह खेल शुरू किया। जेम्स नाइस्मिथ ने 1891 में बास्केटबॉल का आविष्कार किया।"},
    {"q":"सूची-I (खेल) को सूची-II (जनक/आविष्कारक) से सुमेलित कीजिए —<br>(A) जूडो (B) बास्केटबॉल (C) वॉलीबॉल (D) लॉन टेनिस<br>1. जिगोरो कानो 2. विलियम जी. मॉर्गन 3. वॉल्टर विंगफ़ील्ड 4. जेम्स नाइस्मिथ","o":["A-1, B-4, C-2, D-3","A-4, B-1, C-2, D-3","A-1, B-2, C-4, D-3","A-1, B-4, C-3, D-2"],"a":0,"e":"जूडो — जिगोरो कानो, जापान 1882 (A-1); बास्केटबॉल — जेम्स नाइस्मिथ, 1891 (B-4); वॉलीबॉल — विलियम जी. मॉर्गन, 1895 (C-2); लॉन टेनिस — विंगफ़ील्ड, 1873 (D-3)।"},
    {"q":"अभिकथन (A): मिल्खा सिंह को \"उड़न सिख\" (फ़्लाइंग सिख) कहा जाता है।<br>कारण (R): 1960 में लाहौर की एक दौड़ में अब्दुल ख़ालिक़ को हराने के बाद पाकिस्तान के राष्ट्रपति अयूब ख़ान ने उन्हें यह उपाधि दी थी।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A और R सही, R ही उपाधि की उत्पत्ति है। मिल्खा की आत्मकथा \"द रेस ऑफ़ माई लाइफ़\" पर फ़िल्म \"भाग मिल्खा भाग\" (2013) बनी।"},
    {"q":"2020 में \"लॉरियस स्पोर्टिंग मोमेंट 2000–2020\" पुरस्कार किस भारतीय खिलाड़ी को मिला?","o":["विराट कोहली","सचिन तेंदुलकर","अभिनव बिंद्रा","एम. एस. धोनी"],"a":1,"e":"2011 विश्व कप जीत के बाद साथियों द्वारा सचिन को कंधे पर उठाकर वानखेड़े का चक्कर लगाने के क्षण (\"कैरीड ऑन द शोल्डर्स ऑफ़ अ नेशन\") को यह पुरस्कार मिला — लॉरियस पाने वाले पहले भारतीय।"},
    {"q":"अभिकथन (A): 1956 मेलबर्न ओलंपिक की घुड़सवारी स्पर्धाएँ स्वीडन के स्टॉकहोम में आयोजित की गईं।<br>कारण (R): ऑस्ट्रेलिया के कठोर पशु-क्वारंटीन नियमों के कारण विदेशी घोड़ों का प्रवेश कठिन था।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A और R सही, R ही कारण है — एकमात्र ओलंपिक जिसकी स्पर्धाएँ दो महाद्वीपों में हुईं।"},
    {"q":"अभिकथन (A): बीजिंग विश्व का पहला शहर है जिसने ग्रीष्मकालीन और शीतकालीन — दोनों ओलंपिक आयोजित किए।<br>कारण (R): टोक्यो ने 1964 और 2020 में दो ग्रीष्मकालीन ओलंपिक आयोजित किए।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — बीजिंग: 2008 ग्रीष्म, 2022 शीत। R सही — टोक्यो के दो ग्रीष्मकालीन ओलंपिक; पर R, A की व्याख्या नहीं करता।"},
    {"q":"अभिकथन (A): भारतीय पुरुष हॉकी टीम ने टोक्यो 2020 ओलंपिक में कांस्य पदक जीता।<br>कारण (R): यह 1980 मॉस्को के बाद ओलंपिक हॉकी में भारत का पहला स्वर्ण पदक था।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — कांस्य मैच में जर्मनी को 5-4 से हराया (41 वर्ष बाद ओलंपिक हॉकी पदक)। R गलत — यह कांस्य था, स्वर्ण नहीं; 1980 के बाद भारत ने हॉकी स्वर्ण नहीं जीता।"},
    {"q":"अभिकथन (A): ICC का मुख्यालय लंदन के लॉर्ड्स मैदान में स्थित है।<br>कारण (R): ICC की स्थापना 1909 में इंग्लैंड, ऑस्ट्रेलिया और दक्षिण अफ़्रीका ने की थी।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":3,"e":"A गलत — ICC का मुख्यालय 2005 से दुबई (UAE) में है; पहले लॉर्ड्स में था। R सही — 1909 में \"इंपीरियल क्रिकेट कॉन्फ़्रेंस\" के रूप में स्थापना।"},
    {"q":"अभिकथन (A): शतरंज ओलंपियाड 2024 (बुडापेस्ट) में भारत ने ओपन और महिला — दोनों वर्गों में स्वर्ण जीता।<br>कारण (R): शतरंज ओलंपियाड हर वर्ष आयोजित किया जाता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — 45वें ओलंपियाड में भारत का ऐतिहासिक दोहरा स्वर्ण। R गलत — ओलंपियाड सामान्यतः हर दो वर्ष में होता है।"},
    {"q":"अभिकथन (A): पेले को फ़ुटबॉल का महानतम खिलाड़ी माना जाता है।<br>कारण (R): विश्व कप में सर्वाधिक गोल करने का रिकॉर्ड पेले के नाम है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — पेले तीन विश्व कप (1958, 1962, 1970) जीतने वाले एकमात्र खिलाड़ी हैं। R गलत — पेले के 12 विश्व कप गोल हैं; सर्वाधिक गोल का रिकॉर्ड पहले मिरोस्लाव क्लोज़ (16) के नाम था और 2026 विश्व कप के बाद किलियन एम्बाप्पे (22) के नाम है।"},
    {"q":"अभिकथन (A): डेविस कप में भारत कभी विजेता नहीं बन सका।<br>कारण (R): भारत डेविस कप के फ़ाइनल में कभी नहीं पहुँचा।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — भारत ने डेविस कप कभी नहीं जीता। R गलत — भारत तीन बार (1966, 1974, 1987) फ़ाइनल में पहुँचा; 1966 व 1987 में हारा और 1974 में खेलने से इनकार किया।"},
    {"q":"अभिकथन (A): एशियाई खेलों का आदर्श वाक्य \"एवर ऑनवर्ड\" है।<br>कारण (R): पहले एशियाई खेल 1951 में टोक्यो में आयोजित हुए थे।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — यह वाक्य नेहरू ने दिया। R गलत — पहले एशियाई खेल 1951 में नई दिल्ली में हुए; टोक्यो ने 1958 में तीसरे खेल कराए।"},
    {"q":"किस ओलंपिक हॉकी फ़ाइनल में बलबीर सिंह (सीनियर) ने 5 गोल का रिकॉर्ड बनाया?","o":["1948 लंदन","1956 मेलबर्न","1936 बर्लिन","1952 हेलसिंकी"],"a":3,"e":"1952 के फ़ाइनल में भारत ने नीदरलैंड्स को 6-1 से हराया, जिसमें 5 गोल बलबीर सिंह (सीनियर) के थे — ओलंपिक हॉकी फ़ाइनल में किसी खिलाड़ी के सर्वाधिक गोल का रिकॉर्ड आज भी उनके नाम है।"},
    {"q":"ओलंपिक इतिहास में सर्वाधिक स्वर्ण पदक (23) जीतने वाले खिलाड़ी किस खेल से हैं?","o":["एथलेटिक्स","तैराकी","जिम्नास्टिक्स","साइक्लिंग"],"a":1,"e":"अमेरिकी तैराक माइकल फ़ेल्प्स ने 2004–2016 के बीच 23 स्वर्ण सहित 28 ओलंपिक पदक जीते। महिलाओं में सर्वाधिक पदक जिम्नास्ट लारिसा लैटिनिना (18) के हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. विंबलडन विश्व की सबसे पुरानी टेनिस प्रतियोगिता है, जो 1877 में आरंभ हुई।<br>2. चारों ग्रैंड स्लैम में केवल यूएस ओपन घास के कोर्ट पर खेला जाता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — 1877 में ऑल इंग्लैंड क्लब में आरंभ। कथन 2 गलत — घास के कोर्ट पर केवल विंबलडन खेला जाता है; यूएस ओपन व ऑस्ट्रेलियन ओपन हार्ड कोर्ट पर तथा फ़्रेंच ओपन क्ले कोर्ट पर।"},
    {"q":"पहला ICC अंडर-19 क्रिकेट विश्व कप (1988) किस देश ने जीता?","o":["पाकिस्तान","भारत","इंग्लैंड","ऑस्ट्रेलिया"],"a":3,"e":"1988 में ऑस्ट्रेलिया में हुए पहले अंडर-19 विश्व कप को ऑस्ट्रेलिया ने जीता। भारत ने पहली बार 2000 में (मोहम्मद कैफ़ की कप्तानी में) यह ख़िताब जीता।"},
    {"q":"भारतीय अंडर-19 क्रिकेट के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. भारत ने अंडर-19 विश्व कप पहली बार 2000 में मोहम्मद कैफ़ की कप्तानी में जीता।<br>2. 2008 का अंडर-19 विश्व कप विराट कोहली की कप्तानी में भारत ने जीता।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 2000 (श्रीलंका) में पहला ख़िताब। कथन 2 सही — 2008 (मलेशिया) में कोहली की कप्तानी में; भारत सर्वाधिक बार यह ख़िताब जीतने वाला देश है।"},
    {"q":"\"हॉकी का जादूगर\" कहे जाने वाले मेजर ध्यानचंद किस रेजिमेंट में सिपाही के रूप में भर्ती हुए थे?","o":["राजपूताना राइफ़ल्स","पंजाब रेजिमेंट (प्रथम ब्राह्मण रेजिमेंट)","गोरखा राइफ़ल्स","मद्रास रेजिमेंट"],"a":1,"e":"ध्यानचंद 1922 में 16 वर्ष की आयु में \"फ़र्स्ट ब्राह्मण्स\" रेजिमेंट (बाद में पंजाब रेजिमेंट का अंग) में भर्ती हुए; रात में चाँदनी में अभ्यास करने के कारण उन्हें \"चंद\" नाम मिला।"}
  ]
});
